(window.GIM_TP=window.GIM_TP||{})["Bava Kamma.1"]={"from":211,"a":[[["צריכין כפירה במקצת והודאה במקצת ואלו הן שומר חנם והשואל נושא שכר והשוכר","אמר רבא מאי טעמא דרמי בר חמא שומר חנם בהדיא כתיב ביה (שמות כב, ח) כי הוא זה שומר שכר יליף נתינה נתינה משומר חנם","שואל (שמות כב, יג) וכי ישאל וי\"ו מוסיף על ענין ראשון שוכר אי למ\"ד כשומר שכר היינו שומר שכר אי למ\"ד כשומר חנם היינו שומר חנם","וא\"ר חייא בר יוסף הטוען טענת גנב בפקדון אינו חייב עד שישלח בו יד מאי טעמא (שמות כב, ז) ונקרב בעל הבית אל האלהים אם לא שלח ידו במלאכת רעהו מכלל דאי שלח בה יד מיחייב למימרא דבשלח בה יד עסקינן","אמר להו ר' חייא בר אבא הכי א\"ר יוחנן בעומדת על אבוסה שנו א\"ל ר' זירא לר' חייא בר אבא דוקא בעומדת על אבוסה קאמר אבל שלח בה יד קנה ושבועה לא מהניא ביה כלום או דלמא אפי' עומדת על אבוסה קאמר","א\"ל זו לא שמעתי כיוצא בה שמעתי דא\"ר אסי א\"ר יוחנן הטוען טענת אבד ונשבע וחזר וטען טענת גנב ונשבע ובאו עדים פטור מ\"ט לאו משום דקנה בשבועה ראשונה","א\"ל לא הואיל ויצא ידי בעלים בשבועה ראשונה","איתמר נמי א\"ר אבין א\"ר אילעא א\"ר יוחנן הטוען טענת אבידה בפקדון ונשבע וחזר וטען טענת גניבה ונשבע ובאו עדים פטור הואיל ויצא ידי בעלים בשבועה ראשונה","אמר רב ששת הטוען טענת גנב בפקדון כיון ששלח בו יד פטור מאי טעמא הכי קאמר רחמנא ונקרב בעל הבית אל האלהים אם לא שלח ידו וגו' הא שלח ידו פטור","אמר ליה רב נחמן והלא שלש שבועות משביעין אותו שבועה שלא פשעתי בה שבועה שלא שלחתי בה יד שבועה שאינה ברשותי מאי לאו שבועה שלא שלחתי בה יד דומיא דשבועה שאינה ברשותי מה שבועה שאינה ברשותי כי מיגליא מילתא דאיתיה ברשותיה חייב אף שבועה שלא שלחתי בה יד כי מיגליא מילתא דשלח בה יד חייב","אמר ליה לא שבועה שלא שלחתי בה יד דומיא דשלא פשעתי בה מה שבועה שלא פשעתי בה כי מיגליא מילתא דפשע בה פטור מכפל אף שבועה שלא שלחתי בה יד כי מיגליא מילתא דשלח בה יד פטור מכפל","בעי רמי בר חמא ממון המחייבו כפל פוטרו מן החומש או דלמא שבועה המחייבתו כפל פוטרתו מן החומש","היכי דמי כגון שטען טענת גנב ונשבע וחזר וטען טענת אבד ונשבע"],[[0,"צריכין כפירה במקצת והודאה במקצת","קודם שיתחייבו שבועה ואם נשבעו בלא כפירה והודאה אין שבועתו של ש\"ח כלום ולא מחייבתו כפל ודרמי בר חמא פליג אדרבי חייא בר יוסף:"],[2,"פרשה ראשונה","נאמרה בש\"ח ושניה בשומר שכר:"],[2,"שוכר","פלוגתא דר\"מ ורבי יהודה לעיל (בבא קמא דף נז:):"],[3,"אינו חייב","כפל:"],[3,"עד שישלח בה יד","קודם שבועה כגון שעשה בה מלאכה:"],[3,"ה\"ג","דאמר קרא ונקרב בעל הבית אל האלהים אם לא שלח:"],[3,"למימרא","דהאי דכתיב בתריה אשר ירשיעון אלהים וגו':"],[3,"בששלח בה יד עסקינן","דנמצא רשע בכך שנשבע לשקר שהרי שלח בה יד:"],[4,"בעומדת על אבוסה","שלא שלח בה יד שנו דחייב כפל:"],[4,"אבל שלח בה יד","קודם שבועה קנאה בתורת גזילה ושומר חנם אינו נעשה גנב אלא בטענת גנב וזה קודם שטען טענת גנב קנאה וקמה ליה ברשותיה שאם מתה ישלמנה ואשתכח דכי כפר דידיה קא כפר:"],[4,"או דלמא אפילו עומדת על אבוסה קאמר","וכל שכן כי שלח בה יד דבהכי קאי קרא כדאמר ר' חייא בר יוסף:"],[5,"הטוען טענת אבידה ונשבע","ל\"ג והודה:"],[5,"פטור","מן הכפל:"],[5,"מ\"ט לאו משום דקנה בשבועה ראשונה","להתחייב באונסין כדרב ששת דאמר לעיל הכופר בפקדון נעשה עליו גזלן אפי' בלא שבועה והיכא דאשתבע כל שכן דכ\"ע מודו אלמא כיון דקמה ליה ברשותיה כי כפר דידיה קא כפר ולא מיחייב ליה כפל וה\"ה לשולח בה יד כיון דפשיטא לן בפ' המפקיד (ב\"מ מא:) דקמה ליה ברשותיה תו לא מיחייב עליה כפל:"],[6,"לא","התם לאו משום דקמה ליה ברשותיה הוא אלא הואיל ויצא שומר זה ידי בעלים בשבועה ראשונה שמבית דין ראשון נסתלק מידם ושבועה אחרונה זו לאו שבועת הדיינים הוא לחייבו כפל דכיון דנשבע בתחילה שוב לא היה מחויב שבועה לבעלים:"],[8,"כיון ששלח בה יד","קודם שבועה:"],[8,"ה\"ק אם לא שלח","ונקרב בעל הבית וקיימא לן בהמפקיד (שם) דהאי ונקרב לשבועה הוא וכתיב בתריה ישלם שנים אם נמצא רשע:"],[8,"הא שלח יד פטור","מכל הדין הזה:"],[9,"שלש שבועות משביעין","את שומר חנם האומר נגנבה:"],[9,"שבועה שלא פשעתי","בשמירתו כשנגנבה דאי פשע בה חייב דכתיב על כל דבר פשע:"],[9,"שבועה שלא שלחתי בה יד","ליהנות בה קודם לכן דאם שלח בה יד קמה ליה ברשותיה דנעשה גזלן עליה ומיחייב באונסין וכ\"ש בגניבה ואבידה:"],[10,"כי מגליא מילתא דפשע בה","ונגנבה:"],[10,"פטור מכפל","דהא אינו גנב עליה:"],[10,"אף שבועה דשלח בה יד כי מגליא מילתא דשלח בה יד פטור מכפל","אפילו עדיין היא אצלו:"],[11,"בעי רמי בר חמא","דקיימא לן בפרק מרובה (לעיל בבא קמא דף סה:) ממון שאין משתלם בראש דאיכא כפל בהדיה אין מוסיף חומש ולעיל (בבא קמא דף קו.) נמי תנינן לה אם משבאו עדים הודה משלם תשלומי כפל ואשם אבל חומש לא מאן פטר ליה מחומשא ממונא או שבועה:"],[12,"והיכי דמי","כלומר למאי נ\"מ כגון שטען טענת גנב כו':"]],[[3,"עד שישלח בו יד","והא דקתני לעיל (בבא קמא דף קו.) והעדים מעידים אותו שגנבו משלם תשלומי כפל היינו ששלח בו יד:"],[6,"הואיל ויצא ידי בעלים בשבועה ראשונה","דאע\"ג שהודה שלשקר נשבע אין חייב מן הדין לישבע פעם שניה שנגנב כמו שחוזר וטוען אלא נאמן שלא בשבועה לומר שנגנב במגו דאי בעי אמר באמת נשבעתי והיה פטור והא קמ\"ל אע\"ג. שמושבע מפי ב\"ד כגון שטענו בפני ב\"ד אחר שלא היו יודעים שנשבע כבר קודם והשביעוהו עתה דפטור כיון שמן הדין לא היה לו לישבע:"],[8,"ושלח בו יד פטור","והא דאמר לעיל והעדים מעידים אותו שאכלו משלם תשלומי כפל צ\"ל כגון שאכלו לאחר שבועה ונראה דדוקא קאמר ושלח דגזירת הכתוב היא כדקאמר אם לא שלח הא שלח פטור אבל כופר בפקדון אע\"ג דאמר רב ששת לעיל הכופר בפקדון נעשה עליו גזלן כפל מיהא מחייב דהא דקאמר נעשה עליו גזלן היינו להתחייב באונסין:"],[9,"והלא שלש שבועות משביעין אותו","וצריך כולהו דאי נשבע שלא פשעתי אכתי חיישינן שמא ברשותו הוא ובאמת נשבע וכשנשבע שאינה ברשותו איכא למיחש שמא שלח בה יד ומתחייב אע\"פ שלא פשע ואינה ברשותו:"],[9,"מאי לאו שלא שלחתי כו'","ה\"נ ה\"מ לאותובי לרבי חייא ב\"ר יוסף ולימא מאי לאו [שלא] שלחתי דומיא דלא פשעתי ולשנויי לא דומיא דאין ברשותי:"],[10,"מה שבועה שלא פשעתי בה כי מגליא מילתא דפשע בה פטור","דהא מהכא דרשינן טוען טענת גנב מדכתיב אם לא ימצא הגנב אלא הוא עצמו גנבו וזה שפשע בה לא גנבו:"],[12,"כגון שטוען טענת גנב וחזר וטען טענת אבד","ואיפכא לא מצי למימר דאם כן לא מיחייב כפל כדאמר לעיל שכבר יצא ידי בעלים בשבועה ראשונה והכי פירושו וחזר וטען טענת אבד ואומר מה שנשבעתי שנגנב לא כי אלא אבד והיה לי לישבע שאבד אבל אין לפרש שאמר אחר שבועה אבד שא\"כ לא ה\"מ למפטר נפשיה באבד כיון שהיא ברשותו בשעה שנשבע דאההיא שעה שנשבע לשקר מתחייב באונסין ולא מחייב אהך שבועה חומש ואשם דלא הויא כפירת ממון אלא כשבועת ביטוי בעלמא:"]]],[["ובאו עדים אקמייתא והודה אבתרייתא מאי","ממון המחייבתו כפל פוטרו מן החומש והא איחייב ליה עילויה כפילא או דלמא שבועה המחייבתו כפל פוטרתו מן החומש והא שבועה בתרייתא הואיל דלא קא מחייבא ליה כפילא תחייביה חומשא","אמר רבא ת\"ש אמר לאחד מן השוק היכן שורי שגנבת והוא אומר לא גנבתי משביעך אני ואמר אמן והעדים מעידים אותו שגנבו משלם תשלומי כפל ואם הודה מעצמו משלם קרן וחומש ואשם","והא הכא עדים הוא דמחייבי ליה כפילא הודה מעצמו אין אבל הודה אחר עדים לא","ואי סלקא דעתך שבועה המחייבתו כפל פוטרתו מן החומש אמאי הודה אחר עדים לא מכדי הא שבועה לא קא מיחייבא ליה כפילא תחייביה חומשא","אלא לאו שמע מינה ממון המחייבו כפל פוטרתו מן החומש ש\"מ","בעי רבינא חומש וכפילא בתרי גברי מאי היכי דמי כגון שמסר שורו לשני בני אדם וטענו בו טענת גנב חד נשבע והודה וחד נשבע ובאו עדים מאי","מי אמרינן בחד גברא קפיד רחמנא דלא משלם חומשא וכפילא האי נשלם כפילא והאי נשלם חומשא או דלמא עלויה חד ממונא קפיד רחמנא דלא נשלם עלה חומשא וכפילא והכא נמי חד ממונא הוא תיקו:","בעי רב פפא תרי חומשי או תרי כפילי בחד גברא מאי היכי דמי שטען טענת אבד ונשבע והודה וחזר וטען טענת אבד ונשבע והודה אי נמי כגון שטען טענת גנב ונשבע ובאו עדים וחזר וטען טענת גנב ונשבע ובאו עדים מאי","מי אמרינן תרי גווני ממונא קאמר רחמנא דלא נשתלמו עילוי חד ממונא והכא חד גוונא הוא או דלמא תרי ממונא אמר רחמנא דלא לשתלמו עילוי חד ממונא והכא נמי תרי ממונא נינהו","תא שמע דאמר רבא (ויקרא ה, כד) וחמישיתו יוסיף עליו התורה ריבתה חמישיות הרבה לקרן אחת שמע מינה:","תבעוהו בעלים לשומר ונשבע ושילם והוכר הגנב כפל למי אביי אמר לבעל הפקדון רבא אמר למי שהפקדון אצלו","אביי אמר לבעל הפקדון כיון דאטרחיה בשבועה לא מקני ליה כפילא רבא אמר למי שהפקדון אצלו כיון דשילם מקני ליה כפילא","וקא מיפלגי בדיוקא דמתניתין דתנן המפקיד אצל חבירו בהמה או כלים ונגנבו או שאבדו שילם ולא רצה לישבע שהרי אמרו שומר חנם נשבע ויוצא נמצא הגנב משלם תשלומי כפל טבח ומכר משלם תשלומי ארבעה וחמשה למי הוא משלם למי שהפקדון אצלו","נשבע ולא רצה לשלם ונמצא הגנב משלם תשלומי כפל טבח ומכר משלם תשלומי ארבעה וחמשה למי הוא משלם לבעל הפקדון","אביי דייק מרישא רבא דייק מסיפא אביי דייק מרישא דקתני שילם ולא רצה לישבע טעמא דלא רצה לישבע"],[[0,"ובאו עדים","דכשנשבע היתה אצלו לחייב כפל והדר הודה איהו אבתרייתא:"],[0,"מאי","מיחייב חומש אהך שבועה בתרייתא או לא:"],[1,"והא איחייב ליה כפילא","עליה דהאי ממון:"],[1,"או דלמא שבועה המחייבתו כפל פוטרתו מן החומש","כגון אי הוה מודה השתא אקמייתא אחר העדאת עדים הוה מיפטר מחומש אבל השתא דאבתרייתא אודי והך שבועה לא חייבתיה כפילא תחייביה חומשא והכא ליכא למימר יצא ידי בעלים בשבועה ראשונה דכי אמרינן ליה היכא דאתו סהדי אשבועה שניה דאמרינן אשבועת חנם לא מחייבי כפילא אבל היכא דאודי עלה קיימא לן לעיל (בבא קמא דף קו.) השביע עליו חמשה פעמים כו' דלענין חומש ואשם לא שני ליה בין שבועת עצמו לשבועת דיינין ובלבד שיכפור ממון:"],[2,"אמר לאחד מן השוק","שאין שומר על שורו:"],[2,"משביעך אני","משום הודה מעצמו דסיפא נקט אבל משום כפל בלאו שבועה נמי מיחייב:"],[8,"תרי חומשי או תרי כפילי בחד גברא מאי","הכי גרסינן:"],[10,"לקרן אחת","אם כפר וחזר וכפר וה\"ה לתרין כפילי:"],[11,"תבעוהו בעלים לשומר חנם ונשבע","שנגנבה ונפטר ואח\"כ שילם לפנים משורת הדין:"],[12,"כיון דאטרחיה","שומר לבעלים עד שהביאוהו לבית דין ונשבע אע\"ג דהדר שילם לא מקנו ליה בעלים לשומר כפילא בשעת תשלומים:"],[13,"שהרי אמרו וכו'","ויכול היה ליפטר בשבועה:"]],[[0,"ובאו עדים אקמייתא","תימה דע\"כ כשבאו עדים אקמייתא ואומרים באותה שעה ראינוהו ברשותו ונמצא שמכחישין גם שבועה שניה שנשבע שאבד וכשהודה אחר עדים אמאי משלם חומש הא קתני לעיל בברייתא דהיכן פקדוני כו' הודה מעצמו משלם קרן וחומש משמע דוקא הודה מעצמו אבל אחר עדים לא ויש לומר דלעולם בטענת אבד הודה לאחר עדים נמי משלם חומש כדמשמע בסמוך דקאמר מכדי האי שבועה לא מחייבא ליה כפל תחייביה חומש אלא שמע מינה ממון המחייבו כפל פוטרו מן החומש משמע הא היכא דליכא כפל בהעדאת עדים כמו בטענת אבד דמתחייב חומש בהודה אחר עדים ולעיל לאו דוקא נקט מעצמו אלא הוא הדין אחר עדים ואיידי דתנא בסיפא הודה מעצמו גבי טוען טענת גנב תנא נמי ברישא:"],[6,"חד [נשבע] והודה וחד [נשבע] ובאו עדים","נראה דוקא נקט מתחילה הודה דאי מתחילה כפר חד ובאו עדים ואח\"כ הודה חד הוו עדים קודמין להודאה ומחייבין תרוייהו כפילא דעדים כשבאו להעיד על שניהם העידו אבל כשהודה חד קודם אע\"פ שאח\"כ באו עדים יש לומר דפטור והכי משמע בכולה הך שמעתא דמודה בקנס ואח\"כ באו עדים דפטור:"],[8,"ותרי כפילי","מחמת שנעשה פסול בשבועה שניה משעה שנמצא שקרן בראשונה אין לפוטרו משום דחשוד על השבועה מדרבנן הוא דמיפסל כדמוכח בשבועות (דף מה.) דקתני ושכנגדו חשוד על השבועה ומשמע התם דמדרבנן הוא וכיון דמדאורייתא שבועתו שבועה מחייב כפל:"],[8,"טען טענת אבד ונשבע והודה וחזר וטען טענת אבד","נראה דל\"ג והודה דאם הודה מיד הויא ברשותו להתחייב באונסים משעה שנשבע לשקר ומה שיחזור ויטעון שוב אבד אין כופר כלום ואפי' אמר לאחר שבועה אבד אלא נראה דלא הודה אלא לאחר שבועה שניה ומיהו תימא מאי קמבעיא ליה לרב פפא הא מתניתין היא דמייתי לעיל (בבא קמא דף קו.) השביע עליו ה' פעמים בין בפני ב\"ד בין שלא בפני ב\"ד וכפר עליו חייב על כל אחת ואחת:"],[8,"וחזר וטען טענת גנב ונשבע","תימה היאך השביעוהו בית דין כיון שנפטר בבית דין בשבועה ראשונה ואפילו חזר וטען שלאחר שבועה ראשונה נגנב מ\"מ למה השביעוהו והלא משבועה ראשונה שנשבע לשקר חייב באונסים נמצא שלא כפר כלום במה שטען שנגנב אחר שבועה ראשונה ואין לומר שבאו לפני בית דין אחר שלא ידעו שכבר נפטר והשביעוהו וכיון שנשבע על פי בית דין (אע\"ג) שלא ידעו מיחייב כפל והא דאמרינן לעיל שכבר יצא בשבועה ראשונה היינו שאותו בית דין עצמו השביעוהו וטעו דאין סברא לחלק כלל ונראה דמיירי דאמר ליה בעל הפקדון שוב לאחר שנמצא שקרן בשבועה ראשונה רצוני שתהא עליו שומר חנם כבתחילה וחזר וטען לאחר שעשיתני שומר חנם נגנב ופוטר עצמו שהרי לא נתחייב באונסין במה שעשאו בפירוש ש\"ח אבל תימה דא\"כ לא הוי חד ממונא דהשתא הפקידו אצלו פעם שניה ומה לי לקחו בידו ונתן לו ומ\"ל שלא לקחו אלא אמר ליה בעודו בידו תהא עליו שומר חנם:"],[11,"רבא אמר למי שהפקדון אצלו","וא\"ת דהכא סבר רבא דאע\"ג דאטרחיה לבי דינא מקני ליה כפילא ובפרק המפקיד (ב\"מ דף לה.) גבי ההוא גברא דאפקיד כיפי גבי חבריה קאמר רבא שפיר עבד דלא אהדר ליה הכא אטרחיה לבי דינא התם לא אטרחיה לבי דינא ויש לומר דהתם שאני דאטרחיה לבי דינא ולא פרע ליה מידי אלא רב נחמן אגבייה לאפדנא מיניה אבל הכא אע\"ג דאטרחיה לבי דינא קצת שנשבע לו תחילה מכל מקום הרי שילם לו לבסוף ולא אטרח בי דינא הלכך מקני ליה כפילא:"],[12,"","רבא אמר למי שהפקדון אצלו. וא\"ת דהכא סבר רבא דאע\"ג דאטרחיה לבי דינא מקני ליה כפילא ובפרק המפקיד (ב\"מ דף לה.) גבי ההוא גברא דאפקיד כיפי גבי חבריה קאמר רבא שפיר עבד דלא אהדר ליה הכא אטרחיה לבי דינא התם לא אטרחיה לבי דינא ויש לומר דהתם שאני דאטרחיה לבי דינא ולא פרע ליה מידי אלא רב נחמן אגבייה לאפדנא מיניה אבל הכא אע\"ג דאטרחיה לבי דינא קצת שנשבע לו תחילה מכל מקום הרי שילם לו לבסוף ולא אטרח בי דינא הלכך מקני ליה כפילא:"]]],[["הא נשבע אע\"פ ששילם למי משלם לבעל הפקדון","רבא דייק מסיפא נשבע ולא רצה לשלם טעמא דלא רצה לשלם הא שילם אע\"פ שנשבע למי משלם למי שהפקדון אצלו","לאביי קשיא סיפא אמר לך אביי הכי קתני נשבע ולא רצה לשלם קודם השבועה אלא לאחר השבועה למי משלם לבעל הפקדון לרבא קשיא רישא אמר לך רבא הכי קתני שילם ולא רצה לעמוד בשבועתו אלא שילם למי משלם למי שהפקדון אצלו","תבעוהו בעלים לשומר ונשבע והוכר הגנב תבעו שומר והודה תבעוהו בעלים וכפר והביאו עדים מי נפטר הגנב בהודאת שומר או לא נפטר הגנב בהודאת שומר","אמר רבא אם באמת נשבע נפטר הגנב בהודאת שומר אם בשקר נשבע לא נפטר הגנב בהודאת שומר","בעי רבא עמד לישבע בשקר ולא הניחוהו מהו תיקו רב כהנא מתני הכי רב טביומי מתני בעי רבא נשבע לשקר מהו תיקו","תבעוהו בעלים לשומר ושילם והוכר הגנב תבעוהו בעלים והודה תבעו שומר וכפר והביא עדים נפטר גנב בהודאת בעלים או לא","מי אמרינן מצי אמר ליה שומר לבעלים אתון כיון דשקליתו לכו דמי אסתליקתו לכו מהכא או דלמא מצי אמרי ליה כי היכי דאת עבדת לן מילתא אנן נמי עבדינן לך טרחינן בתר גנבא שקלנא אנן דידן ושקול את דידך תיקו","אתמר נגנבה באונס והוכר הגנב אמר אביי אם שומר חנם הוא רצה עושה עמו דין רצה נשבע אם שומר שכר הוא עושה עמו דין ואינו נשבע רבא אמר אחד זה ואחד זה עושה עמו דין ואינו נשבע","לימא פליגא אדרב הונא בר אבין דשלח רב הונא בר אבין נגנבה באונס והוכר הגנב אם שומר חנם הוא רצה עושה עמו דין רצה נשבע ואם שומר שכר הוא עושה עמו דין ואינו נשבע","אמר לך רבא הכא במאי עסקינן כגון שקדם ונשבע והא רצה עושה עמו דין רצה נשבע קאמר הכי קאמר רצה שומר חנם עומד בשבועתו רצה עושה עמו דין","רבה זוטי בעי לה הכי נגנבה באונס והחזיר גנב בבית שומר ומתה בפשיעה מהו מי אמרינן כיון דנגנבה באונס כליא ליה שמירתו או דלמא כיון דהדרה הדרה לשמירתו תיקו:","\u0001מתני׳\u0002 היכן פקדוני אמר לו אבד משביעך אני ואמר אמן והעדים מעידים אותו שאכלו משלם קרן [הודה מעצמו משלם קרן וחומש ואשם]","היכן פקדוני אמר לו נגנב משביעך אני ואמר אמן והעדים מעידים אותו שגנבו משלם תשלומי כפל הודה מעצמו משלם קרן חומש ואשם","הגוזל את אביו ונשבע לו ומת הרי זה משלם קרן וחומש ואשם לבניו או לאחיו ואם אינו רוצה או שאין לו לוה ובעלי חוב באין ונפרעים","האומר לבנו קונם אי אתה נהנה משלי אם מת ירשנו"],[[0,"הא נשבע אע\"פ ששילם","כיון דאטרחיה בשבועה למי משלם גנב כפל לבעל הפקדון כטעמיה דאביי דלעיל:"],[3,"מי נפטר הגנב","מן הכפל כשאר מודה בקנס:"],[3,"בהודאה","שהודה לשומר:"],[3,"או לא נפטר","דכיון דנשבע שומר תחילה נסתלק ושוב אינה בשמירתו ולא הויא הודאה:"],[4,"אם באמת נשבע","השומר שטען נגנבה באונס ונמצא כן:"],[5,"ולא הניחוהו מאי","מדלא נשבע נאמן הוא עדיין לבעלים או דלמא כיון דעמד לישבע תו לא מהימני ליה בעלים:"],[5,"נשבע לשקר מהו","מי אמרינן אכתי עליה רמיא דכיון דלשקר נשבע סופו להתחרט ולשלם הלכך תביעתו תביעה או לא:"],[5,"אית דגרס אם באמת נשבע","דלא פשע לא נפטר הגנב דכיון דבאמת נשבע אפטר ליה שומר ותו לא רמיא עליה למתבעיה לגנב ואם לשקר נשבע כגון דפשע נפטר הגנב בהודאת שומר דאכתי עליה רמיא לשלומי וראשון שמעתי ועיקר הוא. דהכא איכא לאקשויי א\"כ מאי בעי רבא עמד לישבע לשקר ולא הניחוהו מהו השתא נשבע ממש דאסתלק ליה מבי דינא דתו לא רמיא עליה לא שבועה ולא פרעון עד שיבאו עדים שפשע אמרינן דנפטר הגנב דאכתי אשומר רמיא למתבעיה כל שכן היכא דלא נשבע דעליה רמיא לשלומי:"],[7,"את עבדת לן מילתא","טובה ששילמת לפנים משורת הדין הלכך על דידן נמי רמיא למיעבד מילתא דטיבותא לאהדורי בתר גנבא ולמתבעיה ותביעתן תביעה:"],[8,"נגנבה באונס","בלסטים מזויין דשומר שכר פטור בו ואח\"כ הוכר הגנב ויכול לכופו ולהוציא מידו:"],[8,"רצה נשבע","והבעלים יפרעו מן הגנב:"],[8,"עושה עמו דין","משלם לבעלים והוא יפרע מן הגנב:"],[8,"ואם שומר שכר הוא","אע\"ג דפטור בלסטים מזויין הכא הואיל והוכר הגנב ולא יפסיד כלום עליו לטרוח אחריה לפיכך הוא ישלם לבעלים ויחזור ויפרע מן הגנב:"],[8,"עושה עמו דין","ישלם דמצוה עליו לחזר אחר האבידה:"],[9,"לימא פליגא","דרבא אדרב הונא בר אבין:"],[10,"כגון שקדם ונשבע","קודם שהוכר הגנב:"],[12,"מתני' משלם קרן","דאין חומש ואשם אלא אם הודה דכתיב בגזל הגר בפרשת נשא והתוודה:"],[14,"הרי זה משלם קרן וחומש לבניו","של אביו או לאחיו של אביו אם אין לו בנים ואף על גב דנפלה ירושה קמיה דהאיך בעי למעבד השבה ואין מעכב אפילו כנגד חלקו:"],[14,"אין לו","נכסים כל כך שיכול לוותר על חלקו או שאין רוצה להפסיד חלקו:"],[14,"לוה","מאחרים ומשיב לאחיו לקיים מצות השבה:"],[14,"ובעלי החוב באין ונפרעין","מן ההשבה את חלקו כגון אם היו שנים אחין והוא שלישי נפרעים בעלי חובים מן (ההשבה שליש החוב) והשאר יגבו ממנו:"]],[[3,"תבעו שומר והודה תבעוהו בעלים והביא עדים","משמע דהודה לאחר שאין בעל הדבר דלא הויא הודאה ותימה אמאי לא בעי לענין קרן גופיה בשלא באו עדים אי הויא הודאה אי לאו ואמאי נקט והביא עדים משמע דלא מבעיא אלא לענין כפל וי\"ל דמשום דאקרן לא הוי מצי למיפשט הא דפשיט אם בשקר נשבע לא נפטר הגנב כו':"],[5,"ולא הניחוהו מהו","הקשה בקונט' אהך גירסא דגרסינן אם באמת נשבע לא נפטר גנב וכו' דא\"כ מאי בעי רבא עמד לישבע לשקר ולא הניחוהו מהו השתא נשבע לשקר ממש דאיסתליק ליה מבי דינא דתו לא רמיא עליה כ\"ש היכא דלא נשבע דעליה רמיא לשלומי ויש מתרצים דכיון (דלא הניחוהו לישבע מחל לו והרי נפטר נמי שומר כאילו) שומר נשבע באמת ותו לא רמיא עליה ולהכי קבעי ולאו מילתא היא דמשום דלא הניחוהו לישבע לא מחל לו ולא מיפטר שומר בהכי וכן פוסק בה\"ג דאע\"פ שמחל לו השבועה לנתבע בשביל כך לא מחל לו ממון לגמרי וכל שכן היכא דלא מחל לו שבועה אלא שלא הניחו לישבע באותה שעה:"],[8,"נגנבה באונס","נראה דאין שום גניבה קרויה אונס אלא בלסטים מזויין כדפירש בקונט' וכן מוכח לעיל בהכונס (בבא קמא דף נז.):"],[14,"לבניו או לאחיו","נראה לבניו של גזלן או לאחיו של גזלן כלומר בתחילה לבניו אם יש לו דהם קודמים לכל אדם בחלק המגיעו ונחשב אותו כאילו מת הוא והרי בניו יורשים חלקו עם אחיו והם אין באים מכחו אלא מכח אבוה דאבא כדאמר בסוף מי שמת (ב\"ב דף קנט.) תחת אבותיך יהיו בניך הלכך אע\"פ שאין לאביהן בהן כלום שהרי יש לו להחזיר גזילה אפ\"ה הם קודמין בחלקו מההוא טעמא דב\"ב או לאחיו כשאין לו בנים:"],[14,"לוה וב\"ח באין ונפרעין","נראה לפרש לוה על הקרקע שלו מאחרים אפי' בלא אפותיקי דקרקע משועבד לבעל חוב ואח\"כ נותן קרקע שלו לבניו או לאחיו בעבור הגזילה וכגון שאין הגזילה קיימת וחוזרים ב\"ח ונפרעין מאותה קרקע אע\"ג דיש לו שאר נכסים במה לפרוע ונראה דאין צריך לומר בשעת נתינתו לבניו או לאחיו ע\"מ שיפרעו בעלי חוב מכם דבלאו הכי אין יכולין לזכות שלא מדעתו ואם הגזילה בעין צריך לפרש שילוה עליה או יעשנה אפותיקי למלוה ויחזירנה לבניו או לאחיו ויחזור ויטרפנה מהם ב\"ח אע\"ג דאמרינן לעיל (בבא קמא דף יא:) עשה שורו אפותיקי ומכרו אין ב\"ח גובה הימנו היינו דוקא מכרו דכיון דליכא קלא לא אפסדינא ללקוחות אבל נתנו במתנה דלא שייך פסידא דלקוחות ב\"ח. גובה הימנו דאין יכול ליתן מה שמשועבד לאחרים אבל לא עשאו אפותיקי לא היה ב\"ח חוזר וטורף מהם דכי היכי דמטלטלי דיתמי לא משתעבדי לב\"ח ה\"נ לא משתעבדי מטלטלי דמקבל מתנה לבעל חוב והוי כאילו נותן להם במתנה כיון שהוא עצמו אינו יכול לחזור ולטרוף מהן ומיהו נראה דלא חשיב הכא מה שמחזיר להן כאילו נתן להם דאינו נותן להם לשם מתנה אלא סתמא בשתיקה מחזיר להם ואין דעתו אלא לקיים מצות השבה בעלמא הלכך לא הויא מתנה ויכול ב\"ח לטרוף מהם והוא ודאי אינו יכול לחזור וליקח מהן דאז לא היתה מתקיים השבה כלל אם היה לוקח בעצמו מה שנתן אבל מה שב\"ח נוטל מתקיימא שפיר מצות השבה כיון שבעצמו אין נוטל ומיירי אפי' בלא אפותיקי:"]]],[["בחייו ובמותו אם מת לא ירשנו ויחזיר לבניו או לאחיו ואם אין לו לוה ובעלי חוב באים ונפרעים:","\u0001גמ׳\u0002 אמר רב יוסף אפילו לארנקי של צדקה אמר רב פפא וצריך שיאמר זה גזל אבי","אמאי נמחליה לנפשיה מי לא תנן מחל לו על הקרן ולא מחל לו על החומש אלמא בר מחילה הוא","אמר רבי יוחנן לא קשיא הא רבי יוסי הגלילי הא רבי עקיבא","דתניא (במדבר ה, ח) ואם אין לאיש גואל להשיב האשם וכי יש אדם בישראל שאין לו גואלים אלא בגזל הגר הכתוב מדבר","הרי שגזל הגר ונשבע לו ושמע שמת הגר והיה מעלה כספו ואשמו לירושלים ופגע באותו הגר וזקפו עליו במלוה ומת זכה הלה במה שבידו דברי רבי יוסי הגלילי ר' עקיבא אומר אין לו תקנה עד שיוציא גזילו מתחת ידו","לרבי יוסי הגלילי לא שנא לנפשיה ל\"ש לאחרים מצי מחיל ולרבי עקיבא ל\"ש לאחרים ולא שנא לנפשיה לא מצי מחיל","ולר' יוסי הוא הדין דאפי' לא זקפו במלוה והאי דקתני זקפו עליו במלוה להודיעך כחו דרבי עקיבא דאפילו זקפן עליו במלוה אין לו תקנה עד שיוציא גזילה מתחת ידו","מתקיף לה רב ששת אי הכי לרבי יוסי הגלילי לשמעינן לנפשיה וכל שכן לאחרים לרבי עקיבא לשמעינן לאחרים דלא מצי מחיל וכ\"ש לנפשיה דלא מצי מחיל","אלא אמר רב ששת הא והא רבי יוסי הגלילי כי קאמר רבי יוסי הגלילי דמצי מחיל לאחרים אבל לנפשיה לא מצי מחיל אלא אמאי זכה הלה במה שבידו משום דזקפן עליו במלוה","רבא אמר הא והא רבי עקיבא כי אמר רבי עקיבא דלא מצי מחיל לנפשיה אבל לאחרים מצי מחיל"],[[0,"בחייו ובמותו","אם מת לא ירשנו:"],[0,"ואם אין לו","מה יאכל לוה ואוכל ובעלי חוב באין ונפרעין מן הירושה את חלקו:"],[1,"גמ' ואפי' לארנקי של צדקה","אם אינו מוצא יורש לאביו למי ישיב יתן אותה לארנקי של צדקה ולא יעכבנו בידו:"],[1,"וצריך שיאמר","כשהוא משיב לארנקי של צדקה זה גזל אבא:"],[2,"ונמחליה לנפשיה","היכא דאין יורש אלא הוא וכולה שלו:"],[2,"מי לא תנן מחל לו על הקרן","ולא מקיימא מצות השבה אלמא למיפק ידי גזילה בעינן והא נפקא ליה במחילה הכא נמי כיון דירושה קמיה נפלה נפק ליה מידי גזילה:"],[4,"להשיב האשם","זה קרן של גזילה כדתניא לקמן בפרקין (בבא קמא דף קי.):"],[4,"גואל","יורש:"],[4,"וכי יש לך אדם בישראל שאין לו גואלים","אם אין לו בן או בת או אח יש לו קרוב עד יעקב אבינו הקרוב קרוב יורש:"],[4,"אלא בגזל הגר","ונשבע לשקר דכתיב למעול מעל בה':"],[5,"והיה מעלה כספו ואשמו לירושלים","לכהנים כדכתיב האשם המושב לה' לכהן ואמרינן לקמן בשמעתין אשם זה קרן:"],[5,"וזקפו עליו","גר במלוה נפק ליה מתורת גזילה ולכי מיית גר הוה ליה האי מוחזק וזכה מן ההפקר:"],[6,"לא שנא לנפשיה","כגון הכא דמחיל ליה האי גברא גזל הגר לנפשיה וה\"ה גוזל את אביו ונשבע לו ומת אביו דמחיל לנפשיה:"],[6,"ול\"ש לאחרים","נגזל לגוזל מצי מחיל ומתני' דקתני מחל לו על הקרן רבי יוסי הגלילי היא ואשמעינן לאחרים וה\"ה לנפשיה היכא דנפק מידי גזילה כגון יורש או גזל הגר וקס\"ד האי זקפו לאו דוקא כדמפרש ואזיל:"],[6,"לר' עקיבא לא שנא כו'","ומתני' דקתני משלם קרן וחומש לבניו או לאחיו ר' עקיבא היא ולאשמועינן לנפשיה דלא מצי מחיל וה\"ה לאחרים דאפילו מחיל ליה נגזל גופיה לאו מחילה היא:"],[7,"ה\"ה אפי' לא זקפן","הלכך יורש את אביו נמי אע\"ג דלא זקפו עליו במלוה ולא יצא מתורת גזילה בחיי אביו כיון דמת אביו ונפלו נכסים לפניו מחיל לנפשיה ולקמן (בבא קמא קט ע\"ב) פריך א\"כ גזל הגר דנפיק לכהנים היכי משכחת לה:"],[9,"הא והא ר' יוסי","הא דאמר בזקפו במלוה דכיון דאפקה גר גופיה דהוה נגזל מתורת גזילה דהוי כמוחל לאחרים הוי מחילה ולכי מיית קנייה האי הלכך מחל לו על הקרן דמתני' ר' יוסי היא דאי לרבי עקיבא בעי השבה משלו כדקתני אין לו תקנה עד שיוציא גזילה וסיפא נמי רבי יוסי היא דמודי רבי יוסי לנפשיה דלא מצי מחיל כיון דלא אפקיה נגזל מתורת גזילה:"],[10,"רבא אמר הא והא רבי עקיבא","דלרבי יוסי לנפשיה נמי מצי מחיל דזקפו לאו דוקא וכי אמר רבי עקיבא דלא מצי מחיל לנפשיה הוא דקאמר דאע\"ג דגר זקפו כיון דלא מחיל מחילה גמורה לא נפקא ליה מתורת גזילה אבל נגזל לגזלן מודה ר' עקיבא דמחיל:"]],[[0,"ב\"ח באין ונפרעין","אחר מיתה ואפילו בחייו הוי שרי בכה\"ג כדאמרינן (נדרים דף מג.) המודר הנאה מחבירו ואין לו מה יאכל ילך אצל חנוני הרגיל אצלו ויאמר לו איש פלוני מודר הנאה ממני ואין לו מה יאכל ואיני יודע מה אעשה לו נותן לו ובא ונוטל מזה אלא לפי שזה אין רוצה שיהנה ממנו כלל בחייו ואין יכול לעשות תקנה אלא מדעתו והא דלא תני הכא ואם אין רוצה כדקתני רישא משום שהרי ודאי [אינו] רוצה או שמא דוקא אין לו מה יאכל שרי כדקתני גבי המודר הנאה מחבירו אבל אם יש לו מה יאכל אפי' [אינו] רוצה אין לו תקנה בכך וא\"ת והיאך נפרע ממנו והא תנן בפרק אין בין המודר (נדרים דף לג.) המודר הנאה מחבירו שוקל לו שקלו ופורע לו חובו ופר\"ת דדוקא במזונות אשתו אבל שאר חובות אסור לפרוע דודאי קא משתרשי ליה ואסור וה\"נ משתרשי ליה וי\"ל דלא דמי דהתם כיון שמתחייב למי שפרע בעבורו אם יפרע בחנם בעבורו א\"כ מהנהו ואסור אבל הכא מה שבאים ב\"ח ונפרעין מן הנכסים אין זה נהנה מן הנכסים וההיא דהולך אצל חנוני לא תקשה דהתם דרך מתנה מיירי שהחנוני נותן לזה פירות במתנה וחוזר ומקבל מזה מעות דרך מתנה אבל הא דאמר בפרק השותפין (נדרים דף מז:) קונם אשתי שאני נהנית לך כו' לוה וב\"ח באין ונפרעין מבעל בשלמא קונם שאני נהנה לאשתי איכא למימר במזונות אשתו ואליבא דתנן אלא קונם שאני נהנה לך משמע שאומר לחבירו נמצא שהוא פורע חובו ויש לומר כגון שלוה הימנו על מנת שלא לפרוע דהשתא אין נהנה כלום במה שפורע חובו וא\"ת וכי בשופטני עסקינן שילוה ע\"מ שלא לפרוע וי\"ל שהוא אוהבו שלא יניח מלפרוע בעבורו:"],[9,"אלא אמר רב","ששת הא והא ר' יוסי הגלילי. וא\"ת ואמאי לא מוקי מתני' כר' עקיבא ומודה דלאחרים מצי מחיל ולנפשיה לא מצי מחיל ובזקפו עליו במלוה הוא דפליג עליו רבי עקיבא ארבי יוסי דלא חשיב ליה זקיפה כמו מחילה דאחריני וי\"ל דרב ששת סבר כיון דמחילה דאחריני מועלת זקפו נמי מועיל לכ\"ע וכיון דאמר ר' עקיבא דזקפו במלוה אינו מועיל א\"כ ודאי ס\"ל דמחילת אחרים נמי אינו מועיל הלכך לא מתוקמא מתני' כר' עקיבא דקתני במתניתין מחל לו את הקרן משמע דמחילת אחריני מועלת ורבא דמוקי לה כרבי עקיבא סבר דזקפו במלוה אינו מועיל כלום לכ\"ע אי לא מצי מחיל לנפשיה הלכך רבי יוסי דקאמר זכה הלה במה שבידו ע\"כ משום דסבר דמצי מחיל לנפשיה הלכך מתני' לא מיתוקמא כוותיה אלא כרבי עקיבא ומודה רבי עקיבא דלאחריני מצי מחיל והשתא הא דנקט זקפו במלוה להודיעך כחו דרבי עקיבא דאפי' זקפו במלוה לא מצי מחיל לנפשיה כיון דליכא מחילה דאחריני:"]]],[["מכלל דרבי יוסי הגלילי סבר אפילו לנפשיה נמי מצי מחיל אלא גזל הגר דקאמר רחמנא נתינה לכהנים היכי משכחת לה","אמר רבא הכא במאי עסקינן כשגזל את הגר ונשבע לו ומת הגר והודה לאחר מיתה דבעידנא דאודי קנאו השם ונתנו לכהנים","בעי רבינא גזל הגיורת מהו (במדבר ה, ו) איש אמר רחמנא ולא אשה או דלמא אורחיה דקרא הוא","אמר ליה רב אהרן לרבינא תא שמע דתניא איש אין לי אלא איש אשה מנין כשהוא אומר (במדבר ה, ח) המושב הרי כאן שנים","א\"כ מה ת\"ל איש איש אתה צריך לחזור אחריו אם יש לו גואלים אם לאו קטן אי אתה צריך לחזור אחריו בידוע שאין לו גואלין","תנו רבנן (במדבר ה, ח) לה' לכהן קנאו השם ונתנו לכהן שבאותו משמר אתה אומר לכהן שבאותו משמר או אינו אלא לכל כהן שירצה כשהוא אומר (במדבר ה, ח) מלבד איל הכפורים אשר יכפר בו עליו הרי לכהן שבאותו משמר הכתוב מדבר","ת\"ר הרי שהיה גוזל כהן מנין שלא יאמר הואיל ויוצא לכהנים והרי הוא תחת ידי יהא שלי ודין הוא אי בשל אחרים הוא זוכה בשל עצמו לא כ\"ש","רבי נתן אומר בלשון אחר ומה דבר שאין לו חלק בו עד שיכנס ברשותו כשיכנס לרשותו אינו יכול להוציאו מידו דבר שיש לו חלק בו עד שלא יכנס ברשותו משנכנס לרשותו אינו דין דאין אחר יכול להוציאו מידו","לא אם אמרת בדבר שאין לו חלק בו שכשם שאין לו חלק בו כך אין לאחרים חלק בו תאמר בגזל שכשם שיש לו חלק בו כך יש לאחרים חלק בו אלא גזילו יוצא מתחת ידו ומתחלק לכל אחיו הכהנים","והכתיב (במדבר ה, י) ואיש את קדשיו לו יהיו הכא במאי עסקינן בכהן טמא","אי בכהן טמא דבר שיש לו חלק בו מי אית ליה אלא אתיא לכהן לכהן משדה אחוזה","דתניא (ויקרא כז, כא) אחוזתו מה ת\"ל מנין לשדה היוצאה לכהנים ביובל וגאלה אחד מן הכהנים מנין שלא יאמר הואיל ויוצאה לכהנים ביובל והרי היא תחת ידי תהא שלי","ודין הוא בשל אחרים אני זוכה בשל עצמי לא כ\"ש","ת\"ל (ויקרא כז, כא) כשדה החרם לכהן תהיה אחוזתו אחוזה שלו ואין זו שלו הא כיצד יוצאה מתחת ידו ומתחלקת לכל אחיו הכהנים:","תנו רבנן מנין לכהן שבא ומקריב קרבנותיו בכל עת ובכל שעה שירצה תלמוד לומר (דברים יח, ו) ובא בכל אות נפשו ושרת","ומניין שעבודתה ועורה שלו תלמוד לומר (במדבר ה, י) ואיש את קדשיו לו יהיו הא כיצד אם היה בעל מום נותנה לכהן שבאותו משמר ועבודתה ועורה שלו"],[[0,"מכלל דרבי יוסי הגלילי סבר מצי מחיל לנפשיה","אפי' לא זקפו לרבא פרכינן:"],[1,"קנאו השם","הקב\"ה כדכתיב המושב לה' לכהן:"],[1,"קנאו השם ונתנו לכהנים","אבל הודה בחיי הגר נעשה אצלו כמלוה וכי מיית גר מחיל לנפשיה:"],[2,"גזל הגיורת","שגזל אותה ונשבע והודה לאחר מיתה:"],[2,"מהו","מי נפיק לכהנים או זכה בה איהו:"],[2,"איש אמר רחמנא","אם אין לאיש גואל:"],[3,"הרי כאן שנים","תרי השבות כתיב להשיב המושב. לישנא אחרינא תרי אשמות כתיבי להשיב האשם האשם המושב:"],[4,"צריכין לחזור אחריו","ולשאול אם יש לו בנים קודם שתתנהו לכהן:"],[4,"קטן","שאין איש בידוע שאין לו בנים יתנהו לכהנים ומהכא נפקא לן דקטן לאו בר אולודי הוא בסנהדרין בבן סורר ומורה (סנהדרין דף סט.):"],[5,"לכהן שבאותו משמר","שהוא בא להתכפר בו:"],[5,"כשהוא אומר מלבד איל הכפורים","משמע למי שזה ניתן זה ניתן ואיל הכפורים אין יכול להקריב אלא כהן שבאותו משמר כדכתיב (דברים י״ח:ח׳) לבד ממכריו על האבות אני בשבתי ואתה בשבתך:"],[6,"הרי שהיה כהן גוזל","את הגר וכשהגיע משמר שלו בא והודה לאחר מיתת הגר:"],[6,"בשל אחרים","אם היה ישראל מביא גזל הגר במשמר זה הריני נוטל חלקי עם אחיי הכהנים בני המשמר:"],[6,"בשל עצמי לא כ\"ש","שאטול את הכל:"],[7,"מה דבר שאין לו חלק בו","כגון כהן שהתנדב קרבן דאמרינן לקמן בשמעתין כהן בא ומקריב קרבנותיו בכל שעה שירצה ובשרה ועורה שלו דכתיב ואיש את קדשיו לו יהיו נמצא שאין לבני משמר חלק בו:"],[7,"משנכנס לרשותו אין אחר יכול כו'","שאם נתנה לכהן אחר של אותו משמר שוב אין יכול להוציאו מידו שנאמר ואיש אשר יתן לכהן לו יהיה:"],[7,"דבר שיש לו חלק בו עד שלא נכנס ברשותו","שכיון שבא ישראל והביא גזל הגר למשמר זה אע\"פ שנתנו לאחד מאחיו יש לו חלק בו:"],[7,"ל\"א","מה דבר (שלא נכנס ברשותו) כגון תרומות ומעשרות מפי עוקר הרים:"],[8,"כך אין לאחרים חלק בו","לפיכך משנתנו לך מי יעכב עליך:"],[8,"תאמר בגזל","הגר שהוא לכל בני משמר וכולם תובעין:"],[9,"והכתיב ואיש את קדשיו [וגו']","ונפקא לן לקמן מיניה שכהן מקריב קרבנותיו בכל עת שירצה ובשרה ועורה שלו והכא נמי האי איל אשם קרבנות דכהן הוא וזכי ביה וכיון דמקריב ליה וזכי ביה גזל נמי דידיה הוא כדאמרינן מלבד איל הכפורים למי שזה ניתן זה ניתן:"],[10,"בכהן טמא","דאין ראוי להקריב איל האשם:"],[10,"אי [בכהן] טמא","היכי מצי למימר דבר שיש לו חלק בו והא קיימא לן בזבחים (דף צח:) דאין טמא חולק בקדשי המקדש ואפילו בעורות וגזל הגר נמי קדשי המקדש הוא:"],[10,"אלא","לעולם בכהן טהור והאי דמוציאין מידו משום דילפינן ג\"ש כהן כהן משדה אחוזה ואיש את קדשיו במילי אחריני מתוקמא:"],[11,"אחוזתו","לכהן תהיה היה לו למימר ודיו ומה ת\"ל אחוזתו:"],[11,"לשדה היוצאה לכהנים","מקדיש שדה אחוזה ולא גאלה מן ההקדש ומכרה גזבר לאחרים כשהיא יוצאה מיד הלוקח ביובל מתחלקת לכהנים משמר שנכנס בו יובל שנאמר ואם לא יגאל את השדה בעלים ואם מכר את השדה גזבר לא יגאל עוד בעלים אלא והיה השדה וגו' והכי תניא בת\"כ ובערכין:"],[11,"וגאלה אחד מן הכהנים","כלומר והלוקח מן הגזבר כהן היה ומבני המשמר של יובל היה:"],[12,"בשל עצמי לא כ\"ש","שאטול את הכל:"],[14,"שבא ומקריב","אם נדר קרבן או שהיה מוטל עליו חטאת ואשם חובה מקריב אף במשמר שאינו שלו:"],[15,"שעבודתה","שכר עבודתה דהיינו בשרה:"],[15,"אם היה בעל מום","ראוי לאכול ואין ראוי להקריב אין יכול לעשות שליח להקרבה מי שירצה אלא נותנה לבני המשמר והואיל והוא ראוי לאכילה קרינן ביה ואיש את קדשיו לפיכך עבודה ועורה שלו. לשון אחר גרסינן עבודה ועורה לאנשי משמר כיון דהם הקריבוהו:"]],[[0,"אלא גזל הגר דקאמר היכי משכחת לה","ה\"ה דה\"מ למפרך בתחילת סוגיא כי קאמר ר' יוסי הגלילי לא שנא לנפשיה ולא שנא לאחריני מצי מחיל אלא משום דהוו ליה פירכי אחריני לא חש למפרך:"],[4,"קטן אי אתה צריך לחזור עליו","וא\"ת גזל גר קטן היכי משכחת לה והא אין זכיה לקטן כדאמרינן בפ\"ק דב\"מ (דף יב.) דגזל קטן מדבריהם ולא מדאורייתא ובירושה ליכא למימר דגר אין יורש אביו דבר תורה וי\"ל דדוקא מציאה דאין דעת אחרת מקנה אותו לא הוה אלא מדבריהם אבל כשדעת אחרת מקנה אותו קני מדאורייתא ובקטן שנתגייר עם אביו מיירי דלכ\"ע מטבילין אותו אבל בלא אביו פלוגתא היא בפרק קמא דכתובות (דף יא.) אם מטבילים אותו על דעת בית דין: [ועי' תוס' סנהדרין סח: ד\"ה קטן]"],[5,"לכהן שבאותו משמר","אין נראה לפרש דבשעת הודאה כשמתחייב אלא למשמר שהיה בשעת הבאה שהרי בכל הקרבנות חטאות ואשמות נדרים ונדבות אין אנו הולכים אחר שעת החיוב ליתנו לאותו משמר שהיה באותה שעה שנדר או נדב או חטא שהוא מתחייב בה אלא אחר הבאה אנו הולכים וכמו כן בכאן:"],[6,"מנין שלא יאמר","תימה דנקיט האי לישנא כיון דלא מקרא מייתי לה אלא מדינא:"],[7,"ומה דבר שאין לו חלק בו עד שיכנס לרשותו","כגון תרומה וחלה וראשית הגז שטובת הנאה לבעלים ליתן לאיזה כהן שירצה משנכנס לרשותו אין אחר יכול להוציא מידו שיתחלק לבני משמר דאין מתחלק לאנשי משמר אלא מתנות:"],[8,"לא אם אמרת בדבר שאין כו'","ללשון ראשון נמי דקאמר ודין הוא בשל אחרים אני זוכה יכול להקשות דיו לבא מן הדין להיות כנדון שלא יזכה בשל עצמו אלא כפי חלקו כמו בשל אחרים:"],[11,"אחוזתו מה ת\"ל","תימה להרשב\"א למ\"ל אחוזתו לומר שיוצאה מתחת ידו ומתחלקת לכל אחיו הכהנים דהיכי הוה אמינא בשל אחרים אני זוכה בשל עצמי לא כ\"ש הא הכא שייך נמי למפרך כמו לעיל דיו לבא כו' ויש לומר דאיצטריך אחוזתו משום דה\"א כיון שהיא תחת ידו תהא שלו דהוה ילפינן כהן כהן מגזל הגר ובגזל הגר ה\"א דהוי שלו כדקאמר ואיש את.. קדשיו לו יהיו משום הכי איצטריך אחוזתו:"],[11,"מנין ליוצאה לכהנים כו'","ברייתא היא בערכין בפרק אין מקדישין (ערכין דף כה:):"]]],[["ואם היה זקן או חולה נותנה לכל כהן שירצה ועבודתה ועורה לאנשי משמר","האי זקן או חולה היכי דמי אי דמצי עביד עבודה עבודתה ועורה נמי תיהוי דידיה ואי דלא מצי עביד עבודה שליח היכי משוי","אמר רב פפא שיכול לעשות על ידי הדחק עבודה דכי עביד ליה ע\"י הדחק עבודה היא ומשוי שליח אכילה דכי אכיל על ידי הדחק אכילה גסה היא ואכילה גסה לאו כלום הוא משום הכי עבודתה ועורה לאנשי משמר","אמר רב ששת אם היה כהן טמא בקרבן צבור נותנה לכל מי שירצה ועבודתה ועורה לאנשי משמר היכי דמי אי דאיכא טהורים טמאים מי מצו עבדי ואי דליכא טהורים עבודתה ועורה לאנשי משמר הא טמאים נינהו ולא מצו אכלי","אמר רבא אימא לבעלי מומין טהורין שבאותו משמר","אמר רב אשי אם היה כהן גדול אונן נותנה לכל כהן שירצה ועבודתה ועורה לאנשי משמר מאי קמ\"ל תנינא כהן גדול מקריב אונן ואינו אוכל ואינו חולק לאכול לערב","ס\"ד אמינא כי חס רחמנא עליה דכהן גדול לקרובי הוא אבל לשוויי שליח לא מצי משוי קמ\"ל:","\u0001מתני׳\u0002 הגוזל את הגר ונשבע לו ומת הרי זה משלם קרן וחומש לכהנים ואשם למזבח שנאמר (במדבר ה, ח) ואם אין לאיש גואל להשיב האשם אליו האשם המושב לה' לכהן מלבד איל הכפורים אשר יכפר בו עליו","היה מעלה את הכסף ואת האשם ומת הכסף ינתן לבניו והאשם ירעה עד שיסתאב וימכר ויפלו דמיו לנדבה נתן הכסף לאנשי משמר ומת אין היורשין יכולין להוציא מידם שנאמר (במדבר ה, י) ואיש אשר יתן לכהן לו יהיה","נתן הכסף ליהויריב ואשם לידעיה יצא אשם ליהויריב וכסף לידעיה אם קיים האשם יקריבוהו בני ידעיה ואם לא יחזיר ויביא אשם אחר שהמביא גזילו עד שלא הביא אשמו יצא הביא אשמו עד שלא הביא גזילו לא יצא","נתן את הקרן ולא נתן את החומש אין החומש מעכב:","\u0001גמ׳\u0002 ת\"ר אשם זה קרן המושב זה חומש או אינו אלא אשם זה איל","ולמאי נפקא מינה לאפוקי מדרבא דאמר רבא גזל הגר שהחזירו בלילה לא יצא החזירו חצאין לא יצא מ\"ט אשם קרייה רחמנא","כשהוא אומר מלבד איל הכפורים הוי אומר אשם זה קרן","תניא אידך אשם זה קרן המושב זה חומש או אינו אלא אשם זה חומש למאי נפקא מינה לאפוקי ממתניתין דתנן נתן לו את הקרן ולא נתן לו את החומש אין החומש מעכב אדרבה חומש מעכב","כשהוא אומר (במדבר ה, ז) והשיב את אשמו בראשו וחמישיתו הוי אומר אשם זה קרן","תניא אידך אשם זה קרן המושב זה חומש ובגזל הגר הכתוב מדבר או אינו אלא המושב זה כפל ובגניבת הגר הכתוב מדבר כשהוא אומר והשיב את אשמו בראשו וחמישיתו הרי בממון המשתלם בראש הכתוב מדבר","גופא אמר רבא גזל הגר שהחזירו בלילה לא יצא החזירוהו חצאין לא יצא מאי טעמא אשם קרייה רחמנא","ואמר רבא גזל הגר שאין בו שוה פרוטה לכל כהן וכהן לא יצא ידי חובתו מ\"ט דכתיב האשם המושב עד שיהא השבה לכל כהן וכהן","בעי רבא אין בו למשמרת יהויריב ויש בו"],[[0,"ואם היה זקן","וראוי לעבודה כדמפרש לקמן ואין ראוי לאכילה:"],[0,"נותנה","להקריב:"],[0,"לכל כהן שירצה","דהואיל דהוא חזי לעבודה מצי לשוייה שליח:"],[0,"ועבודתה ועורה לאנשי משמר","דכיון דלא חזי לאכילה לא משוי שליח לאכילה:"],[2,"אכילה גסה","שנפשו קצה בה:"],[3,"אם היה הכהן","של המשמר טמא ויש לו קרבן צבור להקריב:"],[3,"אי דאיכא טהורין","בההוא משמר:"],[3,"טמאים מי מצו עבדי","וכיון דלא מצו עבדי שליח היכי משווי:"],[4,"לבעלי מומין טהורין","מתחלקת דקיימא לן זבחים (ד' צח:) איש חולק ואפי' בעל מום בקדשים ובמנחות:"],[5,"אם היה כהן גדול אונן","ויש לו קרבן עצמו להקריב:"],[5,"נותנו לכל כהן שירצה","דכיון דכהן גדול מקריב אונן דכתיב לאביו ולאמו לא יטמא ומן המקדש לא יצא אם מת אביו ואמו דהוי אונן אפילו הכי מקדושתו לא יצא ולא יחלל כלומר דעבודתו שיעבוד באנינות לא תתחלל הא אחר הדיוט שלא יצא חילל:"],[5,"ואינו חולק לאכול לערב","כשתסתלק אנינותו דאנינות לילה דרבנן דאנינות דאורייתא אינו אלא יום מיתה דכתיב (עמוס ח׳:י׳) ואחריתה כיום מר אלמא אין מרירות אלא יום אחד:"],[8,"מתני' היה מעלה את הכסף ומת","בדרך:"],[8,"הכסף ינתן לבניו","של גזלן דהא זכה ביה ממיתת הגר אלא דבעי למעבד השבה כי היכי דתיהוי ליה כפרה אשבועתיה והשתא תו ליכא כפרה כיון דמית ליה:"],[8,"האשם ירעה","דהוי אשם שמתו בעליו וקיי\"ל לקמן כל שבחטאת מתה באשם רועה:"],[8,"לנדבה","לשופרות קיץ המזבח עולות בשר לשם ועורות לכהנים:"],[9,"משמרת יהויריב","ראשונה לכל המשמרות ושל ידעיה אחריה:"],[9,"נתן","הגזלן את הכסף ליהויריב במשמרתו ואח\"כ נתן אשם לידעיה במשמרתו:"],[9,"יצא","כדמפרש ואזיל שהמביא גזילו עד שלא הביא קרבן אשמו יצא וזה זכה בשלו וזה בשלו:"],[9,"אם קיים האשם יקריבוהו בני ידעיה","דקנסינהו ליהויריב להחזיר האשם דשלא כדין עבוד בני יהויריב דקבול אשם מקמי כסף ולידעיה ליכא למקנס מידי דבמשמר דידהו קבילי ור' יהודה דפליג אברייתא בגמרא במתניתין מודה:"],[10,"נתן הקרן","לכהנים אין החומש מעכב מלהקריב את האשם אם לא נתן עדיין ולבסוף נתן:"],[11,"גמ' או אינו אלא אשם זה איל","אשם ומושב זה קרן:"],[12,"ולמאי נ\"מ","דהא ממה נפשך תרוייהו קאמר קרא תיפוק ליה מינה לאפוקי מדרבא דאמר דאשם קרייה רחמנא לקרן ומה אשם אינו בא בלילה דכתיב (ויקרא ז׳:ל״ח) ביום צותו ואינו בא לחצאין אף קרן כו':"],[13,"כשהוא אומר מלבד איל הכפורים הוי אומר אשם","דרישא קרן הוא:"],[14,"או אינו אלא אשם זה חומש","ומושב זה קרן ונ\"מ לאפוקי ממתניתין דתנן אין החומש מעכב נימא אדרבה חומש מעכב דאשם קרייה רחמנא לשון קרבן כשהוא אומר כו':"],[16,"משתלם בראש","קרן לבדו שהוא ראש:"],[18,"לכל כהן וכהן","שבמשמר ומוסיף משלו עוד להשלים:"],[19,"אין בו","שוה פרוטה לכל משמר יהויריב ויש בו שוה פרוטה לכל משמר ידעיה שהן מועטין מהו:"]],[[2,"דכי עביד ע\"י הדחק עבודה היא","דלא מצינו בכהנים פסול בשנים אלא דנתנו חכמים שיעור עד שירתת בהכל שוחטין (חולין ד' כד:):"],[2,"אכילה גסה לאו כלום היא","מפיק מדריש לקיש דאמר בהחולץ (יבמות ד' מ. ושם.) האוכל אכילה גסה ביום הכפורים פטור מלא תענו וא\"ת דבפרק מי שאמר הריני נזיר ושמע (נזיר דף כג. ושם) גבי הא דאמר רבה בר בר חנה אמר ר' יוחנן מאי דכתיב צדיקים ילכו בם ופושעים יכשלו בם משל לשני בני אדם שצלו פסחיהם אחד אכלו לשם מצוה ואחד אכלו לשם אכילה גסה זה שאכלו לשם אכילה גסה ופושעים יכשלו בם א\"ל ריש לקיש רשע קרית ליה נהי דלא עבד מצוה מן המובחר מצוה מיהא עביד משמע דיצא ידי חובה וי\"ל דהתם לא קאמר דיצא אלא דלא מיקרי רשע ועוד דהתם לא מיירי באוכלו אכילה גסה ממש אלא כלומר שאין אוכלו לשם פסח אלא כדי להיות שבע תדע דלא קאמר אכילה גסה אלא לשם אכילה גסה ועי\"ל דשתי אכילות גסות הן.:"],[3,"אי דאיכא טהורין טמאין מי מצו עבדי","לרב ששת פריך דשמעינן ליה לרב ששת דאמר בפ\"ק דיומא (דף ו:) טומאה דחויה בצבור ואי איכא טמאים וטהורין לא מצו עבדי טמאים ואיכא דפליג התם ואמר דטומאה הותרה בצבור ואפי' איכא טמאים וטהורים מצו עבדי טמאים:"],[4,"לבעלי מומין טהורין","תימה ועורה אמאי הויא לבעלי מומין:"],[5,"תנינא כ\"ג מקריב אונן","תימה אמאי לא פריך נמי לרב ששת תנינא טמא מותר בקרבן ציבור:"],[14,"למאי נ\"מ לאפוקי ממתניתין","תימה אמאי לא קאמר לאפוקי מדרבא כדקאמר לעיל:"],[16,"או אינו אלא המושב זה כפל","תימה היכי מ\"ל זה כפל והלא אין מתחייב כאן אלא בהודאתו דכתיב והתודה וכפל לא מחייב בהודאה:"]]],[["למשמרת ידעיה מהו","היכי דמי אילימא דיהביה לידעיה במשמרת ידעיה הא אית ביה","לא צריכא דיהביה לידעיה במשמרתו דיהויריב מאי מי אמרינן כיון דלאו משמרתו הוא ולא כלום הוא או דלמא כיון דלא חזי ליה מעיקרא לידעיה קאי תיקו","בעי רבא כהנים מהו שיחלקו גזל הגר כנגד גזל הגר","מי אמרינן אשם קרייה רחמנא מה אשם אין חולקין אשם כנגד אשם אף גזל אין חולקין גזל הגר כנגד גזל הגר או דלמא גזל הגר ממונא הוא","הדר פשטה אשם קרייה רחמנא רב אחא בריה דרבא מתני לה בהדיא אמר רבא כהנים אין חולקין גזל הגר כנגד גזל הגר מ\"ט אשם קרייה רחמנא:","בעי רבא כהנים בגזל הגר יורשין הוו או מקבלי מתנות הוו","למאי נפקא מינה כגון שגזל חמץ שעבר עליו הפסח אי אמרת יורשין הוו היינו האי דירתי מורית ואי אמרת מקבלי מתנות הוו מתנה קאמר רחמנא דניתיב להו והא לא קא יהיב להו מידי דעפרא בעלמא הוא","רב זעירא בעי הכי אפילו אם תימצי לומר מקבלי מתנה הוו הא לא איבעיא לן דההיא מתנה אמר רחמנא דניתיב להו","אלא כי קמבעיא לן כגון שנפלו לו עשר בהמות בגזל הגר מחייבי לאפרושי מינייהו מעשר או לא","יורשין הוו דאמר מר קנו בתפיסת הבית חייבין או דלמא מקבלי מתנות הוו ותנן הלוקח והניתן לו במתנה פטור ממעשר בהמה מאי","ת\"ש עשרים וארבע מתנות כהונה ניתנו לאהרן ולבניו וכולן ניתנו בכלל ופרט וכלל וברית מלח","כל המקיימן כאילו מקיים כלל ופרט וכלל וברית מלח כל העובר עליהם כאילו עובר על כלל ופרט וכלל וברית מלח","ואלו הן עשר במקדש וד' בירושלים ועשר בגבולים עשר במקדש חטאת בהמה וחטאת העוף ואשם ודאי ואשם תלוי וזבחי שלמי צבור ולוג שמן של מצורע ומותר העומר ושתי הלחם ולחם הפנים ושירי מנחות","וארבע בירושלים הבכורה והביכורים והמורם מן התודה ואיל נזיר ועורות קדשים","ועשרה בגבולין תרומה ותרומת מעשר וחלה וראשית הגז והמתנות ופדיון הבן ופדיון פטר חמור ושדה אחוזה ושדה חרמים וגזל הגר","וקא קרי מיהת מתנה ש\"מ מקבלי מתנות הוו ש\"מ:","נתן את הכסף לאנשי משמר [וכו']: אמר אביי ש\"מ כסף מכפר מחצה דאי לא מכפר הוה אמינא מהדר ליורשין מ\"ט אדעתא דהכי לא יהב ליה","אלא מעתה חטאת שמתו בעליה תיפוק לחולין דאדעתא דהכי לא אפרשה אמרי חטאת שמתו בעליה הלכתא גמירי לה דלמיתה אזלא","אלא מעתה אשם שמתו בעליו ליפוק לחולין דאדעתא דהכי לא אפרשיה אשם נמי הלכתא גמירי לה כל שבחטאת מתה באשם רועה","אלא מעתה יבמה שנפלה לפני מוכה שחין תיפוק בלא חליצה דאדעתא דהכי לא קדשה עצמה התם אנן סהדי"],[[5,"אין חולקים","מנחות כנגד מנחות וקרבן כנגד קרבן מלכל בני אהרן תהיה איש כאחיו נפקא לן בקדושין (דף נג.) ובמנחות פרק אלו מנחות (מנחות דף עג.):"],[6,"יורשין","הגר הן או מקבלי מתנות גבוה הן:"],[7,"היינו האי דירתי","ירושה זאת נפלה להן והרי היא לפניהן שאילו היה הגר קיים היה זה אומר לו הרי שלך לפניך:"],[8,"רב זעירי בעי לה","הכי אפילו אם תמצי לומר מקבלי מתנות הוו הא לא מבעיא לן דהא מתנה. יהיב להו רחמנא. והרי הן לפניהן:"],[9,"כגון שנפלו לו","לכהן:"],[10,"קנו","יתומים שקנו בהמות:"],[10,"בתפיסת הבית","כלומר נפלו להן בהמות בירושה עד שלא חלקו:"],[10,"הלוקח","לקח עשרה טלאים שלא נתעשרו מן השוק:"],[10,"פטור","ובמסכת בכורות מפרש טעמא:"],[11,"בכלל ופרט וכלל","לכל קדשי בני ישראל לך נתונים למשחה כלל וזה יהיה לך מקדש הקדשים מן האש פרט כל מתנה בפני עצמה וכל תרומת קדשים חזר וכלל והדר כתיב ברית מלח עולם הוא וגו' בסוף הפרשה (במדבר יח):"],[12,"כל המקיימן כאילו קיים","כל התורה כולה שניתנה לדרוש בכלל ופרט וכלל וכאילו קיים כל הקרבנות שניתנה בהן ברית מלח:"],[13,"עשר במקדש","נאכל לפנים מן הקלעים:"],[13,"ארבע בירושלים","בכל העיר:"],[13,"ועשר בגבולים","בערי ארץ ישראל:"],[13,"אשם ודאי","חמשה הן גזילות מעילות שפחה חרופה נזיר ומצורע וחד חשיב להו:"],[13,"אשם תלוי","בא על ספק כרת שלא נודע לו שעבר ודאי שיביא חטאת:"],[13,"וזבחי שלמי צבור","כבשי עצרת שנקראו שלמים כדכתיב (ויקרא כ״ג:כ׳) ושני כבשים בני שנה וקדשי קדשים הן כדכתיב (שם) קדש יהיו לה' לכהן ונאכלים לפנים מן הקלעים:"],[13,"ולוג שמן של מצורע","מה שנשאר בלוג מיציקה לכף כהן של השמאלית נאכל לכהנים דתניא במנחות (דף עג.) ובזבחים (דף מד:) לכל קרבנם לרבות לוג שמן של מצורע דהוא נמי קרוי קרבן דכתיב והקריב אותו לאשם ואת לוג השמן וסמיך ליה לקרא קמא בקדש הקדשים תאכלנו בויקח קרח:"],[13,"מותר העומר","מנחת העומר נקמצת ושיריה נאכלים וכל המנחות קדשי הקדשים הן כדכתיב לא (תאכל עליו חמץ) וגו':"],[13,"ושירי מנחות","כל מנחות הנקמצות מנחת נדבה ומנחת חוטא ומנחת סוטה:"],[14,"הבכורה","בכור תם נאכל בכל העיר וכן הבכורים צריכין חומה כדכתיב (דברים י״ב:ז׳) ואכלתם שם לפני ה' אלהיכם וגו' ואמר מר תרומת ידך אלו בכורים מכות (דף יז.):"],[14,"והמורם מתודה","חזה ושוק וארבע חלות מארבע מינים שבה חלות ורקיקין חמץ ורבוכה וכתיב (ויקרא ז׳:י״ד) והקריב ממנו אחד מכל קרבן תרומה לכהן הזורק וגו':"],[14,"והמורם מאיל נזיר","זרוע בשלה וחלה ורקיק וחזה ושוק של שלמים בכלל תודה הוא דתודה שלמים אקרי והנך תרתי תודה ואיל נזיר משום דדמיין להדדי חשיב להו בחדא כדאמר בשחיטת חולין בפרק הזרוע:"],[14,"ועורות קדשים","עורות עולה וחטאות ואשמות אבל קדשים קלים עורותיהן לבעלים כדאמר בזבחים פרק טבול יום (זבחים דף קג.) ומש\"ה קא חשיב להו בהדי הנך דבירושלים למעוטי דאין נחשבים בהדי הנך דגבולים דהני עורות לא מתייהבי להו אלא בירושלים ובהדי הנך דבמקדש לא חשיב אלא הנהו דאי נפקי חוץ לקלעים מפסלי ביוצא:"],[15,"ושדה אחוזה","שהקדישוה בעליה ולא גאלה ומכרה גזבר כשהלוקח מחזירה ביובל מתחלקת לכהנים:"],[15,"ושדה חרמים","ישראל שהחרימו שדיהן:"],[15,"וגזל הגר","נמי קרי ליה מתנת גבולין שאם נתנו לכהן המשמר חוץ לירושלים יצא ואיל אשמו יעלה לירושלים להקריב:"],[17,"אדעתא דהכי","דלא תיהוי ליה כפרה:"],[18,"תיפוק לחולין","ולא תיזל למיתה:"],[19,"באשם רועה","עד שיומם וימכר ויפלו דמיו לקיץ המזבח עולה לשם ועורה לכהנים זה מדרש דרש יהוידע הכהן בשקלים (דף ט:) ובתמורה (דף כג:) וכל זמן שהוא תם אין יוצא לחולין לימכר לפיכך ירעה והוא מעצמו אין יכול להשתנות מאשם לעולה:"]],[[2,"או דלמא כיון דלא חזי ליהויריב לידעיה קאי","ויכול להביא אשם מיד וליתבה לפני יהויריב להתכפר אע\"פ שהכסף נתון לידעיה כדקתני בפירקין נתן את הכסף ליהויריב והאשם לידעיה יצא:"],[7,"למאי נ\"מ לגזל חמץ ועבר עליו הפסח","תימה אמאי לא פשיט ליה מדידיה דאמר לעיל גזל הגר שאין בו שוה פרוטה לכל אחד ואחד לא יצא אלמא מקבלי מתנות הווא] דאי יורשין הוו אמאי לא יצא מאי דשבק להון אבוהון יהב להון ונראה דבחד מנהון גרסינן רבה:"],[11,"בכלל ופרט וכלל וברית מלח","הך שמעתא מפורש. בפרק הזרוע (חולין דף קלג:):"],[15,"וגזל הגר","תימה אמאי חשיב גזל הגר מעשרה בגבולין דכי היכי דאמר רבא החזירו בלילה ולחצאין לא יצא דאשם קרייה רחמנא ה\"נ אם החזירו בגבולין לא יצא כדין אשם:"],[17,"כסף מכפר מחצה","מכאן נראה דכהן אין יכול למחול כיון דהוי כפרה:"],[20,"דאדעתא דהכי לא קדשה נפשה","נראה דבנפלה מן האירוסין איירי דאי מן הנישואין ודאי מקדשה נפשה כדי שתהא נשואה לבעלה דמשום אחר מיתת בעלה לא מסקא אנפשה מלהיות נשואה אלא מן האירוסין איירי דמקדושין אין לה שום טובה וא\"ת אדם שקנה מחבירו שום דבר ונתקלקל יבטל המקח דאדעתא דהכי לא קנה וי\"ל דהתם לאו בלוקח לחודיה תליא מילתא אלא כמו כן בדעת מוכר ומוכר אקנה ליה אדעתא דהכי אבל הכא דקדושין בדידה קיימא והוא אינו חושש היאך דעתה להתקדש וכן גבי מקדיש נמי בדידיה קאי וכן נותן הגזל בדידיה קאי: [וע' בתוספות כתובות מז:"]]],[["דמינח ניחא לה בכל דהו כריש לקיש דאמר ר\"ל טב למיתב טן דו מלמיתב ארמלו:","נתן את הכסף ליהויריב וכו': תנו רבנן נתן אשם ליהויריב וכסף לידעיה יחזיר כסף אצל אשם דברי רבי יהודה וחכמים אומרים יחזיר אשם אצל כסף","היכי דמי אילימא דיהיב ליה אשם ליהויריב במשמרתו דיהויריב וכסף לידעיה במשמרתו דידעיה זה זכה בשלו וזה זכה בשלו","אמר רבא הכא במאי עסקינן דיהיב אשם ליהויריב במשמרתו דיהויריב וכסף לידעיה במשמרתו דיהויריב ר' יהודה סבר כיון דלאו משמרת דידעיה היא לידעיה קנסינן ליה הלכך יחזיר כסף אצל אשם ורבנן סברי שלא כדין הוא עבוד בני יהויריב דקיבלו אשם מקמי כסף הלכך לדידהו קנסינן להו ויחזור אשם אצל כסף","תניא אמר רבי לדברי רבי יהודה אם קדמו בני יהויריב והקריבו את האשם יחזור ויביא אשם אחר ויקריבוהו בני ידעיה וזכו הללו במה שבידן","אמרי למאי חזי אשם פסול הוא אמר רבא לעורו","תניא אמר רבי לדברי רבי יהודה אם קיים אשם יחזיר אשם אצל כסף","והא רבי יהודה יחזיר כסף אצל אשם אית ליה הכא במאי עסקינן כגון דנפק משמרתו דיהויריב ולא תבעו והא קמ\"ל דאחולי אחילו גבייהו","תניא אידך אמר רבי לדברי רבי יהודה אם קיים אשם יחזור כסף אצל אשם פשיטא הכי אית ליה","הכא במאי עסקינן כגון דנפיק משמרתם דהני ודהני ולא תבעו מהו דתימא אחולי גבי הדדי קמ\"ל דאמרינן כיון דלא תבעי להדרו ברישא:","שהמביא גזילו עד שלא הביא אשמו [וכו']: מנהני מילי אמר רבא דאמר קרא (במדבר ה, ח) האשם המושב לה' לכהן מלבד איל הכפורים אשר יכפר בו מכלל דכסף ברישא","אמר ההוא מרבנן לרבא אלא מעתה (במדבר כח, כג) מלבד עולת הבקר הכי נמי מכלל דמוספין ברישא","והתניא מנין שלא יהא דבר קודם לתמיד של שחר תלמוד לומר (ויקרא ו, ה) וערך עליה העולה ואמר רבא העולה עולה ראשונה","אמר ליה אנא (במדבר ה, ח) מאשר יכפר בו נפקא ליה ועדיין לא כיפר:","נתן לו את הקרן וכו': ת\"ר מנין שאם הביא מעילתו ולא הביא אשמו אשמו ולא הביא מעילתו שלא יצא","תלמוד לומר (ויקרא ה, טז) באיל האשם ונסלח לו","ומנין שאם הביא אשמו עד שלא הביא מעילתו שלא יצא תלמוד לומר באיל האשם האשם בכבר","יכול כשם שאיל ואשם מעכבים כך חומש מעכב תלמוד לומר באיל האשם ונסלח לו איל ואשם מעכבים בהקדש ואין חומש מעכב","וילמד הקדש מהדיוט והדיוט מהקדש","הקדש מהדיוט מה אשם דהתם קרן אף אשם דהכא קרן והדיוט מהקדש מה הקדש אין חומש מעכב אף הדיוט נמי אין חומש מעכב:","\u0001הדרן עלך הגוזל עצים\u0002"],[[0,"דמינח ניחא לה","להתקדש לראשון שהוא שלם על ספק זה שאם ימות תזקק לאחיו:"],[0,"טן דו","גוף שנים כלומר אשה בכל דהו ניחא לה:"],[2,"זה זכה בשלו וזה זכה בשלו","ונהי נמי לרבנן דקנסו ליהויריב דקבול אשם מקמי כסף אלא לרבי יהודה מ\"ט דקניס לידעיה:"],[4,"לדברי רבי יהודה","ואע\"ג דקניס ליה לידעיה ה\"מ היכא דאשם ראשון קיים דיכולין בני יהויריב להקריבו בעוד משמרתן קיימת ובהכשר אבל אם קדמו והקריבוהו בפסול דאשם הבא קודם הקרן פסול הוא כדמפורש לקמן ינתן אשם השני לידעיה:"],[5,"למאי חזי","דקתני זכו:"],[7,"כגון דנפק משמרתם","דהני ודהני ולא תבעו בני יהויריב את הכסף במשמרתם ולא בני ידעיה את האשם במשמרתם ואיצטריך לאשמועינן דלא תימא טעמא דרבי יהודה בדתבעו בני יהויריב שיחזור בעוד משמרתן קיימת אבל היכא דלא תבעו מחלו לבני ידעיה:"],[7,"קמ\"ל","דכיון דבני ידעיה נמי לא תבעו לאשם במשמרתן יחזור כסף אצל אשם ויקריבוהו בני יהויריב כשיחזיר שבת משמרתם:"],[10,"האשם המושב [לה'] לכהן מלבד איל הכפורים אשר יכפר בו","כלומר לא קרב האיל עדיין:"],[13,"אנא מאשר יכפר קאמינא","דכתיב בלשון עתיד מדלא כתיב אשר כיפר ומשמע דכשהשיב לכהן את האשם דהיינו קרן הכסף עדיין לא כיפר:"],[14,"מנין שאם הביא מעילתו","גבי נהנה מן ההקדש קאמר:"],[14,"מעילתו","קרן דהקדש שמעל בו:"],[15,"באיל האשם ונסלח","משמע אין סליחה אלא בשניהם איל כמשמעו האשם קרן כדיליף לקמיה הקדש מהדיוט מה האשם דכתיב בגזל הגר קרן הוא כדאמר לעיל (בבא קמא דף קי.) אף אשם דכתיב בהקדש קרן הוא:"],[16,"באיל האשם","משמע באיל שהוא בא חובה לאשם שהוא קרן אלמא קרן ברישא מייתי:"],[19,"אין החומש מעכב","את הכפרה:"]],[[5,"","אמר רבא לעורו. תימה דהכא משמע אפילו בפסול קודם זריקה וגם כשהעור מחובר עדיין בבשר ונעשה בו פסול קודם שחיטה שהביא קודם הכסף שרי בהנאה ובזבחים בפרק טבול יום (זבחים דף קד. ושם) אמר רבי דם מרצה על העור בפני עצמו פי' כשהוא מופשט ואירע פסול בבשר הדם מרצה על העור וכשהוא עם הבשר ונולד בו פסול קודם זריקה הרי הוא כיוצא בו אחר זריקה הורצה בשר שעה אחת יפשיטנו ועורו לכהנים אלמא כשהוא עם הבשר ונפסל קודם זריקה יוצא לשריפה והכא אירע בו פסול קודם שחיטה שהובא קודם הכסף ואמאי לא יצא העור לשריפה:"],[12,"ת\"ל העולה עולה ראשונה","פי' ראשונה שבפרשת פנחס וכי היכי דמלבד עולת הבקר גלי לך בהדיא דמלבד דבר הקודם לו קאמר הכי נמי מלבד איל הכפורים דבר הקודם לו קאמר ותימה דיליף הכא מהעולה ובפרק כל התדיר (זבחים דף פט. ושם.) יליף ממלבד עולת הבקר לחודיה וי\"ל דהתם נמי אהעולה קסמיך ועוד יש תירוץ אחר ואין להאריך כאן:"],[18,"וילמד הקדש מהדיוט והדיוט מהקדש","תימה אמאי איצטריך קרא לעיל גבי הדיוט שאם הביא אשמו עד שלא הביא גזילו לא יצא נילף מהקדש ויש לומר דאי לאו דאשכחן שהשוה הכתוב הדיוט להקדש להך מילתא לא הוה ילפינן האי מהאי לענין שאר דברים אבל השתא דאשכחן שהשוה אותן דבתרוייהו אם הביא אשמו תחילה לא יצא כמו כן יש להשוותם לענין שאר דברים:"]]],[["מתני׳ \u0001הגוזל\u0002 ומאכיל את בניו והניח לפניהם פטורין מלשלם ואם היה דבר שיש בו אחריות חייבין לשלם:","\u0001גמ׳\u0002 אמר רב חסדא גזל ולא נתייאשו הבעלים ובא אחר ואכלו ממנו רצה מזה גובה רצה מזה גובה מאי טעמא כל כמה דלא נתייאשו הבעלים ברשותיה דמריה קאי","תנן הגוזל ומאכיל את בניו והניח לפניהם פטורין מלשלם תיובתא דרב חסדא אמר לך רב חסדא כי תניא ההיא לאחר יאוש:","אם הניח לפניהם פטורין מלשלם: אמר רמי בר חמא זאת אומרת רשות יורש כרשות לוקח דמי","רבא אמר רשות יורש לאו כרשות לוקח דמי והכא במאי עסקינן כשאכלום","הא מדקתני סיפא אם היה דבר שיש בו אחריות חייבין לשלם מכלל דרישא בגזילה קיימת עסקינן אמר לך רבא הכי קאמר אם הניח להם אביהם אחריות נכסים חייבין לשלם","והא מתני ליה רבי לרבי שמעון בריה לא דבר שיש בו אחריות ממש אלא אפילו פרה וחורש בה חמור ומחמר אחריו חייבין להחזיר מפני כבוד אביהן","אלא אמר רבא כי שכיבנא ר' אושעיא נפיק לוותי דתריצנא מתני' כוותיה דתני רבי אושעיא הגוזל ומאכיל את בניו פטורין מלשלם הניח לפניהם גזילה קיימת חייבין אין הגזילה קיימת פטורין הניח להם אביהם אחריות נכסים חייבין לשלם","אמר מר אין הגזילה קיימת פטורין נימא תיהוי תיובתא דרב חסדא אמר לך רב חסדא כי תניא ההיא לאחר יאוש","אמר מר גזילה קיימת חייבין לשלם נימא תיהוי תיובתא דרמי בר חמא אמר לך רמי בר חמא כי תניא ההיא"],[[0,"מתני' הגוזל ומאכיל","והניח לפניהם. או שהניח לפניהם הגזילה קיימת:"],[0,"פטורים מלשלם","בגמרא מפרש טעמא:"],[0,"אם היה דבר כו'","בגמ' מפרשי לה מר הכי ומר הכי:"],[1,"גמ' ברשותיה דמריה קאי","וזה שאכלו נעשה כגוזלו מבעליו:"],[3,"זאת אומרת","דקתני והניח לפניהם פטורין:"],[3,"רשות יורש כרשות לוקח דמי","והויא לה כרשות אחרת וכיון דאוקימנא למתניתין לאחר יאוש קני להו יתמי ביאוש ושינוי רשות דאי ביאוש כדי לא קני מדלא קתני פטורא באבוהון:"],[4,"כשאכלום","לאחר מיתת אביהן ונגזל אין יכול לתובען שהרי לא גזלוהו:"],[5,"והא מדקתני סיפא אם היה דבר שיש בו אחריות","כגון דבר הניכר לרבים ונראה כל שעה כעין קרקע או כגון טלית וכסות:"],[5,"חייבים להחזירה","מפני כבוד אביהן שהבריות אומרות זו טלית שגזל פלוני:"],[5,"מכלל דבגזילה קיימת עסקינן","ואפ\"ה היכא דלאו משום כבוד פטר להו ברישא במתני':"],[5,"הכי קאמר אם הניח להן אביהן","קרקעות משלו אפילו אכלו את הגזילה חייבין דאשתעביד נכסים דאבוהון מחיים:"],[6,"לא דבר שיש בו אחריות ממש","לא שגזל קרקע והניחה לפניהן:"],[6,"אלא אפילו גזל פרה וחרש בה או חמור ומחמר אחריו","והכל מעידין שהיה דנגזל חייבין אלמא בגזילה קיימת עסקינן:"],[7,"אמר רבא כי שכיבנא רבי אושעיא נפק לוותי","יצא לקראתי:"],[7,"דמתריצנא למתניתין כוותיה","באחריות ממש ובשאין גזילה קיימת וחסורי מיחסרא ולא מוקי לה בדבר המסויים ובגזילה קיימת כרבי [דכיון דאשכחן הכי מתריצנא לה מתניתין כברייתא ולא חיישינן למאי דמתני רבי לר' שמעון בריה דברייתא קיימא כוותיה]:"],[7,"גזילה קיימת","שלא אכלוה אחרי מותו ותבען הנגזל:"],[7,"חייבין","דרשות יורש לאו כרשות לוקח דמי ויאוש כדי לא קני:"],[7,"אין גזילה קיימת","שאכלוה אחרי מותו:"],[7,"חייבין לשלם","דאשתעבוד נכסיה:"],[8,"דרב חסדא","דאמר לעיל רצה מזה גובה:"],[8,"לאחר יאוש","ואכלוה:"],[9,"תיהוי תיובתא דרמי בר חמא","כיון דלאחר יאוש אוקימתה:"]],[[0,"מתני' הגוזל ומאכיל","לאו דוקא מאכיל דה\"ה נותן להם דפטורין לרב חסדא דמוקי בגמרא מתניתין לאחר יאוש דהוה ליה יאוש ושינוי רשות אלא אורחא דמילתא נקט אי נמי דוקא נקט מאכיל אפי' לרב חסדא דלא חשיב שינוי רשות במה שנותן לבניו הסמוכין על שולחנו אפילו לשמואל דאמר בבבא מציעא (דף יב.) דמציאתן לעצמן כיון דלאכילה נותן להם ומזונותיו עליו לא חשיב שינוי רשות ומיהו לרב דאית ליה יאוש כדי קני ואמר נמי בפירקין (דף קטו.) דאית ליה דרב חסדא וא\"כ לדידיה נמי צריך לאוקמי מתניתין לאחר יאוש כדמוקי רב חסדא לדידיה ודאי מאכיל לאו דוקא דה\"ה נותן ועוד י\"ל דלרב נמי מאכיל דוקא ובדבר המסויים:"],[1,"גזל ולא נתייאשו הבעלים ובא אחר כו'","אבל נתייאשו אין גובה אלא מן הראשון כיון דאכלו האחרון ואפי' היכא דאילו לא אכלו היה חייב להחזיר כגון היכא דליכא שינוי רשות שנתייאש אחר שבא ליד השני וכן משמע לקמן דאוקים רב חסדא ברייתא דר' אושעיא דקתני גזילה קיימת חייבין אחר יאוש משום דרשות יורש לאו כרשות לוקח דמי כדרבא ואפ\"ה אין גזילה קיימת קתני דפטור ותימה כיון דכי הגזילה קיימת חייבין אמאי פטורין כשאכלום וכן קשה לרמי בר חמא דמוקי לה לפני יאוש ועוד לרב חסדא ולרבא כיון דרשות יורש לאו כרשות לוקח דמי מה לי לפני יאוש מה לי לאחר יאוש אפי' אין גזילה קיימת חייבין וי\"ל דדרשינן מקרא לקמן בשמעתין דפטור באין גזילה קיימת אשר גזל אם כעין שגזל יחזיר מכאן אמרו הגוזל ומאכיל כו' ומסתברא ליה לרב חסדא לאוקמי קרא דדוקא לאחר יאוש ורמי בר חמא מוקי לה אף לפני יאוש ומיהו לרב דאמר יאוש כדי קני וסבר נמי כרב חסדא לדידיה צ\"ל דאסמכתא היא דבלאו קרא נמי פטורין כיון דביאוש כדי קני ומה שבגזילה קיימת חייבין נפרש בסמוך בע\"ה ומיהו קשה למ\"ד במרובה (לעיל בבא קמא דף סז.) דשינוי לא קני ודריש והשיב הגזילה מ\"מ ולא דריש אשר גזל אם כעין אשר גזל יחזיר אלא למעוטי גזל אביו מנא ליה האי דרשה ואין לומר דאותו אמורא יסבור דיאוש כדי קני דהשתא לא צריך להאי דרשה ואסמכתא היא דהא ר' חייא בר אבא אמר ר' יוחנן דריש בריש הגוזל (לעיל בבא קמא דף צד:) דבר תורה גזילה המשתנית חוזרת בעין מוהשיב את הגזילה מ\"מ ולית ליה דרשה כעין שגזל וסובר במרובה (לעיל בבא קמא דף סח:) ובפירקין דיאוש כדי לא קני וא\"כ מנליה באין גזילה קיימת דפטורין מלשלם לכך נראה דהך דרשה דלקמן אסמכתא היא לכ\"ע ומסברא מחלק רב חסדא בין לפני יאוש בין לאחר יאוש דלא הוי כל כך ברשות מריה אחר יאוש כמו לפני יאוש שנקל לצאת מרשות בעלים בשינוי רשות או בשינוי השם ואין זה דוחק דכי הוה מפקינן נמי מקרא צריך סברא זו דאמאי מוקמינן קרא טפי אחר יאוש מלפני יאוש כיון דגם אחר יאוש חשיבא ברשות מריה ולרמי בר חמא ניחא טפי דאיהו לית ליה טעמא דרשות מריה כלל דכיון שהוא לא גזלן אינו יכול לתובעו כלל שהרי אין לגמרי ברשות מריה שהרי אינו יכול (לו) להקדישו וגם הגזלן יכול לקנותו בשינוי מעשה ותדע דהא רב חסדא הוצרך לפרש מ\"ט כו' וגמרא נמי פריך ליה ממתניתין:"],[5,"ואם הניח להן אביהן אחריות נכסים חייבין לשלם","למ\"ד מלוה על פה אין גובה לא מן היורשים ולא מן הלקוחות בגט פשוט (ב\"ב דף קעה:) איכא לאוקמי כשעמד בדין דהוה כמלוה בשטר כדמוכח בכמה דוכתי: [ועי' תוס' לעיל (בבא קמא קד:) ד\"ה מלוה ע\"פ]:"],[7,"דמתריצנא מתניתין כוותיה","כך היה רגיל לתרץ משניות כמותו כדאשכחן באיזהו נשך (ב\"מ דף סב:) גבי כיצד לקח הימנו חיטים אבל בשביל שהיה מתרץ משנה אחת לא היה אומר כן:"],[7,"אין גזילה קיימת פטורין לימא תיהוי תיובתא דרב חסדא","מרישא דקתני הגוזל ומאכיל את בניו פטורין ה\"מ למפרך לרב חסדא כל כמה דלא ידע דלאחר יאוש מיירי כי היכי דפריך ליה לעיל ממתניתין אלא משום דניחא ליה למפרך מסיפא משום דפריך מינה לתרוייהו לרמי בר חמא ולרב חסדא:"],[8,"רב חסדא מוקי לה לאחר יאוש","וא\"ת רב דסבר יאוש כדי קני וסבר נמי כרב חסדא וע\"כ צריך לאוקמי נמי לאחר יאוש א\"כ כי גזילה קיימת אמאי חייבין כיון דיאוש כדי קני וי\"ל דרב מוקי לה בדבר המסויים והא דקתני אין גזילה קיימת פטורין ה\"ה דה\"מ לפלוגי בגזילה קיימת גופה בין דבר המסויים לשאין מסויים אלא דניחא ליה לאשמועינן דאפילו בדבר המסויים באין גזילה קיימת פטורין אע\"ג דאוושא מילתא שאכלו מה שגזל אביהן וכן ברייתא דלקמן דקתני הגוזל ומאכיל את בניו פטורין מלשלם ומיבעי ליה לאוקמי אליבא דרב חסדא לאחר יאוש לרב צריך לאוקמי בדבר המסויים מדקתני אם הניח לבניו גדולים חייבין לשלם וכן באידך קתני בין גדולים בין קטנים חייבין ואי בדבר שאינו מסויים אמאי חייבין לרב כיון דאיירי לאחר יאוש ופליגי הני ברייתות אליבא דרב אם קטנים חייבין משום כבוד אביהן אי לאו והא כסומכוס והא כרבנן דפלוגתא דסומכוס ורבנן בסמוך מיבעי ליה לאוקמי אליבא דרב דפליגי בהכי אי שייך בקטנים טעמא דכבוד אביהן אי לא אבל לרמי בר חמא דמיירי ברייתות לפני יאוש ולרב חסדא דאיירי לאחר יאוש פליגי בגזילה גמורה שביד קטן ולא קנאה קטן אם מקבלין עדים להוציא מידו או לא וכן פלוגתא דסומכוס ורבנן:"]]],[["לפני יאוש","רב אדא בר אהבה מתני להא דרמי בר חמא אהא הניח להן אביהן מעות של רבית אע\"פ שיודעין שהן של רבית אין חייבין להחזיר אמר רמי בר חמא זאת אומרת רשות יורש כרשות לוקח דמי","רבא אמר לעולם אימא לך רשות יורש לאו כרשות לוקח דמי ושאני הכא דאמר קרא (ויקרא כה, לו) אל תקח מאתו נשך ותרבית אהדר ליה כי היכי דנחי בהדך לדידיה קא מזהר ליה רחמנא לבריה לא מזהר ליה רחמנא","מאן דמתני לה אברייתא כ\"ש אמתניתין מאן דמתני לה אמתניתין אבל אברייתא רמי בר חמא כרבא מתני לה","ת\"ר הגוזל ומאכיל את בניו פטורין מלשלם הניח לפניהם גדולים חייבין לשלם קטנים פטורין מלשלם ואם אמרו גדולים אין אנו יודעין חשבונות שחשב אבינו עמך פטורין","משום דאמרי אין אנו יודעין פטורים אמר רבא הכי קאמר גדולים שאמרו יודעים אנו חשבונות שחשב אבינו עמך ולא פש לך גביה ולא מידי פטורין","תניא אידך הגוזל ומאכיל בניו פטורין מלשלם הניח לפניהם ואכלום בין גדולים בין קטנים חייבין קטנים מי מיחייבי לא יהא אלא דאזיק אזוקי א\"ר פפא הכי קאמר הניח לפניהם ועדיין לא אכלום בין גדולים בין קטנים חייבין","אמר רבא הניח להם אביהם פרה שאולה משתמשין בה כל ימי שאלתה מתה אין חייבין באונסיה כסבורים של אביהם היא וטבחוה ואכלוה משלמין דמי בשר בזול הניח להם אביהם אחריות נכסים חייבין לשלם","איכא דמתני לה ארישא ואיכא דמתני לה אסיפא","מאן דמתני לה ארישא כל שכן אסיפא ופליגא דרב פפא מאן דמתני לה אסיפא אבל ארישא לא והיינו דרב פפא","דא\"ר פפא היתה פרה גנובה לו וטבחה בשבת חייב שכבר חייב בגניבה קודם שיבא לידי איסור שבת היתה פרה שאולה לו וטבחה בשבת פטור שאיסור שבת ואיסור גניבה באין כאחד","ת\"ר (ויקרא ה, כג) והשיב את הגזילה אשר גזל מה ת\"ל אשר גזל יחזיר כעין שגזל","מכאן אמרו הגוזל ומאכיל את בניו פטורין מלשלם הניח לפניהם בין גדולים בין קטנים חייבין משום סומכוס אמרו גדולים חייבין קטנים פטורין","בר חמוה דרבי ירמיה טרק גלי באפיה דרבי ירמיה אתא לקמיה דרבי אבין","אמר שלו הוא תובע א\"ל והא מייתינא סהדי דאחזקי ביה בחיי דאבוה א\"ל וכי מקבלין עדים"],[[0,"לפני יאוש","דשינוי רשות בלא יאוש לא קני וכי אין גזילה קיימת שאכלוה אחרי מות אביהן פטורין דלית ליה דרב חסדא:"],[3,"מאן דמתני לה","להא דרמי בר חמא אברייתא כ\"ש אמתניתין דליכא טעמא אחרינא למפטריה אלא האי כל כמה דלא מחסרת לה למתניתין משמע דגזילה קיימת:"],[3,"מאן דמתני לה אמתניתין אבל אברייתא רמי בר חמא","משום טעמא דקרא מתני לה כרבא. ל\"א איפכא גרסינן מאן דמתני לה אמתני' כ\"ש אברייתא דמתניתין איכא לאוקמא בשאכלום אבל ברייתא קתני שיודעין שהן של רבית אלמא דקיימי בעין וקתני פטורים דרשות יורש כרשות לוקח ומאן דמתני לה אברייתא אבל אמתניתין רמי בר חמא בשאכלום מתני לה כרבא וראשון שמעתיו ועיקר:"],[4,"קטנים פטורים","דלאו בני דינא נינהו ואע\"פ דגזילה קיימת מיהו מחסרא גוביינא וסומכוס הוא דפטר קטנים לקמן:"],[4,"גדולים חייבים","ורמי בר חמא מוקי לה לפני יאוש:"],[4,"ואין אנו יודעין חשבונות","ושמא אבינו חישב לך דמים:"],[5,"משום דאין יודעים פטורים","בתמיה הואיל ויודעים שבגזילה באה לידו דברי ושמא הוא וברי עדיף:"],[6,"לא יהא אלא דאזיק אזוקי","נכנס לחצר דנגזל והזיקו מי מחייבי קטנים לשלם והא אנן תנן לעיל (בבא קמא דף פז.) והם שחבלו באחרים פטורים והכא כיון דאכלום מאן כפי להו לשלומי:"],[6,"הניח לפניהם","ועדיין לא אכלום אפילו קטנים חייבים כיון דגזילה קיימת ברשותא דמרה הוא ורבנן הוא דפליגי עליה דסומכוס ולא תקשי אברייתא דלעיל דאמר גדולים חייבין קטנים פטורים:"],[7,"אין חייבין באונסיה","דלא קבילו עלייהו נטירותא:"],[7,"בזול","כל זוזא חשבינא בארבע דנקי וכן כל היכא דתני בזול בפרק מי שמת (ב\"ב דף קמו:) והיינו שני שלישי דמים וכולהו דמים לא נשלמו דאי הוו ידעי דבעו שלומי לא הוו אכלי בשרא והעור יחזירנו כמות שהוא:"],[8,"איכא דמתני להא","הניח להן אביהן אחריות נכסים חייבין:"],[8,"ארישא","דקאמר מתה אין חייבין באונסיה ואם הניח להן אביהן קרקעות חייבין לשלם דאשתעבוד נכסים מחיים דאבוהון דקסבר רבא חיוב אונסים משעת שאלה מוטל על השואל ופליגא דרב פפא דאמר לקמן לא רמי חיוב אונסים אשואל עד שעה שתיאנס:"],[8,"ואיכא דמתני לה אסיפא","טבחוה ואכלוה משלמים דמי בשר בזול ואם הניח להן אביהן קרקע משלמין פרעון שלם דהוו אינהו במקום אבוהון והואיל והן אכלוה משלמין:"],[9,"אבל ארישא","דמתה כדרכה לא דלא אמרינן אשתעבוד נכסים דלא רמי חיוב אונסין על השואל עד שעת אונסין והכא כי אתניסא ליתיה לשואל והני לא קבול עלייהו מידי:"],[10,"והיינו דרב פפא דאמר היתה פרה גנובה לו","כלומר גנב פרה מערב שבת וטבח בשבת חייב אף בתשלומין ארבעה וחמשה שהרי נתחייב בקרן קודם שיבא לידי איסור סקילה ואף על גב דקנסא לא אתי עליה עד שבת לא פטרינא ליה מקנסא משום חיוב מיתה דאמר באלו נערות (כתובות דף לד:) קנס חידוש הוא שחידשה תורה הלכך אע\"ג דמקטיל משלם:"],[10,"היתה פרה שאולה לו וטבחה בשבת פטור","מן הכל דלא אמרינן משעת שאלה מחייב ליה אקרנא וקמה ברשותיה אפילו למלאך המות אלא בשעת טביחה הוא דגזליה ואיסור שבת וגניבה באין כאחד ונפטר מן הקרן משום דקם ליה בדרבה מיניה וקנסא ליכא דהא אין כפל ולא ארבעה וחמשה אלא בגנב עצמו שגנב מבית בעלים או בשומר חנם הבא לפטור עצמו בטענת גניבה אבל שואל ונושא שכר ושוכר שאין יכולין להפטר בטענת גנב אין בהן כפל כדאמר בכמה דוכתי לא אם אמרת בשומר חנם שכן משלם תשלומי כפל תאמר בש\"ש כו': שאם אין גניבה אין טביחה ואין מכירה לא גרס ליה ואנן שמעינן כאן ובכתובות וכן פירש לנו רבינו שאם אין גניבה אחר שפטור מן הקרן משום דקם ליה בדרבה מיניה אין טביחה קנס נמי לא משלם ואף על גב דחידוש הוא ואין מיתה פוטרתו הכא דליכא קרן פטור דתשלומי ארבעה וחמשה אמר רחמנא ולא תשלומי ג' וד' וכי מדלית מהכא קרנא הוו להו ג' לצאן וד' לבקר. ולא היה לי לב להבין את מושל שטעם זה אין צריך לכאן שהרי אין קנס בשואל הטובח ואפילו אמרינן כרב פפא דעד השתא קם ברשותא דמרה אפילו הכי גזלן נעשה עליה ולא גנב שאין דין גנב אלא בטוען טענת גנב והוה שומר חנם וכי גרס ליה בכתובות גרסינן ליה ובמלתא דרבא דאמר התם גנב וטבח בשבת פטור שאם אין גניבה כו' דהתם בגנב עצמו קאי וליכא למיפטריה מקנסא אלא משום האי טעמא אבל בדרב פפא ליכא למגרסא לא התם ולא הכא ואיידי דמילתא דרב פפא איתמר התם גבי מלתא דרבא איגרסא נמי אגב שטפא בדרב פפא ותשובות רב האי גאון מסייעא לי:"],[11,"כעין שגזל","כלומר אם גזילה קיימת יחזיר אבל אין גזילה קיימת פטור ובדידיה ליכא לאוקמה אלא בבניו:"],[13,"בר חמוה דרבי ירמיה","קטן הוה:"],[13,"טרק גלי","דלת פתוחה בבית אביו סגר ולא הניח ליכנס לפי שהיה רוצה רבי ירמיה להחזיק בה:"],[14,"דאחזקי בה בחיי דאבוה","והיה טוען שאביו מכרה לו או נתנה לו:"]],[[1,"אע\"פ שהן יודעין שהם של רבית כו'","וא\"ת והיכי מדקדק מינה דכרשות לוקח דמי דאפילו לאו כרשות לוקח דמי א\"ש דפטורין כיון דמדעת נתן לו ליתנהו גביה בתורת גזילה אלא בתורת הלואה ולכך אין חייבין להחזיר דמלוה על פה אינו גובה מן היורשין וי\"ל דאע\"ג דמדעת נתנם לו איתנייהו גביה בתורת גזילה דהוי כנתינה בטעות דלא נתן לשם מתנה אלא בתורת רבית ומיקרי גזילה בעיניה כיון שהמעות בעין והיו חייבין להחזיר אי לאו דכרשות לוקח דמי והוי שנוי רשות:"],[5,"ולא פש לך גביה ולא מידי פטורין","מגו שהיו יכולין לומר החזרנו לך א\"נ כגון שאין עדי גזילה אלא הודאת הבנים בלבד:"],[12,"קטנים והא אמר קטנים פטורי'","ל\"ג דהא לאו קושיא היא דההיא דלעיל כסומכוס והך כרבנן כדפירש בקונטרס אלא ה\"ג בכל הספרים ואכילת קטן מידי מששא אית ביה לא יהא אלא מזיק ותנן חש\"ו פגיעתן רעה כו' וה\"נ ה\"מ למפרך מאכילת גדולים אמאי חייבין כי אכלו לרב חסדא לאחר יאוש ולרמי בר חמא לפני יאוש אע\"ג דכי גזילה קיימת חייבין כי אכלו פטורים כדפ\"ל אלא פריך טפי להדיא אקטנים וליכא לאוקמי כגון שהניח להן אביהן אחריות נכסים ולהכי א\"ש הא דגדולים חייבין לשלם אבל קטנים קשה דמ\"מ יש לפטור מטעם דאין מקבלין עדות אלא בפני בעל דין דהא לא פטורים מהאי טעמא אלא לסומכוס ולא לרבנן:"]]],[["שלא בפני בעל דין ולא והא קתני בין גדולים בין קטנים חייבין א\"ל הרי מחלוקת סומכוס בצידך אמר איכפל כולי עלמא וקאי כסומכוס לאפקוען לדידי","אדהכי איגלגל מילתא אתא ומטא לקמיה דרבי אבהו אמר לא שמיע לכו הא דרב יוסף בר חמא א\"ר אושעיא דאמר רב יוסף בר חמא אמר רבי אושעיא תינוק שתקף בעבדיו וירד לתוך שדה של חבירו ואמר שלי הוא אין אומרים נמתין עד שיגדיל אלא מוציאין מידו מיד ולכשיגדיל יביא עדים ונראה","מי דמי התם הוא דמפקינן מיניה דלא קיימא ליה אחזקה דאבוה אבל היכא דאית ליה חזקה דאבוה לא","אמר רב אשי א\"ר שבתאי מקבלין עדים שלא בפני בעל דין תהי בה ר' יוחנן וכי מקבלין עדים שלא בפני בעל דין","קיבלה מיניה ר' יוסי בר חנינא כגון שהיה הוא חולה או עדיו חולים או שהיו עדיו מבקשין לילך למדינת הים ושלחו לו ולא בא","אמר רב יהודה אמר שמואל מקבלין עדים שלא בפני בעל דין אמר מר עוקבא לדידי מיפרשא לי מיניה דשמואל כגון דפתחו ליה בדיניה ושלחו ליה ולא אתא אבל לא פתחו ליה בדינא מצי א\"ל אנא לב\"ד הגדול אזילנא","אי הכי כי פתחו ליה נמי מצי א\"ל לב\"ד הגדול אזילנא אמר רבינא כגון דנקט דיסקא מבית דין הגדול","אמר רב מקיימין את השטר שלא בפני בעל דין ור' יוחנן אמר אין מקיימין את השטר שלא בפני בעל דין א\"ל רב ששת לרבי יוסי בר אבהו אסברה לך טעמיה דרבי יוחנן אמר קרא (שמות כא, כט) והועד בבעליו ולא ישמרנו אמרה תורה יבא בעל השור ויעמוד על שורו","אמר רבא הלכתא מקיימין את השטר שלא בפני בעל דין ואפי' עומד וצווח ואי אמר נקיטו לי זימנא עד דמייתינא סהדי ומרענא ליה לשטרא נקטינן ליה אי אתא אתא אי לא אתא נטרינן ליה בה\"ב","אי לא אתא כתבינן פתיחא עלויה תשעין יומין תלתין קמאי לא נחתינן לנכסיה דאמר קא טרח בזוזי וניזוף מציעאי נמי לא נחתינן ליה לנכסיה דאמר דלמא לא אשכח למיזף וקא טרח ומזבין בתראי נמי לא נחתינן לנכסיה דאמר לוקח גופיה קא טרח בזוזי","לא אתא כתבינן אדרכתא אניכסיה והני מילי דאמר אתינא אבל אמר לא אתינא לאלתר כתבינן","והני מילי במלוה אבל בפקדון לאלתר כתבינן","וכי כתבינן אמקרקעי אבל אמטלטלי לא דלמא שמיט ואכיל להו מלוה למטלטלי וכי אתי לוה ומייתי סהדי ומרע ליה לשטרא לא משכח מידי למיגבה","ואי אית ליה מקרקעי למלוה כתבינן ולא היא אדרכתא אמטלטלי לא כתבינן אף על גב דאית ליה מקרקעי חיישינן שמא תכסיף","וכי כתבינן אדרכתא מודעינן ליה והני מילי דמיקרב אבל מירחק לא","ואי מירחק ואיכא קרובים אי נמי איכא שיירתא דאזלי ואתו התם משהינן ליה תריסר ירחי שתא עד דאזלא ואתי שיירתא כי הא דרבינא שהא למר אחא תריסר ירחי שתא עד דאזלא ואתייא שיירתא מבי חוזאי","ולא היא התם איניש אלימא הוה אי הויא מטיא אדרכתא לידיה לא הוה אפשר לאפוקי מיניה אבל הכא לא נטרינן ליה אלא עד דאזיל שליחא בתלתא בשבתא ואתא בארבעה בשבתא ולחמשא בשבתא קאי בדיניה","אמר רבינא האי שלוחא דרבנן מהימנינן ליה כבי תרי וה\"מ לשמתא אבל לפתיחא כיון דממונא קא מחסר ליה דקא בעי ליה למיתב ליה זוזי לספרא לא","אמר רבינא יהבינן זימנא אפומא דאיתתא ואפומא דשיבבי ולא אמרן אלא דליתיה במתא"],[[0,"שלא בפני בעל דין","והאי קטן כמאן דליתיה דמי:"],[1,"שתקף בעבדיו","שלקח עבדיו עמו שיסייעוהו [לישנא אחרינא שתקף בעבדיו ואמר שלי הן]:"],[1,"ונראה","אם שלו הוא:"],[2,"התם","הוא דירד לתוך שדה חבירו דלית ליה להך תינוק בהך שדה חזקה דאבוה אבל היכא דאית ליה להאי תינוק בבית זה חזקה דאבוה לא מפקינן ליה מיניה ולכשיגדיל יביא רבי ירמיה עדיו וידון עמו:"],[4,"חולים","מסוכנים למות ואם לא עכשיו אימתי:"],[5,"לב\"ד הגדול","שבארץ ישראל:"],[6,"כגון דנקט","בעל דין חבירו:"],[6,"דסקא","אגרת מב\"ד הגדול ששלחו לב\"ד של כאן [לכופו]:"],[7,"מקיימים את השטר","היו עדים החתומים מבקשים לילך למדינת הים מביאן מלוה לב\"ד ומעידין על כתב ידן ובית דין כותבין תחתיו במותב תלתא הוינא ואתו פלוני ופלוני ואסהידו אחתימת ידייהו ואשרנוהי וקיימנוהי כדחזי:"],[8,"ואע\"פ שעומד","בעל דין וצווח אל תקיימוהו מזויף הוא אין חוששין:"],[9,"פתיחא","שטר שמתא על שאין פורע החוב:"],[10,"אדרכתא","פסק דין לירד המלוה לתוך נכסים של לוה וליטלם בשומא בחובו:"],[13,"שמא תכסיף","קרקעות של מלוה תבור ותפחות מדמיה:"],[15,"מר אחא","זה שמו והיה לו חוב על חבירו ולא היה הלוה בעיר:"],[15,"שני וחמישי","בתי דינין קבועים בעיירות תקנת עזרא בפרק מרובה (לעיל בבא קמא דף פב.):"],[17,"שליח דרבנן","שהלך להזמין איש לדין וחזר ואמר לב\"ד אינו רוצה לבא:"],[17,"מהימנינן ליה כבי תרי","דלא משקר בבי דינא:"],[17,"פתיחא","שטר שמתא וכי שרו ליה שמתא לא שרו ליה עד דיהיב זוזא דפתיחא לספרא:"],[18,"יהבינן זמנא","מזמנין בעל דין ליום פלוני לדין:"],[18,"על פי אשה","ההולכת אצלו לפי דרכה או ע\"פ שכיניו וסמכינן עלייהו דעבדין שליחותייהו אי לא אתי מחזקינן באפקרותא ומשמתינן ליה:"],[18,"אלא דליתיה במתא","שאין אותו פלוני עכשיו בעיר שב\"ד בה ואמר לשכניו כשישוב פלוני אמרו לו לבא:"]],[[2,"אבל היכא דאית ליה חזקה דאבהתא כו'","משמע דהיינו אפי' היה רבי ירמיה בתוך הבית מדלא מפליג התם בעל השדה מוחזק בשדה הכא רבי ירמיה לא היה מוחזק משמע דלא תלי בהכי מידי אלא במה דאית ליה חזקה מאבות אפילו היה רבי ירמיה מוחזק בבית:"],[4,"ושלחו לו ולא בא","אור\"י דמשמע דבעי שלחו לו ולא בא בהדי שהיו עדיו חולים או שהיו מבקשין לילך למדינת הים מדלא קאמר או שלחו כדקאמר או שהיו עדיו חולים או שהיו כו' ומיהו בסמוך משמע דבעי למימר או ושלחו דקאמר כגון דפתחו ליה בדיניה ושלחו ליה ולא אתא משמע דמשום האי מילתא לחודיה דשלחו לו ולא אתא מקבלין עדים שלא בפני בעל דין ויש לדחות דשאני התם דפתחו ליה בדיניה ודין גדול הוא זה [ויש ספרים שכתוב בהן או שלחו אחריו ולא בא] וצ\"ע בספרים ישנים ובפי' ר\"ח ובספר ישן נמצא כתוב ושלחו לו:"],[6,"מצי טעין לב\"ד הגדול קאזילנא כו'","פירש בה\"ג ומצי נתבע לאשתמוטי בהכי והיה נראה לומר דדוקא נתבע יכול לפטור עצמו בכך אבל לא תובע דאל\"כ כל אדם יאמר לחבירו או תן לי מנה או בא עמי לב\"ד הגדול אבל נראה לר\"ת דכ\"ש תובע דהשתא נתבע שנראה עושה ערמה כדי לפטור עצמו ממה שזה תובעו מצי למימר הכי כ\"ש תובע שמתחילה תובע כך ואין נראה כמערים ועוד דאפילו לוה דעבד לוה לאיש מלוה מצי למימר לב\"ד הגדול קאזלינא כ\"ש מלוה ואע\"ג דאמר בפרק זה בורר (סנהדרין דף לא: ושם) אמר אמימר הלכתא כופין אותו והולך עמו למקום הועד ומסיק דהני מילי מלוה אבל לוה עבד לאיש מלוה ולא מ\"ל נלך למקום הועד בית הועד לאו היינו ב\"ד הגדול דבית הועד היינו מקום ב\"ד קבוע אבל יש ב\"ד הגדול ממנו בחכמה והילכתא אפילו לוה מצי למימר לב\"ד הגדול קאזלינא אבל לבית הועד לא מצי אמר אלא כופין אותו ודן בעירו:"],[7,"מקיימין את השטר שלא בפני בעל דין","פי' בקונט' אם עדיו מבקשין לילך למדינת הים ואין נראה לר\"י דא\"כ אמאי נקט קיום השטר הא קבלת עדים אמר נמי לעיל דבכה\"ג מקבלין שלא בפני בעל דין ונראה לר\"י דבכל ענין קאמר דמקיימין דקיום שטר דרבנן ועדים החתומים על השטר כמי שנחקרה עדותן בב\"ד דמי ואין צריך קיום ומדרבנן הוא דצריך הלכך מקיימינן שלא בפני בעל דין ורבי יוחנן דאמר אין מקיימין סבר דלא פלוג רבנן בין קיום שטרות לקבלת עדות והא דקאמר אסברה לך טעמא דר' יוחנן ה\"ק דאפילו בקיום שטרות אית ליה לר' יוחנן יבא בעל השור ויעמוד על שורו ומיהו רב נמי אית ליה בעלמא יבא בעל השור כו':"],[16,"עד דאזיל שליח בתלתא בשבתא","דמסתמא בשני דנהו:"],[17,"","דקבעי למיתב זוזא לפתיחא. כשקורעין אותה משלם הוא שכר הסופר:"]]],[["אבל איתיה במתא לא דאמרינן אימר לא אמרו ליה דאמרי אשכחינהו שליחא דב\"ד ואמר ליה","ולא אמרן אלא דלא חליף אבבא דבי דינא אבל חליף אבבא דבי דינא לא אמרי אשכחוה בי דינא ואמרי ליה","ולא אמרן אלא דאתי ביומיה אבל לא אתי ביומיה לא אימא אישתלויי אשתלי","אמר רבא האי מאן דכתיב עליה פתיחא על דלא אתי לדינא עד דאתי לדינא לא מקרעינן ליה על דלא ציית לדינא עד דציית לא מקרעינן ליה ולא היא כיון דאמר צייתנא קרעינן ליה:","אמר רב חסדא קובעים זמן שני וחמישי ושני זמנא וזמנא בתר זמנא ולמחר כתבינן","רב אסי איקלע בי רב כהנא חזא ההיא איתתא דאזמנה לדינא בפניא ובצפרא כתיב עלה פתיחא א\"ל לא סבר לה מר להא דאמר רב חסדא קובעין זמן שני וחמישי ושני","א\"ל ה\"מ גברא דאניס וליתיה במתא אבל איתתא כיון דאיתה במתא ולא אתיא מורדת היא:","אמר רב יהודה לא יהבינא זמנא לא ביומי ניסן ולא ביומי תשרי לא במעלי יומא טבא ולא במעלי שבתא אבל מניסן לבתר יומי ניסן וביומי תשרי לבתר תשרי קבעינן ממעלי שבתא לבתר מעלי שבתא לא קבעינן מאי טעמא בעבידתיה דשבתא טריד","אמר רב נחמן לא יהבינן זמנא לא לבני כלה בכלה ולא לבני ריגלא בריגלא כי הוו אתו לקמיה דרב נחמן אמר להו וכי לדידכו כנופייכו והאידנא דאיכא רמאי חיישינן:","אם היה דבר שיש בו אחריות חייב לשלם: מתני ליה רבי לר\"ש בריה לא דבר שיש בו אחריות ממש אלא אפילו פרה וחורש בה חמור ומחמר אחריו חייבין להחזיר מפני כבוד אביהן","בעי מיניה רב כהנא מרב מטה ומיסב עליה שולחן ואוכל עליו מהו אמר לו (משלי ט, ט) תן לחכם ויחכם עוד:","\u0001מתני׳\u0002 אין פורטין לא מתיבת המוכסין ולא מכיס של גבאין ואין נוטלין מהם צדקה אבל נוטל הוא מתוך ביתו או מן השוק:","\u0001גמ׳\u0002 תנא אבל נותן לו דינר ונותן לו את השאר:","ומוכסין והאמר שמואל דינא דמלכותא דינא","אמר רב חנינא בר כהנא אמר שמואל במוכס שאין לו קצבה דבי ר' ינאי אמרי במוכס העומד מאליו","איכא דמתני לה אהא לא ילבש אדם כלאים אפי' על גבי עשרה בגדים להבריח בו את המכס מתני' דלא כר\"ע דתניא אסור להבריח את המכס ר\"ש אומר משום ר\"ע מותר להבריח את המכס","בשלמא לענין כלאים בהא קמיפלגי דמר סבר דבר שאין מתכוין מותר ומר סבר דבר שאין מתכוין אסור אלא להבריח בו את המכס מי שרי והאמר שמואל דינא דמלכותא דינא","א\"ר חנינא בר כהנא אמר שמואל במוכס שאין לו קצבה דבי ר' ינאי אמרי במוכס העומד מאליו","ואיכא דמתני אהא נודרין להרגין ולחרמין ולמוכסין שהיא של תרומה שהיא של בית מלך אע\"פ שאינה של תרומה אע\"פ שאינה של מלך ולמוכסין והאמר שמואל דינא דמלכותא דינא","א\"ר חנינא בר כהנא אמר שמואל במוכס שאין לו קצבה דבי ר' ינאי אמרי במוכס העומד מאליו","רב אשי אמר במוכס כנעני דתניא ישראל וכנעני אנס שבאו לדין אם אתה יכול לזכהו בדיני ישראל זכהו ואמור לו כך דינינו בדיני כנענים זכהו ואמור לו כך דינכם ואם לאו באין עליו בעקיפין דברי ר' ישמעאל ר\"ע אומר אין באין עליו בעקיפין מפני קידוש השם","ור\"ע טעמא דאיכא קידוש השם הא ליכא קידוש השם באין","וגזל כנעני מי שרי והתניא אמר ר' שמעון דבר זה דרש ר\"ע כשבא מזפירין מנין לגזל כנעני שהוא אסור ת\"ל (ויקרא כה, מח) אחרי נמכר גאולה תהיה לו"],[[0,"אבל איתיה במתא לא","משמתינן ליה דהנהו איתתא ושיבבי לא עבדי שליחותם:"],[0,"דאמרי שליחא דבי דינא אשכחיה ואמר ליה","אלא משדרינן ליה עוד שליחות אחרינא בתריה:"],[1,"ולא אמרן אלא דלא חליף אבבא דבי דינא","כי אתי ההוא פלוני לביתיה לית ליה אורחא לבבא דבי דינא אבל חליף אבבא דבי דינא לא סמכינן אשיבבי דאמרי בי דינא אמרי ליה:"],[2,"אישתלי","שכחו שליחותם קודם ששב אותו פלוני לביתו:"],[3,"עד דאתא לבי דינא לא קרעינא ליה","ואע\"ג דאמר אתינא אתינא:"],[3,"על דלא ציית לבי דינא","שאמרו צא תן לו ולא קיים:"],[3,"עד דציית דינא","ויפרע לו:"],[3,"לא מקרעינן ליה","ואע\"ג דאמר פרענא:"],[3,"ולא היא כיון דאמר דצייתנא קרענא","לאלתר דדלמא לית ליה זוזי השתא וטרח אבל באתא לדינא כל כמה דלא אתי אפקרותא הוא:"],[5,"קובעין זמן","ליום שני בשבת ואם לא יבא מזמנין אותו ליום חמישי ואם לא יבא מזמנין אותו ליום שני ועד למחר לא כתבינן פתיחא שכל היום ממתינין שמא יבא:"],[7,"לא יהבינן זימנא ביומי ניסן","אין מזמנין אדם לדין בניסן ובתשרי שהן זמן קציר ובציר:"],[7,"אבל לבתר ניסן","שולחים שיבא ביום פלוני באייר:"],[8,"לבני כלה בכלה","באין לשמוע הדרשה בכל שבת אין אומרים לו בא ביום שני לדין דממנע ולא אתי לכלה:"],[8,"בריגלא","באין לשמוע הלכות הרגל קודם הרגל ל' יום:"],[8,"כי אתו","תובעין לקמיה דרב נחמן ביום כלה להזמין בעלי דינין לדין:"],[8,"אמר להו וכי לדידכו כנופייכו","לצורך דינכם הקהלתי אתכם:"],[10,"מטה ושלחן מהו","כיון דמידי דקאי בגו בית' הוא ולא מתחזי לעלמא כי פרה וחמור וליכא זילותא דאבוהון או דלמא כיון דנפקי ועיילי אינשי לביתייהו וחזו להו איכא זילותא:"],[10,"דאמרי שליחא דבי דינא אשכחיה ואמר ליה","אלא משדרינן ליה עוד שליחות אחרינא בתריה:"],[10,"ויחכם עוד","כפרה וחמור כן מטה ושלחן:"],[11,"מתני' אין פורטין","להחליף סלעים בפרוטות מיד מוכסים ליטול הפרוטות מתיבתן שנותנין בה מעות המכס וכן מכיס של גבאי המכס שגובה כסף גולגולת וארנונא לפי שהן של גזל:"],[11,"מתוך ביתו","של מוכס ממעות שלו:"],[11,"או מן השוק","אם יש לו מעות בשוק שאין לוקח מתיבת המכס:"],[12,"גמ' אבל נותן לו דינר","היה חייב לו פרוטות למוכס מן המכס בשוה חצי דינר ואין לו הפרוטות נותן לו דינר כסף ומקבל הימנו פרוטות בשוה חציו מפני שהוא כמציל מידו:"],[13,"דינא דמלכותא דינא","וזה שקיבל את המכס מן המלך בדבר קצוב כך וכך לשנה אין גזלן:"],[14,"שאין לו קצבה","אלא נוטל ככל חפצו:"],[14,"מאליו","שלא מאת המלך אפי' יש לו קצבה:"],[15,"כדי להבריח את המכס","ואע\"פ שאין כוונתו להנאת לבישה אלא להבריח בו בלבישת כלאים:"],[16,"דינא דמלכותא דינא","ונמצא שגוזל את המוכס ישראל זה שקיבל את המכס מיד המלך נכרי בהיתר:"],[18,"נודרין","קונם כל פירות עלי אם אין תבואה זו של בית המלך:"],[18,"הורגים","רוצחים:"],[18,"חרמים","בעלי תיגרה ומריבה וגוזלי ממון:"],[20,"במוכס שהוא כנעני אנס","ואין לחוש אם גוזלו היכא דליכא חילול השם שאין מבין שזה מכזב:"],[20,"באין עליו בעקיפין","בחכמה עד שפוטרין את הישראל:"],[22,"אחרי נמכר","בעבד עברי הנמכר לנכרי בשוק משתעי:"]],[[11,"אין פורטין לא מתיבת המוכסין","לרבנן דאמרי סתם גזילה לא הוי יאוש בעלים א\"ש ומ\"מ קתני דנותן דינר ויחזיר לו השאר הואיל ואין ידוע בברור שהם של גזל ור\"ש נמי דאמר סתם גזילה הוי יאוש בעלים דהשתא ה\"ל יאוש ושינוי רשות מ\"מ אין פורטין משום דדבר מגונה הוא דתיבה וכיס מיוחדת להצניע שם גזילות שלהם ודרכו כל שעה להניח שם:"],[16,"ומר סבר דבר שאין מתכוין מותר","ושרי אפי' ללבוש והא נמי דתניא מוכרי כסות מוכרין כדרכן ומוקי בבמה מדליקין (שבת דף כט: ושם) כרבי שמעון דשרי דבר שאין מתכוין התם נמי שרי אף ללבוש ולא שישאם דוקא על כתיפיו:"],[18,"נודרין להרגים","בנדרים (דף כח.) מפרש דאמר בשפתיו סתם יאסרו כל פירות שבעולם עלי אם אינם של תרומה ומחשב בלבו היום דאין נאסר אלא אותו יום בלבד ואע\"ג דדברים שבלב אין דברים משום אונסא שרו ליה הכי מפרש התם וה\"ה שיכול לחשוב בלבו שעה אחת או רגע וכן נוהגים כשהאנסים מדירים היהודים הדרים תחתיהם שלא יצאו לדור בעיר אחרת יכולין לידור סתם שלא יצאו ובלבם יחשבו היום ואפי' הוא מפרש בשפתיו שלא יצא ממנו כל ימי חייו יכול להערים ולחשוב בלבו שום תנאי ואם מבטל בשפתיו בלחש כ\"ש דהוי ביטול גמור :"]]],[["שלא ימשכנו ויצא יכול יגלום עליו ת\"ל (ויקרא כה, נ) וחשב עם קונהו ידקדק עם קונהו","אמר רב יוסף לא קשיא הא בכנעני הא בגר תושב","אמר ליה אביי והא תרוייהו גבי הדדי כתיבי לא לך אלא לגר שנאמר (ויקרא כה, מז) לגר ולא לגר צדק אלא לגר תושב שנאמר לגר תושב","משפחת גר זה העובד כוכבים כשהוא אומר או לעקר זה הנמכר לעבודת כוכבים","אלא אמר רבא לא קשיא כאן בגזילו וכאן בהפקעת הלוואתו","א\"ל אביי עבד עברי הפקעת הלוואתו הוא רבא לטעמיה דאמר רבא עבד עברי גופו קנוי","אמר רב ביבי בר גידל אמר ר\"ש חסידא גזל כנעני אסור אבידתו מותרת גזילו אסור דאמר רב הונא מנין לגזל הכנעני שהוא אסור שנאמר (דברים ז, טז) ואכלת את כל העמים אשר ה' אלהיך נותן לך בזמן שהן מסורים בידך ולא בזמן שאינם מסורין בידך","אבידתו מותרת דאמר רב חמא בר גורי' אמר רב מנין לאבידת הכנעני שהיא מותרת שנאמר (דברים כב, ג) לכל אבדת אחיך לאחיך אתה מחזיר ואי אתה מחזיר לכנעני","ואימא הני מילי היכא דלא אתי לידיה דלא מחייב לאהדורי בתרה אבל היכא דאתי לידיה אימא ליהדרה אמר רבינא (דברים כב, ג) ומצאתה דאתאי לידיה משמע: תניא ר' פנחס בן יאיר אומר במקום שיש חילול השם אפי' אבידתו אסור","אמר שמואל טעותו מותרת כי הא דשמואל זבן מכותי לקנא דדהבא במר דפרזלא בד' זוזי ואבלע ליה חד זוזא","רב כהנא זבן מכותי מאה ועשרים חביתא במאה ואבלע ליה חד זוזא אמר ליה חזי דעלך קא סמיכנא רבינא זבן דיקלא הוא וכותי לצלחא א\"ל לשמעיה קדם ואייתי מעיקרו דכותי מניינא ידע","רב אשי הוה קאזיל באורחא חזא שיבשא דגופנא בפרדיסא ותלי בה קיטופי דעינבי אמר ליה לשמעיה זיל חזי אי דכותי נינהו אייתי אי דישראל נינהו לא אייתי לי שמע ההוא כותי דהוה יתיב בפרדיסא אמר ליה דכותי שרי א\"ל כותי שקיל דמי ישראל לא שקיל דמי","גופא אמר שמואל דינא דמלכותא דינא אמר רבא תדע דקטלי דיקלי וגשרי גישרי ועברינן עלייהו","א\"ל אביי ודלמא משום דאייאוש להו מינייהו מרייהו אמר ליה אי לא דינא דמלכותא דינא היכי מייאשי","והא לא קא עבדי כדאמר מלכא מלכא אמר זילו וקטלו מכל באגי ואינהו אזלו וקטלו מחד באגא","שלוחא דמלכא כמלכא ולא טרח ואינהו אפסיד אנפשייהו דאיבעי להו דאינקוט מכוליה באגי ומשקל דמי","אמר רבא מאן דמשתכח בבי דרי פרע מנתא דמלכא וה\"מ שותפא אבל אריסא אריסותיה הוא דקא מפיק","ואמר רבא בר מתא אבר מתא מיעבט וה\"מ דברלא ארעא וכרגא דהאי שתא אבל שתא דחליף הואיל ואפייס מלכא חליף","ואמר רבא הני דדיירי דרי בתוך התחום אסור ליקח מהן מאי טעמא משום דמערבא חיותא דמתא בהדייהו","חוץ לתחום מותר ליקח מהם אמר רבינא אם היו בעלים מרדפים אחריהם אפילו חוץ לתחום אסור","מכריז רבא ואיתימא רב הונא דסלקין לעילא ודנחתין לתתא האי בר ישראל דידע סהדותא לכותי ולא תבעו מיניה ואזל ואסהיד ליה בדיני דכותי על ישראל חבריה משמתינן ליה מאי טעמא דאינהו מפקי ממונא"],[[0,"שלא ימשכנו ויצא","כלומר שלא יוציאוהו בית דין מיד הכותי אלא בגאולה:"],[0,"יגלום","יכול יניח את הכנעני לכפול ולהוסיף ולתבוע מה שלא נתן:"],[1,"גר תושב","אין עובד ע\"ז ואוכל נבילות:"],[2,"ולא לך אלא לגר","בקדושין היא (ד' כ.) ובערכין (דף ל:) כמה קשה אבקה של שביעית אדם שנושא ונותן בפירות שביעית סוף מוכר את עצמו שנאמר ונמכר לך לא לך אלא לכנעני כו' ולע\"ז עצמה לחטוב עצים ולשאוב מים ואכולהו קאי גאולה תהיה לו אלמא גזל כנעני אסור:"],[4,"בהפקעת הלוואתו","שאין גזל ממש שרי כי ליכא חילול השם ולהבריח המכס הוי כהפקעת הלואתו:"],[5,"הפקעת הלואתו הוא","שהלוהו על עבודתו ואפי' הכי אמר ר' עקיבא לא יצא על כרחו:"],[5,"גופו קנוי","כל שש שנים ונמצא שגזלו ממש:"],[8,"והני מילי דבורלא","אברול ארעא מס קרקע שאכל פירות:"],[9,"טעותו","היה חייב לו לישראל וטעה בחשבון דליכא חילול השם:"],[9,"לקנא דדהבא במר דפרזלא","מזרק של זהב בחזקת של נחושת:"],[9,"ואיבלע ליה זוזא","ועוד טעות אחרת שעיכב זוז מדמיו והטעהו בחשבון שלקח ג' במקום ד':"],[10,"לצלחא","לבקע:"],[10,"מעיקרו","פסקית של צד העיקר קח לצרכי שהן עבים:"],[10,"דכותי מניינא ידע","מנין הפסקים מנה אבל לא נתן עיניו כמה דקים יש וכמה גסים יש:"],[11,"שיבשא","זמורות:"],[11,"קטופי","אשכולות:"],[13,"היכי מיאשי","כלומר מי הוי יאוש הא יאוש כדי הוי ואין כאן שנוי רשות שברה\"ר הן ושינוי מעשה נמי ליכא דהשתא נמי גובא דדיקלא מקרו:"],[14,"והא לא עבדי שליחותיה כדקאמר מלכא","ואשתכח דלאו דינא דמלכותא הוא ואמאי עברינן עלייהו:"],[14,"באגא","בקעה:"],[15,"ולא טרח","אין עליו לטרוח וליקח מזה אחד ומזה אחד:"],[16,"דמשתכח בבי דרי","היו ארבעה שותפין בגורן והביאו שלשה חלקן בביתן והרביעי' נמצא בגורן:"],[16,"פרע מנתא דמלכא","בשביל כולם ולכשיבאו חביריו אין יכולין לומר שלך היה ולא שלנו ואם גבאי זה ישראל הוא שקנה מן המלך את המס אין כאן משום גזל דדינא דמלכותא דינא ואם כותי הוא מותר לקנות ממנו:"],[16,"אריסותיה מפיק","דאין לו חלק בגופו של קרקע ואין עליו לפרוע חלק על הבית ולענין זבוני לא מזבנינן מיניה דגזל הוא מה שנטלו מן האריס:"],[17,"בר מתא אבר מתא מיעבט","רשות ביד ישראל גבאי המלך למשכן בן העיר על מס בן עיר חבירו דדינא דמלכותא דינא:"],[17,"וכרגא","כסף גולגולת דשתא דא:"],[17,"אבל שתא דחליף חליף","והוא הגבאי כבר פרע למלך כל קצבה שקיבל עליו שנה שעברה ומעתה המס שלו ולו אין כח למשכן את זה על חבירו:"],[18,"דדיירי דרי","עכו\"ם שיש להם בהמות ומזבלין מהן שדות בשכר:"],[18,"אסור ליקח מהן","בהמה שמא נתחברה עם בהמותיהם של ישראל ושל בני ישראל הוא:"]],[[0,"שלא ימשכנו ויצא כו'","והני תנאי דפרק המקבל (ב\"מ דף קיא: ושם) דסברי דגזל הכנעני מותר מוקמי לה להאי קרא לדרשה אחריתי:"],[0,"יכול יגלום עליו","פי' בקונטרס יכול יניח הכנעני לכפול ולהוסיף על הלואתו לתבוע מה שלא נתן ותימה לר\"י דאמאי אצטריך קרא להכי דאטו יפסיד ויניח את הכנעני להטעות את עצמו ונראה לר\"י דה\"פ יכול יגלום עליו שיטעה את הכנעני ויתן לו פחות ממה שנתן לו ת\"ל וחשב עם קונהו וכן פי' בערוך בערך גלם אע\"ג דטעות כנעני היה מותר אסור להטעותו במקום שהכנעני יודע שגוזל ועושה עצמו כלא ידע:"],[11,"הכי קאמינא אי דכותי נינהו","נראה לר\"י שכן היה דעתו מתחילה כמו שהשיב להכותי ולא כמו שהיה הכותי סובר דא\"כ היה סובר דגזל הכותי מותר דאין חילוק בין גניבה לגזילה דבגניבה איכא חילול השם כשידע לבסוף וכל הנך שמעתא לא אייתי אלא הנהו דאסרי גזל כנעני ולא מייתי תנאי דהמקבל (שם) דשרי:"],[13,"היכי מייאשי","היה להם לתבוע בדין את כל אדם העוברים עליהם אלא ודאי לכך מתייאשים לפי שבדין אין משלמין להם כלום משום דדינא דמלכותא דינא ובקונטרס פי' היכי מייאשי כלומר מי הוי יאוש והא יאוש כדי הוא ולא קני דאין כאן שינוי רשות שהרי הן מונחים ברשות הרבים ושינוי מעשה נמי ליכא דהשתא נמי הוי גובי דדיקלי מיקרו כדאמר לעיל בהגוזל קמא (בבא קמא דף צו. ושם):"]]],[["אפומא דחד ולא אמרן אלא חד אבל בתרי לא וחד נמי לא אמרן אלא בדיני דמגיסתא אבל בי דוואר אינהו נמי חד אמומתא שדו ליה","אמר רב אשי כי הוינא בי רב הונא איבעיא לן אדם חשוב דסמכי עליה כבי תרי מפקי ממונא אפומיה ולא איבעי ליה לאסהודי או דלמא כיון דאדם חשוב הוא לא מצי משתמיט להו ומצי לאסהודי תיקו","אמר רב אשי האי בר ישראל דזבין ליה ארעא לעובד כוכבים אמצרא דבר ישראל חבריה משמתינן ליה מאי טעמא אי נימא משום דינא דבר מצרא והאמר מר זבין מעכו\"ם וזבין לעכו\"ם ליכא משום דינא דבר מצרא","אלא דאמרי' ליה ארבעית לי אריא אמצראי משמתינן ליה עד דקביל עליה כל אונסא דאתי מחמתיה:","\u0001מתני׳\u0002 נטלו מוכסין את חמורו ונתנו לו חמור אחר נטלו לסטים את כסותו ונתנו לו כסות אחרת הרי אלו שלו מפני שהבעלים מתייאשין מהן: המציל מן הנהר או מן הגייס או מן הלסטין אם נתייאשו הבעלים הרי אלו שלו וכן נחיל של דבורים אם נתייאשו הרי אלו שלו","א\"ר יוחנן בן ברוקה נאמנת אשה או קטן לומר מכאן יצא נחיל זה ומהלך בתוך שדה חבירו להציל את נחילו ואם הזיק משלם מה שהזיק אבל לא יקוץ את סוכו על מנת ליתן את הדמים ר' ישמעאל בנו של ר' יוחנן בן ברוקה אומר אף קוצץ ונותן את הדמים:","\u0001גמ׳\u0002 תנא אם נטל מחזיר לבעלים הראשונים קסבר יאוש כדי לא קני ומעיקרא באיסורא אתא לידיה","ואיכא דאמרי אם בא להחזיר יחזיר לבעלים ראשונים מ\"ט יאוש כדי קני מיהו אי אמר אי אפשי בממון שאינו שלי מחזיר לבעלים הראשונים:","הרי אלו שלו מפני שהבעלים כו': אמר רב אשי לא שנו אלא לסטים עובד כוכבים אבל ליסטים ישראל לא סבר למחר נקיטנא ליה בדינא","מתקיף לה רב יוסף אדרבה איפכא מסתברא עכו\"ם דדייני בגיתי לא מייאש ישראל כיון דאמרי מימר מייאש","אלא אי איתמר אסיפא איתמר המציל מן העכו\"ם ומן הלסטים אם נתייאשו הבעלים אין סתמא לא","לא שנו אלא עכו\"ם משום דדייני בגיתי אבל לסטים ישראל כיון דאמרי מימר מייאש","תנן התם עורות של בעל הבית מחשבה מטמאתן","ושל עבדן אין מחשבה מטמאתן","של גזלן אין מחשבה מטמאתן ושל גנב מחשבה מטמאתן","ר\"ש אומר חילוף הדברים של גזלן מחשבה מטמאתן של גנב אין מחשבה מטמאתן לפי שלא נתייאשו הבעלים","אמר עולא מחלוקת בסתם אבל בידוע דברי הכל יאוש קני רבה אמר בידוע נמי מחלוקת","א\"ל אביי לרבה לא תיפלוג עליה דעולא דתנן במתני' כוותיה לפי שלא נתייאשו הבעלים טעמא דלא נתייאשו הבעלים אבל נתייאשו הבעלים הרי אלו שלו","אמר ליה אנן לפי שאין יאוש לבעלים מתנינן לה","תנן נטלו מוכסין חמורו כו' מני","אי רבנן קשיא גזלן אי ר\"ש קשיא גנב","בשלמא לעולא דאמר בידוע קני הכא נמי בידוע ודברי הכל","אלא לרבה דאמר בידוע נמי מחלוקת הא מני לא רבנן ולא ר\"ש בלסטים מזויין ור\"ש היא","אי הכי היינו גזלן תרי גווני גזלן","ת\"ש הגנב והגזלן והאנס הקדשן הקדש ותרומתן תרומה ומעשרותן מעשר","מני אי רבנן קשיא גזלן אי ר\"ש קשיא גנב","בשלמא לעולא דאמר בידוע קני הכא נמי בידוע ודברי הכל היא אלא לרבה דאמר בידוע נמי מחלוקת הא מני לא רבנן ולא ר\"ש","הכא נמי בלסטים מזויין ור' שמעון היא אי הכי היינו גזלן תרי גווני גזלן","ואי בעית אימא הא מתניתא רבי היא דתניא רבי אמר גנב כגזלן"],[[0,"אפומא דחד","ונמצא שהפסידו שלא כדין:"],[0,"דמגיסתא","בני כפר שאין יודעין לדון במשפט:"],[0,"בי דוואר","שלטון:"],[0,"חד אמומתא שדו ליה","על פי עד אחד אין מוציאין ממון אבל מחייבין בעל דין שבועה להכחיש העד כדין תורה לשון אחר דמגוזתא אנסין בחזקה כמו אתו גוזאי וקא מחו ליה (מגילה כח.) סריסים (של בית רבי) העומדין לרדות בחזקה:"],[2,"והאמר מר זבין מעכו\"ם כו'","בבבא מציעא בהמקבל:"],[3,"ארבעית","הרבעת:"],[4,"מתני' הרי אלו שלו","דמסתמא נתייאשו הבעלים מיד וקננהו היאך ביאוש ושינוי רשות:"],[4,"אם נתייאשו","הבעלים דשמעינן דאייאוש דאמר ווי לחסרון כיס אבל סתמא לא וקשיא לסטים דסיפא אלסטים דרישא ובגמרא פריך ומשני לה חדא בלסטים עכו\"ם וחדא בליסטים ישראל דמייאש מסתמא:"],[4,"נחיל","גיור\"א:"],[5,"לא יקוץ את הסוכה","נתיישבו דבורים על סוכת חבירו וירא ליטלן אחת אחת שלא יברחו לא יקוץ את הסוכה להוליכן כולן ביחד ואפילו ע\"מ ליתן דמים:"],[6,"גמ' אם נטל","חמור מן המוכסין:"],[6,"יחזיר לראשונים","ופליגא ברייתא אמתני':"],[6,"יאוש כדי","שנתייאשו הבעלים ביד מוכס לא קנה המוכס ביאוש לבדו בלא נתינת דמים או שינוי מעשה וכי אתא ליד שני באיסור אתא לידיה\""],[7,"אם בא להחזיר","שחסיד הוא:"],[7,"יחזיר לבעלים הראשונים","ולא למוכס:"],[9,"בגיותא","בגאוה ובזרוע:"],[9,"אמרי מימר","צא ותן לו ואין חובטין במקלות לשון אחר דאמרי לנגזל מי יימר כדקאמרת הבא עדים שגנבו ממך:"],[12,"מחשבתו מטמאתן","חישב עליהם בדבר שאין בו חסרון מלאכה כגון לעוצבא ולמטה ירדו לטומאה מיד:"],[13,"ושל עבדן","שאומנותו בכך סתמיה למכירה הלכך אין מחשבתו מחשבה שאם יבאו בני אדם לקנותו ימכרנו להן ונמצא שסופן למנעלין ועדיין לא נגמרה מלאכתן לכך:"],[14,"של גזלן אין מחשבתו מטמאתן","דלאו דידיה הוא דכיון דידע מאן שקליה מיניה לא מייאש:"],[14,"ושל גנב מחשבתו מטמאתן","דאייאוש מרייהו דלא ידעי למאן יתבעו. חילוף הדברים גזלן כיון דשקליה מיניה בהדיא ולא מצי קאי באפיה מייאש גנב סבר בחישנא ליה ומשכחינא ליה:"],[16,"בסתם","דלא שמעינן דמייאש דבהא פליגי דמר סבר סתם גניבה יאוש בעלים הוא ולא סתם גזילה ומר סבר חילוף הדברים כדפרישית:"],[16,"אבל בידוע","דשמעינן דמייאש:"],[16,"דברי הכל יאוש כדי קני","ואפי' גנב לר\"ש וגזלן לרבנן:"],[16,"בידוע נמי מחלוקת","דאי נמי דשמעינן דמייאש אמרי רבנן בגזלן דלא הוי יאוש דכל שעתא דעתיה למנקטיה בדינא וכן גנב לרבי שמעון:"],[18,"שאין יאוש לבעלים","אין יאושן יאוש:"],[19,"מוכס גזלן","לסטים גנב:"],[22,"ומשני בלסטים מזויין","דגזלן הוא:"],[23,"היינו גזלן","והא תנא ליה מוכס:"],[24,"אנס","דקתני גבי גזלן הוי חמסן דיהיב זוזי:"],[27,"ורבי שמעון היא","דאמר גזלן קני:"]],[[0,"ולא אמרן אלא חד אבל בתרי לא","וא\"ת והא לעיל שרי להפקעת הלואה וא\"כ מפסידים אותו הרבה שאם היה רוצה יכול לכפור וי\"ל דמכל מקום לא משמתינן ליה כיון שאין משלם על ידם אלא מה שחייב לו:"],[2,"ליכא משום דינא דבר מצרא","פירשתי בפרק המקבל (ב\"מ דף קח:):"],[3,"עד דמקבל עילויה כו'","אומר ר\"ת דהיינו דוקא כשישראל רוצה ליתן לו כמו שנותן לו העכו\"ם אבל אם העכו\"ם רוצה ליתן לו יותר אין להפסיד בשביל כן:"],[6,"","תנא ואם נטל כו'. מפורש לעיל במרובה (בבא קמא דף סז:):"],[16,"רבה אומר בידוע נמי מחלוקת","והא דאמר במרובה (לעיל בבא קמא דף סח.) ואף רבי אלעזר סבר חיוביה לאחר יאוש כו' עד דפריך ודלמא דשמעי' דאייאש האי פירכא לא אתי אליבא דרבה דאיהו לא מפליג מידי בין סתם לידוע:"],[18,"לפי שאין יאוש לבעלים מתנינן לה","אין מגיה המשנה אלא כך מפרש שלא נתייאשו הבעלים בלבם אפילו אומרים שנתייאשו:"],[23,"היינו גזלן","ואפי' למ\"ד לסטים מזויין גנב הוא לענין שמשלם כפל אבל מ\"מ גזלן הוא דמקרי:"],[24,"ת\"ש הגנב והגזלן","ומשום דמיטמר מאינשי קרי ליה גנב אע\"ג דלא משלם כפל למ\"ד (שם) גזלן הוא:"]]],[["וקיימא לן כגזלן לר\"ש:","גופא רבי אומר אומר אני גנב כגזלן איבעיא להו כגזלן דרבנן קאמר ולא קני או דלמא כגזלן דר\"ש קאמר וקני","ת\"ש נטלו מוכסין חמורו וכו'","מני אי רבנן קשיא גזלן אי ר\"ש קשיא גנב","אי אמרת בשלמא רבי כגזלן דר\"ש קאמר וקני הא מני רבי היא משום הכי קני","אלא אי אמרת כגזלן דרבנן קאמר ולא קני הא מני לא רבי ולא ר\"ש ולא רבנן","הב\"ע בלסטים מזויין ור\"ש היא אי הכי היינו גזלן תרי גווני גזלן","ת\"ש הגנב והגזלן והאנס הקדשן הקדש ותרומתן תרומה ומעשרותן מעשר","מני אי רבנן קשיא גזלן אי ר\"ש קשיא גנב","אי אמרת בשלמא גנב כגזלן דר\"ש קאמר משום הכי קני אלא אי אמרת גנב כגזלן דרבנן הא מני","בלסטים מזויין ור\"ש היא אי הכי היינו גזלן תרי גווני גזלן","א\"ל רב אשי לרבה ת\"ש דמתני רבי לרבי שמעון בריה לא דבר שיש בו אחריות ממש אלא אפילו פרה וחורש בה חמור ומחמר אחריו חייבין להחזיר מפני כבוד אביהן","טעמא מפני כבוד אביהן הא לאו כבוד אביהן לא ש\"מ רבי גזלן דר\"ש קאמר ש\"מ:","וכן נחיל של דבורים: מאי וכן","הכי קאמר אפילו נחיל של דבורים דקנין דרבנן הוא סד\"א האי כיון דרבנן בעלמא הוא דקני ליה אפילו סתמא נמי מייאש קמ\"ל אם נתייאשו הבעלים אין אי לא לא:","א\"ר יוחנן בן ברוקה נאמנת אשה וקטן כו':","אשה וקטן בני עדות נינהו אמר רב יהודה אמר שמואל הכא במאי עסקינן כגון שהיו בעלים מרדפין אחריהם ואשה וקטן מסיחין לפי תומם ואומר מכאן יצא נחיל זה","אמר רב אשי אין מסיח לפי תומו כשר אלא לעדות אשה בלבד","א\"ל רבינא לרב אשי ולא והרי נחיל של דבורים מסיח לפי תומו הוא שאני נחיל של דבורים דקנין דרבנן הוא","ודאורייתא לא והאמר רב יהודה אמר שמואל מעשה באדם אחד שהיה מסיח לפי תומו ואומר זכורני כשאני תינוק ומורכבני על כתיפו של אבא והוציאוני מבית הספר והפשיטוני את כתנתי והטבילוני לאכול בתרומה לערב","ורבי חנינא מסיים בה הכי וחבירי בדילין ממני והיו קורין אותי יוחנן אוכל חלות והעלהו רבי לכהונה על פיו","בתרומה דרבנן","ואכתי דאורייתא לא והא כי אתא רב דימי אמר רב חנא קרטיגנא ואמרי לה רב אחא קרטיגנא משתעי מעשה בא לפני ריב\"ל ואמרי לה מעשה בא לפני רבי בתינוק אחד שהיה מסיח לפי תומו ואמר אני ואמי נשבינו לבין העכו\"ם יצאתי לשאוב מים דעתי על אמי ללקוט עצים דעתי על אמי","והשיאה רבי על פיו לכהונה","בשבויה הקילו:","אבל לא יקוץ את סוכו [וכו']: תניא ר' ישמעאל בנו של רבי יוחנן בן ברוקה אומר תנאי ב\"ד הוא שיהא יורד לתוך שדה של חבירו וקוצץ סוכו של חבירו להציל את נחילו ונוטל דמי סוכו מתוך נחילו של חבירו","ותנאי ב\"ד הוא שיהא שופך יינו ומציל את דובשנו של חבירו ונוטל דמי יינו מתוך דובשנו של חבירו ותנאי ב\"ד הוא שיהא מפרק את עציו וטוען פשתנו של חבירו ונוטל דמי עציו מתוך פשתנו של חבירו שע\"מ כן הנחיל יהושע לישראל את הארץ:","\u0001מתני׳\u0002 המכיר כליו וספריו ביד אחר ויצא לו שם גניבה בעיר ישבע לו לוקח כמה נתן ויטול ואם לאו לאו כל המנו שאני אומר מכרן לאחר ולקחן זה הימנו:","\u0001גמ׳\u0002 וכי יצא לו שם גניבה בעיר מאי הוי ליחוש דילמא זבנינהו והוא ניהו קא מפיק שמא","א\"ר יהודה אמר רב כגון שבאו בני אדם בתוך ביתו ועמד והפגין בלילה ואמר נגנבו כליי כ\"ש עילא מצא","רב כהנא מסיים בה משמיה דרב כגון שהיתה מחתרת חתורה בתוך ביתו ובני אדם שלנו בתוך ביתו יצאו ואנבורקראות של כלים על כתפיהם והכל אומרים נגנבו כליו של פלוני","ודלמא כלים הוו ספרים לא הוו א\"ר חייא בר אבא א\"ר יוחנן כגון דקאמרי נמי ספרים","וליחוש דלמא זוטרי וקא טעין רברבי א\"ר יוסי בר חנינא דקאמרי ספר פלוני ופלוני","ודלמא הוו עתיקי וקא טעין חדתי אמר רב כגון דאמרי הללו כליו של פלוני הללו ספריו של פלוני","ומי אמר רב הכי והאמר רב בא במחתרת ונטל כלים ויצא פטור מ\"ט בדמי קננהו","ה\"מ דקננהו בבא במחתרת דמעיקרא מסר נפשיה לקטלא אבל הני כיון דלא מסרו נפשייהו לקטלא לא","אמר רבא לא שנו אלא בעל הבית העשוי למכור כליו אבל בעל הבית שאינו עשוי למכור כליו"],[[0,"וקיימא לן","לקמן דהא גנב כגזלן דקאמר רבי כגזלן דר\"ש קאמר דקני ולא כגזלן דרבנן דלא קני:"],[12,"הא לאו מפני כבוד אביהם לא","אלמא גזלן לרבי קני כר\"ש וקאמר גנב כגזלן אלמא תרוייהו קני:"],[13,"מאי וכן","פשיטא דקני ביאוש דמ\"ש נחיל מכסות:"],[14,"קנין דרבנן הוא","דאין כאן גזל אלא מפני דרכי שלום דהא דהפקר נינהו ותניא (חולין דף קמא:) יוני שובך ויוני עלייה אין בהן משום גזל אלא מפני דרכי שלום:"],[16,"מרדפין אחריהם","קודם דיבור הקטן דרגלים לדבר דשלו הם:"],[17,"לעדות אשה","שמע מן התינוקות שהיו אומרים הרי אנו הולכין לספוד ולקבור איש פלוני בפ' בתרא דיבמות (דף קכא:):"],[19,"והטבילוני","לפי שדרכו של תינוק לטפח בשרצים ובטומאות:"],[20,"בדילין ממני","מפני תרומתי:"],[21,"בתרומה דרבנן","בזמן הזה דרבי לאחר חורבן היה ואיכא מ\"ד לא קידשה לעתיד לבא:"],[23,"והשיאה רבי לכהונה","ואע\"ג דאיסורא דאורייתא היא משום זונה:"],[24,"בשבויה הקילו","דספיקא בעלמא היא:"],[26,"שיהא שופך יינו","במתני' הוא זה בא בחביתו של יין וזה בא בכדו של דבש נסדקה חבית של דבש:"],[26,"וטוען פשתנו","אם מת חמור חבירו הטעון פשתן בדרך וחמורו של זה טעון עצים:"],[27,"מתני' שם גניבה","שיצא קול שנגנבו כליו:"],[27,"נשבע לוקח כמה נתן ויטול","ויחזיר לו כליו ולפני יאוש קמיירי:"],[29,"גמ' הפגין","צעק:"],[29,"עילא מצא","פירכא היא כלומר עילא מצא כשמכר כליו ונתחרט וידע שמכרן לוקח לאחר עמד והפגין וצעק בלילה להאמין דבריו כשיערער:"],[30,"אנברקראות","חבילות:"],[34,"בדמי קננהו","דהבא במחתרת בר מיתה הוא כדכתיב אם במחתרת ימצא הגנב וגו' וכיון דאי הוה בידיה פטור כי מכרן לאחר אמאי מהדר להו לוקח:"]],[[1,"","דתקנה בעלמא תקנו ליה. משום דרכי שלום כמו יוני שובך ותימה דאמאי לא קני להו מדאורייתא בהגבהת הכוורת:"],[27,"המכיר כליו וספריו ביד אחר כו'","לפני יאוש איירי כדפירש הקונטרס דאי לאחר יאוש דאיכא יאוש ושינוי רשות לא היה מתחייב להחזיר ונראה דבספרים הוי לעולם לפני יאוש שאין רגילות להתייאש מספרים ולא מיבעיא מגנבים עובדי כוכבים דלא מייאש אפי' מכלים כיון דדייני בגיותא כדאמר לעיל אלא אפי' בגנב ישראל אין רגילות להתייאש מספרים דסוף יבאו ליד ישראל דאין גנבים מוכרין אותן רק לישראל ולסוף חוזרין לבעלים ובכלים נמי מיירי לפני יאוש ואפילו לרבנן נמי דאמרי סתם גניבה יאוש בעלים הוא מיירי כגון שהבעלים רודפין אחריו וידוע שלא נתייאשו מהן מעולם מ\"מ נוטל מה שנתן מפני תקנת השוק כדאמר בגמרא וא\"ת בלא תקנה יטול מה שנתן דמצי אמר להציל נתכוונתי ולהשיב אבידה וי\"ל דמיירי שהיה יכול לתבוע מבני אדם שלנו בתוך ביתו אפילו לא היה זה קונה אותם ועי\"ל דלא שייך למימר הכי כלל שהרי הלוקח טוען שקנה מאדם אחר נאמן ולא מאותם שלנו בתוך ביתו כדקתני סיפא שאני אומר מכרן לאחר ולקחן זה ממנו והא דלא קאמר שאני אומר שהוא מכרן לו משום שאין הלוקח טוען שזה מכרן ומה שמקש' אמאי נאמן לומר לקוחין הן בידי והלא ספרים עשויין להשאיל ולהשכיר מפורש בסוף המקבל (ב\"מ דף קטז. ושם):"],[30,"דקאמרי הללו כליו של פלוני","כלומר כשיצא הקול אומרים אלו כליו וספריו של פלוני שבני אדם הללו נושאין והן מכירין שהם חדשים:"]]],[["לא צריך לאהדורי עליה כולי האי","ודלמא איצטריך ליה זוזי וזבין אמר רב אשי הרי יצא לו שם גניבה בעיר:","איתמר גנב ומכר ואח\"כ הוכר הגנב רב משמיה דרבי חייא אמר הדין עם הראשון ר' יוחנן משמיה דרבי ינאי אמר הדין עם השני","אמר רב יוסף לא פליגי כאן לפני יאוש הדין עם השני כאן לאחר יאוש הדין עם הראשון","ותרוייהו אית להו דרב חסדא","א\"ל אביי ולא פליגי הא מתנות כהונה כלפני יאוש דמי ופליגי דתנן אמר לו מכור לי מעיה של פרה והיו בהן מתנות נותנן לכהן ואינו מנכה לו מן הדמים לקח הימנו במשקל נותנו לכהן ומנכה לו מן הדמים","ואמר רב לא שנו אלא ששקל לעצמו אבל שקל לו הטבח הדין עם הטבח","אימא אף דין עם הטבח מהו דתימא אין מתנות כהונה נגזלות קמ\"ל","ולאביי דאמר פליגי במאי פליגי בדרב חסדא","רב זביד אמר כגון שנתייאשו הבעלים ביד לוקח ולא נתייאשו ביד גנב","ובהא פליגי מר סבר יאוש ואח\"כ שינוי רשות קני שינוי רשות ואח\"כ יאוש לא קני ומ\"ס לא שנא","רב פפא אמר בגלימא דכ\"ע לא פליגי דהדר למריה והכא בעשו בו תקנת השוק קמיפלגי","רב משמיה דר' חייא אמר הדין עם הראשון דינא דלוקח דלישקול זוזי מגנב ולא עשו בו תקנת השוק ור' יוחנן משום דר' ינאי אמר הדין עם השני דינא דלוקח דלישקול מבעל הבית ועשו בו תקנת השוק","וסבר רב לא עשו בו תקנת השוק והא רב הונא תלמידיה דרב הוה וחנן בישא גנב גלימא וזבנה אתא לקמיה דרב הונא א\"ל לההוא גברא זיל שרי עביטך","שאני חנן בישא כיון דליכא לאישתלומי מיניה כלא הוכר דמי","אמר רבא אם גנב מפורסם הוא לא עשו בו תקנת השוק והא חנן בישא דמפורסם הוה ועשו בו תקנת השוק נהי דמפורסם לבישותא לגניבותא לא מפורסם","איתמר גנב ופרע בחובו גנב ופרע בהיקיפו לא עשו בו תקנת השוק דאמרי לא אדעתא דהנהו יהיבת ליה מידי","משכנתא שוי מאתן במאה עשו בו תקנת השוק שוה בשוה אמימר אמר לא עשו בו תקנת השוק מר זוטרא אמר עשו בו תקנת השוק","(והלכתא עשו בו תקנת השוק)","זבינא שוה בשוה עשו בו תקנת השוק שוה מאה במאתן רב ששת אמר לא עשו בו תקנת השוק רבא אמר עשו בו תקנת השוק","והלכתא בכולהו עשו בו תקנת השוק לבר מגנב ופרע בחובו גנב ופרע בהיקיפו:","אבימי בר נאזי חמוה דרבינא הוה מסיק בההוא גברא ארבעה זוזי גנב גלימא אתיא ניהליה אוזפיה ארבעה זוזי אחריני לסוף הוכר הגנב אתא לקמיה דרבינא","אמר קמאי גנב ופרע בחובו ולא בעי למיתב ליה ולא מידי הנך ארבעה זוזי אחריני שקול זוזך והדר גלימי","מתקיף לה רב כהן ודלמא גלימא בהני זוזי קמאי יהבה ניהליה גנב ופרע בחובו גנב ופרע בהיקיפו וארבעה זוזי בתראי הימוני הימניה כי היכי דהימניה מעיקרא איגלגל מילתא מטא לקמיה דרבי אבהו אמר הלכתא כרב כהן","נרשאה גנב ספרא זבניה לפפונאה בתמנן זוזי אזל פפונאה זבניה לבר מחוזאה במאה ועשרין זוזי לסוף הוכר הגנב אמר אביי ליזיל מרי דספרא ויהב ליה לבר מחוזא תמנן זוזי ושקיל ספריה ואזיל בר מחוזאה ושקיל ארבעין מפפונאה","מתקיף לה רבא השתא לוקח מגנב עשו בו תקנת השוק לוקח מלוקח מיבעיא","אלא אמר רבא ליזיל מריה דספרא ויהיב ליה לבר מחוזאה מאה ועשרין זוזי ושקיל ספריה וליזיל מרי דספרא ולישקול ארבעין מפפונאה ותמנן מנרשאה:","\u0001מתני׳\u0002 זה בא בחביתו של יין וזה בא בכדו של דבש נסדקה חבית של דבש ושפך זה את יינו והציל את הדבש לתוכו"],[[0,"לא צריך לאהדורי כולי האי","דנימא ספר פלוני ופלוני:"],[2,"הדין עם הראשון","דינו של בע\"ה ותביעתו על הגנב היא ואין הלוקח בעל דינו ואם בא לגבותו הימנו יתן דמים ואע\"ג שהוכר הגנב לא אמרינן יחזיר לוקח הכלים בחנם ויפרע מן הגנב:"],[2,"הדין עם השני","דינו של בעל הבית עם הלוקח הוא ויוציא הימנו כליו בחנם:"],[3,"לפני יאוש","לקחו מן הגנב לפני יאוש:"],[4,"דרב חסדא","גזל ולא נתייאשו הבעלים ובא אחר ואכלו רצה מזה גובה כו' בריש פירקין והאי נמי אע\"ג דיהיב דמי לגנב לגבי האי מיהא גזלן הוא ומיהו היכא דלא הוכר הגנב עבוד ליה רבנן תקנת השוק ליטול מה שנתן אבל היכא דהוכר הגנב עליו להחזיר אחריו:"],[5,"כלפני יאוש דמי","דכהן לא מייאש מינייהו:"],[5,"ופליגי","כלומר ואמר רב הדין עם הראשון:"],[5,"מתנות","קיבה:"],[5,"נותן הלוקח","קיבה לכהן דמסתמא מתנות לא זבין ליה:"],[6,"לא שנו","לקח הימנו במשקל נותנן לכהן דמשמע דהלוקח ע\"כ נותנן לכהן והוא יתבע דמים מן המוכר:"],[6,"אלא ששקל","הוא לעצמו:"],[6,"הדין עם הטבח","דינו של כהן וערעורו על הטבח הוא רב לטעמיה דאמר הדין עם הראשון דטבח כגנב ראשון ולוקח הוי שני וקאמר הדין עם הטבח אלמא רב לית ליה דרב חסדא:"],[7,"אינן נגזלות","דאלימא קנייה דידהו דמכח גבוה קאתו ליה וכל היכא דאיתנהו אימא דכהן נינהו ואפילו שקל לו הטבח יגבה הכהן נמי מן הלוקח קמ\"ל:"],[8,"פליגי בלפני יאוש ובדרב חסדא","דרב לית ליה דרב חסדא:"],[9,"רב זביד אמר","היכא דלא אייאוש בעלים דכ\"ע אית להו דרב חסדא והדין עם השני והכא כגון שנתייאשו כו':"],[10,"לא שנא","דקני לגמרי ואפילו בדמי לא מהדר לו:"],[11,"רב פפא אמר","לעולם בדלפני יאוש פליגי ותרוייהו אית להו דרב חסדא ובגלימא דגניבה כ\"ע לא פליגי דהדרא למרה מיד בחנם ואין הלוקח יכול לעכבה על מעותיו וכדרב חסדא והדין עם הראשון דאמר רב לא בדין הבעל הבית קאמר אלא בדינו של לוקח קאמר:"],[11,"תקנת השוק","על שקנאו לוקח בשוק בפרהסיא ולא הבין בו שנגנב עשו לו תקנה שישלם לו בעל הבית מעותיו:"],[12,"ורבי יוחנן סבר עשו תקנה","ונהי דאית לן דרב חסדא ולא מצי לוקח למימר לבעל הבית לאו בעל דברים דידי את מיהו לאחר שישלם הגניבה יתבע מעותיו מבעל הבית ואי קשיא מ\"מ דמי שקיל מה לי משום תקנה מה לי משום טענת לאו בעל דברים דידי את נפקא מינה היכא דגזל ובא אחר ואכל בלא דמים דאמרינן כדרב חסדא ואם השני נוח לו מן הראשון גובה הימנו:"],[13,"שרי עביטך","התר משכונך כלומר פדה משכונך שבידו:"],[16,"חוב","מלוה:"],[16,"הקף","לחנוני:"],[16,"לאו אדעתא","דהאי גניבה יהבתה ליה זוזי דמקמי הכא אוזפת ליה:"],[17,"משכנתא שוה בשוה","אין דרך לעשות כן להלוות על המשכון כל שויו הלכך לאו אדעתא דהאי משכנתא אוזפיה אלא הימוני הימניה:"],[19,"רב ששת אמר לא עשו","ואפילו ליטול מאה דכי היכי דמאה יתירין מתנה היא מאה דשויה נמי מתנה הוו:"],[19,"ורבא אמר עשו תקנה","אפילו ליטול מאתים דאורחיה למזבין בדמים יקרים:"],[20,"בר מגנב ופרע בחובו ובהיקיפו","דלא יהיב זוזי אהאי חפץ:"],[23,"הלכתא כרב כהן","דכיון דהימניה מעיקרא השתא נמי הימניה:"],[24,"נרשאה ופפונאה ובני מחוזאה","על שם מקומן נקראו: מתני'"]],[[5,"אמר ליה אביי הרי מתנות כהונה כלפני יאוש דמי ופליגי","דמשמע ליה לאביי דהדין עם הטבח דוקא וה\"נ הדין עם הראשון מכאן קשה על פי' הקונטרס דפרק הזרוע (חולין דף קלד.) ואין להאריך בזה:"],[18,"והלכתא בכולהו עשו בו תקנת השוק","נ\"ל דלא קאי אלא אהני דפליגי בהו אמוראי אמימר ומר זוטרא [רבא ורב ששת] דאתו לפסוק כמ\"ד עשו בו תקנת השוק אבל אמילתא דרבא דגנב מפורסם דלא פליג עליה שום אמורא לא קאי:"]]],[["אין לו אלא שכרו ואם אמר אציל את שלך ואתה נותן לי דמי שלי חייב ליתן לו","שטף נחל חמורו וחמור חבירו שלו יפה מנה ושל חבירו מאתים והניח זה את שלו והציל את של חבירו אין לו אלא שכרו ואם אמר לו אני אציל את שלך ואתה נותן לי את שלי חייב ליתן לו:","\u0001גמ׳\u0002 ואמאי לימא ליה מהפקירא קא זכינא מי לא תניא הרי שהיה טעון כדי יין וכדי שמן וראה שהן משתברות לא יאמר הרי זה תרומה ומעשר על פירות שיש לי בתוך ביתי ואם אמר לא אמר כלום","כדא\"ר ירמיה כשעקל בית הבד כרוך עליה ה\"נ כשעקל בית הבד כרוך עליה","ואם אמר לא אמר כלום והתניא מי שבא בדרך ומעות בידו ואנס כנגדו לא יאמר הרי פירות שיש לי בתוך ביתי מחוללים על מעות הללו ואם אמר דבריו קיימין","הכא במאי עסקינן בשיכול להציל אי בשיכול להציל לכתחלה אמאי לא יאמר בשיכול להציל על ידי הדחק","וכל היכא דאיכא הפסידא לכתחלה לא יאמר והתניא הרי שהיו לו עשר חביות של טבל טמא וראה אחת מהן שנשברה או שנתגלתה אומר הרי היא תרומת מעשר על תשע חברותיה ובשמן לא יעשה כן מפני הפסד כהן","א\"ר ירמיה כשעקל בית הבד כרוך עליה בשלמא שנשברה חזיא אלא נתגלתה למאי חזיא","וכ\"ת חזיא לזילוף והתניא מים שנתגלו הרי זה לא ישפכם ברשות הרבים ולא יגבל בהן את הטיט ולא ירבץ בהן את הבית ולא ישקה מהם את בהמתו ולא בהמת חבירו","דעבר לה במסננת כר' נחמיה דתניא מסננת יש בה משום גילוי אמר רבי נחמיה אימתי בזמן שהתחתונה מגולה אבל בזמן שהתחתונה מכוסה אף על פי שהעליונה מגולה אין בה משום גילוי לפי שארס של נחש דומה לספוג וצף ועומד במקומו","לאו איתמר עלה א\"ר סימון אריב\"ל לא שנו אלא שלא טרקו אבל טרקו אסור","התם נמי אפשר דמנח מידי אפומא דחביתא דשפי ליה","ורבי נחמיה (מטמא אטמא) מי תרמינן","והתניא תורמין מן הטמא על הטמא ומן הטהור על הטהור ומן הטהור על הטמא אבל לא מן הטמא על הטהור ר' נחמיה אומר אף מן הטמא על הטמא לא התירו לתרום אלא בשל דמאי הכא נמי בשל דמאי","אמר מר ובשמן לא יעשה כן מפני הפסד כהן מאי שנא שמן דראוי להדליק יין נמי ראוי לזילוף וכי תימא זילוף לאו מילתא היא והאמר שמואל משום רבי חייא שותין מלוג בסלע ומזלפין מלוג בשתים","הכא במאי עסקינן בחדש והא ראוי לישנו אתי ביה לידי תקלה","שמן נמי אתי ביה לידי תקלה דמנח בכלי מאוס יין נמי מנח ליה בכלי מאוס השתא לזילוף קא בעי ליה בכלי מאוס קא מנח ליה","ותקלה עצמה תנאי היא דתניא חבית של יין של תרומה שנטמאת בית שמאי אומרים"],[[0,"אין לו אלא שכרו","שכר כלי ושכר פעולה:"],[2,"גמ' ולימא ליה מהפקירא זכינא","דבש שלך היה הולך כולו לאיבוד והריני כמציל מן ההפקר ואמאי אין לו אלא שכרו כוליה דבש לישקול וגבי חמור ליכא למימר הכי דיכול להצילה הוא:"],[2,"משתברות","והכל נשפך ביחד:"],[2,"לא אמר כלום","אלמא כיון דלאיבוד אזל לית בהו זכייה והפקירא הוא:"],[3,"כדאמר ר' ירמיה","לקמן:"],[3,"בעקל","דדובשא כרוך עליה חבית של דבש קשורה בעקל ולא ישפך הכל אלא מנטף מעט מעט וליכא הפקר:"],[4,"הרי פירות","של מעשר שני שיש לי בתוך ביתי מחוללין כו':"],[6,"וכל היכא דאיכא","קצת הפסד וליכא איבוד לגמרי כי הכא דמוקמת לה בשיכול להציל ע\"י הדחק ושמא יציל:"],[6,"לכתחלה לא יאמר","בתמיה:"],[6,"הרי שהיו לו","ללוי:"],[6,"עשר חביות של טבל","הטבול לתרומת מעשר והוא טמא דתרומת מעשר דידיה לא חזיא לכהן לשתיה אלא לזלף ולקמיה מוקי לה ביין חדש דלא חזי כולי האי לזלף דלא אלים ריחא ופסידא פורתא הוא דאיכא כמו זה שיכול להציל על ידי הדחק:"],[6,"ה\"ג","אומר הרי היא תרומת מעשר על תשע חברותיה:"],[6,"שמן דתרומה טמאה","חזי להדליק וכי מפסיד לה לכהן איכא פסידא טובא:"],[7,"כשעקל בית הבד כרוך עליה","דלא חשיב פסידא כולי האי כגון זה שאין יכול להציל אלא ע\"י הדחק:"],[7,"למאי חזיא","ואפ\"ה קתני אומר הרי הוא תרומה אלמא להפסד מועט לא חששו:"],[8,"לא ישפכם","שלא יעבור עליהם אדם יחף ויכנס ארס של נחש ברגלו ע\"י מכת צרור וימות:"],[8,"(ולא יגבל בהן את הטיט) ולא ישקה בהן לבהמתו","משום סכנת נפשות שמא ישחטנה אחרי כן:"],[9,"מסננת","כלי ע\"ג כלי ונותנין השמרים בתוך העליון והוא ככברה והיין מסתנן מאליו:"],[9,"יש בה משום גילוי","צריך לכסות העליון כדי שלא ישתה בו נחש ואף על פי שהיין מסתנן והולך חיישינן שמא יעבור הארס עם היין לתוך הכלי וכ\"ש כשהתחתון מגולה:"],[10,"שלא טרקו","בשלא עירבו אדם וכגון הך מסננת שאין איש נוגע בה:"],[10,"אבל טרקו אסור","והכא בהך חבית כי מערה ושדי ליה מחבית למסננת מטריק ומתבלבל הארס עם היין ויוצא דרך המסננת לכלי:"],[11,"דמנח מידי","בגד או שולי כברה על פי חבית ושפי ליה ומסננו בנחת שפי לשון שופך כמו השופה יין (לתמרי) [לחבירו] בבא מציעא (דף ס. ע\"ש) רודיי\"ר:"],[12,"ורבי נחמיה","ואי ההיא די' חביות רבי נחמיה היא:"],[12,"מי תרמינן","מן הטמא על הטמא:"],[13,"אלא בשל דמאי","הקילו משום דרוב עמי הארץ מעשרין הן וכבר נתעשר:"],[14,"שותין מלוג בסלע ומזלפין מלוג בשתים","לשתיה אם ימצא יין בזול לוג בסלע יקח אבל לזלף יקח אפי' ביוקר הלוג בשתים סלעים דהנאה יתירא היא:"],[17,"תקלה","לשתותן והרי היא טמאה:"]],[[2,"","הרי שהיה טעון כדי יין וכדי שמן לא יאמר הרי הן כו'. וא\"ת אפי' אין משתבר נמי לא יאמר דאסור לתרום אלא מן המוקף וי\"ל דנקט משתברות משום דבעי למיתני סיפא ואם אמר לא אמר כלום א\"נ בשבתות וימים טובים איירי שמותר לתרום שלא מן המוקף כדאמר בהאשה רבה (יבמות דף צג:):"],[6,"וכל היכא דאיכא פסידא לכתחלה לא","ל\"ג ליה כדפי' הקונט' דהא בברייתא דמייתי נמי אסור לכתחלה היכא דאיכא הפסד כהן דקתני ובשמן לא יעשה וא\"כ לעיל נמי דאיכא הפסד כהן שפיר אסור לכתחלה אלא אמאי דקאמר לעיל דאפי' דיעבד לא אמר כלום פריך:"],[7,"אלא נתגלתה למאי חזיא","אבל משמן לא פריך דקתני בשמן לא יעשה אבל התרומה חלה וכי נתגלתה למאי חזיא דאיכא למימר דחזיא להדלקה ומ\"מ איכא הפסד כהן כיון שאין יכול להדליק בו כי נתגלתה אלא בטורח כי צריך שלא יגע בשמן כלל ולא בכלי במקום שיש שמן:"],[8,"ולא ישקה מהן לבהמה","פי' בקונטרס שמא ישחטנה ואיכא סכנת נפשות. ואין נראה דאפי' לבהמה טמאה לא ישקה משום בל תשחית כדמשמע בפרק ב' דע\"ז (דף ל: ושם) דמוקי התם הא דתניא שמותר להשקות לבהמתו בשונרא שאין קשה לה ופריך א\"ה דחבירו נמי ומשני כחיש דידיה נמי כחש הדר בריא מדפריך דידיה נמי כחיש משמע דאסור משום בל תשחית ועוד מדלא מוקי לה בכל בהמה טמאה שאין לחוש שמא ישחטנה משמע דבשאר בהמות טמאות דקשה לה אסור משום בל תשחית ומיהו י\"ל דבשאר בהמות טמאות לא בעי לאוקומי משום דאטו בשופטני עסקינן שמשקין לבהמה דבר שמתה על ידן:"],[9,"אימתי בזמן שהתחתונה מגולה","וא\"ת א\"כ פשיטא דיש בהן משום גילוי דהוי כשאר מגולין וי\"ל דס\"ד שהנחש ירא לבא מפני הקול שהוא שומע שנופל היין ממסננת לתחתונה כדאמרינן בפ\"ב דע\"ז (דף ל:) טיף טיף אין בו משום גילוי קמ\"ל דכה\"ג שרואה היין שנשפך בבת אחת לכלי התחתון אין מתיירא להיות סבור שהוא קול בני אדם אלא סבור שכך מסננין את היין:"],[15,"אתי לידי תקלה","ומסיק אי חיישי' לתקלה תנאי היא והא דאמר בפ\"ק דשבת (דף יז: ושם) גבי י\"ח דבר גידולי תרומה כתרומה בו ביום גזרו ומפרש התם טעמא משום תרומה טמאה ביד כהן דילמא משהי לה ואתי לידי תקלה והתם ליכא מאן דפליג דכ\"ע אית להו י\"ח דבר אור\"י דשאני התם דפעמים שמשהה אותה ביותר ואין זורעה באותה שנה שאירע שום דבר שלא יזרע בעת הזרע וימתין עד שנה אחרת אבל הכא לעולם יכול הוא לעשות זילוף אחר שיתיישן מעט ועוד יש מתרץ דשאני התם דבההיא גזירה ליכא הפסד כהן דכי היכי דהויא תרומה מעיקרא ה\"נ הויא אחר שזורעה ולכך לכ\"ע חיישינן לתקלה אבל הכא דאיכא הפסד לגמרי שתשפך הכל איכא מאן דלא חייש לתקלה ולפי' זה קשה דקאמר בפרק כל שעה (פסחים דף לג: ושם) מדליקין בפת ובשמן של תרומה שנטמאה ואמר אביי עלה משמיה דרבי יצחק בר מרתא אמר רב הונא לא שנו אלא פת אבל חיטין לא שמא יבא בהן לידי תקלה ורבי יוחנן אמר אפי' חיטין ומוקמינן לה בשליקתא ומאיסתא מכלל דרב הונא אפילו בשליקתא ומאיסתא לא הוה שרי אלמא משום תקלה מפסדי ליה לכהן לגמרי וי\"ל דלא פליגי דרב הונא לא איירי בשליקתא ואיהו נמי שרי בענין זה והשתא ליכא פסידא כיון דיכול לשלקו ולמאסו ולהחזיק בהן:"]]],[["תשפך הכל וב\"ה אומרים תעשה זילוף אמר ר' ישמעאל ב\"ר יוסי אני אכריע בבית תעשה זילוף ובשדה תשפך הכל","איכא דאמרי בישן תעשה זילוף ובחדש תשפך הכל אמרו לו אין הכרעה שלישית מכרעת:","אם אמר לו אציל את שלך וכו': אמאי ונימא ליה משטה אני בך","מי לא תניא הרי שהיה בורח מבית האסורין והיתה מעבורת לפניו אמר לו טול דינר והעבירני אין לו אלא שכרו אלמא אמר ליה משטה אני בך הכא נמי לימא ליה משטה אני בך","הא לא דמי אלא לסיפא ואם אמר לו טול דינר זה בשכרך והעבירני נותן לו שכרו משלם","מאי שנא רישא ומאי שנא סיפא אמר רמי בר חמא בצייד השולה דגים מן הים וא\"ל אפסדתני כוורי בזוזא:","שטף נהר חמורו וחמור חבירו שלו יפה מנה וכו': וצריכא דאי אשמעינן קמייתא התם הוא דכי פירש יהיב ליה דמי כוליה משום דבידים קא פסיד אבל הכא דממילא נימא אין לו אלא שכרו","ואי אשמעינן סיפא הכא הוא דבסתמא אין לו אלא שכרו משום דממילא אבל התם דבידים אימא אפילו בסתמא יהיב ליה דמי כולה צריכא","בעא מיניה רב כהנא מרב ירד להציל ועלה שלו מאליו מהו א\"ל משמיא רחימו עליה","כי הא דרב ספרא הוה קא אזיל בשיירתא לוינהו ההוא ארי כל לילא קא שדר ליה חמרא דחד מינייהו וקא אכיל כי מטא זמניה דרב ספרא שדר ליה חמרא ולא אכליה קדים רב ספרא וזכה ביה","א\"ל רב אחא מדיפתי לרבינא למה ליה למיזכי ביה נהי דכי אפקריה אדעתא דאריה אפקריה אדעתא דכ\"ע לא אפקריה א\"ל רב ספרא לרווחא דמילתא הוא דעבד","בעא מיניה רב מרבי ירד להציל ולא הציל מהו אמר לו וזו שאילה אין לו אלא שכרו","איתיביה השוכר את הפועל"],[[0,"תשפך הכל","כולה ביחד:"],[0,"בשדה תשפך הכל","דאדממטי ליה לגו ביתא אתי ביה לידי תקלה:"],[1,"אין הכרעה שלישית מכרעת","טעם עצמך אתה אומר ולא כדברי אחד מהן ששניהם לא הזכירו בית ושדה והיכי דמי הכרעה כגון אי הוה תני ב\"ש בין נטמאת בבית בין בשדה תשפך הכל וב\"ה אומרים בין בבית ובין בשדה תעשה זילוף ר\"ש אומר נטמא בשדה תשפך הכל בבית תעשה זילוף דטעמא דתרוייהו קמכרע והוו להו לגבי בית תרי ולגבי שדה תרי והלכתא כתרי שאין עומדין דברי יחיד במקום שנים דאחרי רבים להטות כתיב (שמות כג) כי ההוא דקולי מטלניות דבמה מדליקין (שבת דף כט.) אבל הכא דאינהו לא גלו דעתייהו דליהוי שום מידי חילוק בין בית לשדה טעמא דנפשיה קאמר:"],[3,"מעבורת","ספינה רחבה שעוברים בה רוחב הנהר:"],[5,"דאפסדתן כוורי בזוזא","והיינו בשכרו דקתני טול דינר בשכר שאתה מפסיד כאן ותעבירני נותן לו אותו שכר משלם ומתני' נמי הרי הפסידו ניכר:"],[6,"דבידים קא פסיד","שופך את יינו בידים בשבילו:"],[8,"ירד להציל","ע\"מ שיתן לו דמי שלו:"],[8,"ועלה שלו מאיליו מהו","מי אמרינן מעיקרא דאפקריה כאבוד דמי ומחייב לו היאך לשלומי והדר זכה ביה מריה מהפקירא או דלמא כיון דסליק סליק:"],[8,"מן שמיא רחימו עליה","ויהיב ליה דמי כאילו מת:"],[9,"לוינהו","נתחבר עמהם ארי והיה משמר בהמותיהם מחיות וליסטים:"],[9,"קדים רב ספרא","קודם שיחזיק בהן אחר שהרי הפקר היה:"],[10,"לרווחא דמילתא","שלא יהא ערעור בדבר:"]],[[1,"הכרעה שלישית","נראה לר\"י עיקר כפ\"ה דדעת ג' הוא דתנאי קמאי לא גילו בדעתם שיש שום חילוק בין בית לשדה אבל ההוא דקולי מטלניות דבמה מדליקין (שבת דף כט. ושם ד\"ה בין) הויא הכרעה דרבי אליעזר קאמר בין מן המוכן בין שלא מן המוכן טמא רבי יהושע אומר בין מן המוכן כו' טהור ר\"ע אומר מן המוכן טמא שלא מן המוכן טהור ובכירה (שם דף לט:) בהדיא חשיב ליה הכרעה אי לאו משום דר\"ע תלמיד הוה ועוד דהדר ביה ר\"ע לגבי רבי יהושע וההיא דהתם לא ישתטף גופו בין בחמין בין בצונן חשיבא הכרעה דתנאי קמאי גילו בדעתם דשייך לפלוגי בין חמין לצונן אבל הך דשמעתין לא גילו בדעתם חשיב ליה הכרעה שלישית וכן בנזיר פ' כ\"ג (דף נג. ושם ד\"ה ב\"ד) גבי ר\"א אומר [זקינים] הראשונים [מקצתן היו] אומרים חצי קב עצמות כו' התם נמי קרי ליה הכרעה שלישית דתנאי קמאי לא גילו בדעתם דשייך לפלוגי בין תרומה לקדשים לנזיר ועושה פסח ובראשית הגז (חולין דף קלה.) גבי ראשית הגז אין נוהג אלא במרובה וכמה מרובה ב\"ש אומרים שתים ב\"ה אומרים חמש ורבי ישמעאל אומר ארבעה וקרי נמי התם (דף קלז.) לרבי ישמעאל הכרעה שלישית ואותה הכרעה אין חשובה אפילו כדהכא ודנזיר דבהני סבירא ליה למכריע פלגא כמר ופלגא כמר אבל התם לא ס\"ל לא כמר ולא כמר והא דפריך בכל הני והא הכרעה שלישית אין הכרעה ה\"מ למיפרך תלמיד הוא ואין הלכה כהכרעת תלמיד אבל עדיפא קפריך דלאו הכרעה היא כלל ואור\"י הא דתניא בכיצד מברכין (ברכות דף מג:) בש\"א מברך על השמן ואח\"כ על ההדס וב\"ה אומרים מברך על ההדס תחילה וקאמר רשב\"ג אני אכריע שמן זכינו לריחו ולסיכתו הדס לא זכינו אלא לריחו הלכך שמן עדיף וקאמר רבי יוחנן בגמרא הלכה כדברי המכריע לא שייכא ההיא הכרעה לשאר הכרעות שהבאתי דלא סבירא ליה פלגא כמר ופלגא כמר אלא דמפרש טעמא דחד מינייהו וס\"ל כוותיה לגמרי וכן בכל מקום שאם תנא אחד יסבור כתנא אחר לא יקרא בכך מכריע תדע מדאיצטריך ר' יוחנן עלה למימר הלכה כדברי המכריע אע\"ג דאיהו גופיה כבר אמר בכירה (שבת דף לט:) כל מקום שאתה מוצא שנים חלוקים ואחד מכריע הלכה כדברי המכריע ש\"מ דודאי לא שייכא לההיא הכרעה דשבת ודהכא ולא קרי ליה הכרעה אלא מפני שהכריע דברי ב\"ש על דברי ב\"ה. ור\"ת פי' הכרעה שלישית דור שלישית כלומר תלמיד אתה ואין זו הכרעה כדאמר ר\"ע תלמיד הוה וה\"נ הוה מ\"ל דור שני דהיינו נמי תלמיד אלא כך היה המעשה ובנזיר (דף נג.) דקרי ליה הגמרא לב\"ד של אחרים הכרעה שלישית לישנא דהך ברייתא דהכא נקט וא\"ת בפ\"ק דפסחים (דף יג.) גבי ר' מאיר אומר אוכלין כל חמש רבי יהודה אומר אוכלים כל כו' ר\"ג אומר חולין אוכלין כל ארבע ותרומה כל חמש וקאמר בגמרא ר\"ג לאו מכריע הוא דטעמא דנפשיה קאמר ולפי' הקו' ניחא אלא לפי' ר\"ת אמאי לא מכריע הוא והא לאו תלמיד הוה וי\"ל דלאו מכריע הוא דלא עלייהו קאי שלפניהם היה ופ\"ה נראה לר\"י עיקר וי\"מ הכא טעמא דתשפך משום דריחא מילתא היא ואסור לזלף משום דהוי כשתיה ולא משום חשש תקלה ואין נראה דא\"כ לא הוי רבי ישמעאל מכריע אלא טעמא דנפשיה קאמר דקמאי לא איפליגי במיחש לתקלה ואין להקשות לפי' זה לאביי דאית ליה (ע\"ז דף סו:) גבי בת תיהא ריחא מילתא היא לימא דאמר כר\"מ אמאי לא מייתי נמי התם אפלוגתא דאביי ורבא פלוגתא דב\"ש וב\"ה דהכא איכא למימר דאביי א\"ש כב\"ה ומודו בה דריחא מילתא היא ליחשב הנאה והתם לענין איסור הנאת יין נסך איירי ודוקא לענין תרומה טמאה הכא המותרת בהנאה ריחא לאו מילתא ליחשב כשתיה ואע\"ג דמייתי התם ההיא דתנור שהסיקו בכמון של תרומה וההיא דהרודה פת חמה והניחה ע\"פ חבית של יין של תרומה התם ודאי אי ריחא מילתא ואסור בהנאה יש לנו כמו כן לאסור הפת לאכול לזרים שנקלט מן הכמון או היין של תרומה אבל ריחא לחודיה כגון בת תיהא וזילוף לא הוי כשתיה ומותר בתרומה [וע' תוס' ע\"ז סו: ד\"ה אמר רבא]:"],[10,"אדעתא דאריה אפקריה כו'","לא דמי להא דאמר באלו מציאות (ב\"מ ד' כד.) המציל מן הארי ומן הדוב כו' הרי הוא שלו מפני שהבעלים מתייאשים מהן דהתם ודאי שהארי בא לטרוף כדמשמע המציל מן הארי מתייאש לגמרי אבל הכא הארי היה עמהם והיה מלוה אותם לשמור בהמותיהם מחיות וליסטים רק שהיו נותנים לו לאכול חמור בכל לילה ואפשר שפעמים היה שבע ולא אכיל הלכך אין מפקיר אלא אדעתא דאכיל ליה אריה והא לא אכיל ליה:"]]],[["להביא כרוב ודורמסקנין לחולה והלך ומצאו שמת או שהבריא נותן לו שכרו משלם","א\"ל מי דמי התם עביד שליח שליחותיה הכא לא עביד שליח שליחותיה:","ת\"ר שיירא שהיתה מהלכת במדבר ועמד עליה גייס לטורפה מחשבין לפי ממון ואין מחשבין לפי נפשות","ואם שכרו תייר ההולך לפניהם מחשבין אף לפי נפשות ולא ישנו ממנהג החמרין","רשאין החמרין להתנות שכל מי שיאבד לו חמורו יעמיד לו חמור אחר בכוסיא אין מעמידין שלא בכוסיא מעמידין לו ואם אמר תנו לי ואני אשמור אין שומעין לו","פשיטא לא צריכא דאית ליה חמרא אחרינא מהו דתימא הא קא מינטר ליה קמ\"ל שאני נטירותא דחד מנטירותא דבי תרי:","ת\"ר ספינה שהיתה מהלכת בים עמד עליה נחשול לטובעה והקילו ממשאה מחשבין לפי משאוי ואין מחשבין לפי ממון ולא ישנו ממנהג הספנים","ורשאין הספנים להתנות שכל מי שאבדה לו ספינה יעמיד לו ספינה אחרת אבדה לו בכוסיא אין מעמידין שלא בכוסיא מעמידין לו ואי פירש למקום שאין הספינות הולכין אין מעמידין","פשיטא לא צריכא דבניסן מרחקי חד אשלא ובתשרי מרחקי תרי אשלי וקא אזיל ביומי ניסן למקום תשרי מהו דתימא דוושיה נקיט ואזיל קמ\"ל","ת\"ר שיירא שהיתה מהלכת במדבר ועמד גייס וטרפה ועמד אחד מהן והציל הציל לאמצע ואם אמר אני אציל לעצמי הציל לעצמו","היכי דמי אי דיכול להציל אפילו סיפא נמי לאמצע ואי דלא יכול להציל אפילו רישא נמי לעצמו","אמר רמי בר חמא הכא בשותפין עסקינן וכגון זה שותף חולק שלא לדעת חבירו אמר פליג לא אמר לא פליג","רבא אמר הכא בפועלין עסקינן וכרב דאמר רב פועל יכול לחזור בו אפילו בחצי היום","וכמה דלא הדר ביה כברשותיה דבעל הבית דמי וכי הדר ביה טעמא אחרינא הוא דכתיב (ויקרא כה, נה) כי לי בני ישראל עבדים ולא עבדים לעבדים","רב אשי אמר כשיכול להציל ע\"י הדחק גלי דעתיה לעצמו לא גלי דעתיה לאמצע:","\u0001מתני׳\u0002 הגוזל שדה מחבירו ונטלוה מסיקין אם מכת מדינה היא אומר לו הרי שלך לפניך אם מחמת הגזלן חייב להעמיד לו שדה אחר:","\u0001גמ׳\u0002 אמר רב נחמן בר יצחק מאן דתני מסיקין לא משתבש ומאן דתני מציקין לא משתבש מאן דתני מציקין לא משתבש דכתיב (דברים כח, נג) במצור ובמצוק","ומאן דתני מסיקין לא משתבש דכתיב (דברים כח, מב) יירש הצלצל ומתרגמינן יחסניניה סקאה:","אם מחמת הגזלן חייב: היכי דמי אילימא דאנסוה לארעא דידיה ולא אנסוה כולי ארעתא הא מרישא שמעת מינה אם מכת מדינה היא כו' אי לא לא","לא צריכא דאחוי אחוויי לישנא אחרינא הב\"ע כגון דאנסוה עכו\"ם ואמרי ליה אחויי ארעתיה ואחוי ההוא בהדייהו","ההוא גברא דאחוי אכריא דחטי דבי ריש גלותא אתא לקמיה דרב נחמן חייביה רב נחמן לשלומי יתיב רב יוסף אחוריה דרב הונא בר חייא ויתיב רב הונא בר חייא קמיה דרב נחמן א\"ל רב הונא בר חייא לרב נחמן דינא או קנסא","א\"ל מתניתין היא דתנן אם מחמת הגזלן חייב להעמיד לו שדה ואוקימנא דאחוי אחוויי בתר דנפק א\"ל רב יוסף לרב הונא בר חייא מאי נפקא לך מיניה"],[[0,"דורמסקנין","פרושים לשון מורי. לשון אחר אדרופיי\"ש ועשב הוא הנאכל בשלקות קדירה:"],[2,"לטורפה","לבזזה ונתפשרו עמהן בממון:"],[3,"תייר","מראה להם הדרך:"],[3,"אף לפי נפשות","שטעות הדרך במדבר סכנת נפשות היא:"],[3,"ולא ישנו ממנהג החמרים","שאם נהגו לתייר לפי ממון או לפי נפשות עושין:"],[4,"בכוסיא","בפשיעה:"],[4,"אין שומעין לו","שמא לא יקח החמור והם לא התנו אלא כדי שיקח החמור ויהיה מוסר נפשו לשמור עמהן בלילות מן החיות וליסטים:"],[5,"קא מנטר ליה","ואפילו אם יאמר האחד אני יכול לשמור יפה אבל שנים איני יכול לשמור:"],[5,"קמ\"ל","דאמרי ליה לא כ\"ש דהשתא מסרת נפשך טפי:"],[6,"מחשבין לפי משוי","אם השליך זה מאה ליטרין זהב ישליך זה מאה ליטרין ברזל:"],[8,"בניסן","שגדל הנהר מהפשרת שלגים ומן הגשמים מרחקים חד אשלא מלא חבל משפת הנהר לתוך המים ובתשרי שהמים חסרים והספינה גוששת אצל שפת הנהר רגילים להתרחק לתוך עומק המים תרי אשלי:"],[8,"ואזל היאך בניסן למקום תשרי","באמצע המים ומתוך שהנהר גדול וחזק נטבעה:"],[9,"הציל לאמצע","כל אחד מכיר את שלו ונוטל:"],[10,"אי שיכולים","בעלים להציל לא אייאוש ואפי' אמר לעצמו גזלן הוא:"],[11,"הכא בשותף","ובין יכולים להציל ובין אין יכולין להציל:"],[11,"וכגון זה","במקום איבוד ממון:"],[11,"שותף חולק","ואפי' לא ירצה חבירו:"],[11,"אמר פליג","ומעכב חלקו את מה שהציל:"],[11,"לא אמר לא פליג","ושפיר עבד דמסר נפשי' אעיסקא דתרוייהו הואיל והוא שותף עמו אורחיה למטרח אכולה עיסקא:"],[12,"בפועל","שהיה שכיר לבעלי ספינה וכשאין יכולין להציל:"],[13,"הדר ביה","וזכי מהפקירא:"],[14,"רב אשי אומר","לעולם באיניש דעלמא וכגון דיכולין להציל ע\"י הדחק:"],[15,"מתני' ונטלוה מסיקין","אנסין גזלוה מן הגזלן:"],[15,"מכת מדינה היא","דאנסוה ארעתא דאחריני ודהאיך:"],[15,"ואם מחמת הגזלן","מפרש בגמרא:"],[17,"גמ' צלצל","ארבה גזלן הוא שאוכל תבואות כל אדם:"],[19,"דאחוי אחויי","שלא גזלה הוא עצמו אלא שמע מבית המלך שמבקשין לגזול שדות והראה להם טלו קרקע זו של פלוני:"]],[[0,"להביא כרוב ודורמסקנין לחולה","שכרוהו בשביל החולה יותר ממה שהיה ראוי לשוכרו דהכי משמע לשון נותן לו שכרו משלם וצ\"ל דמיירי כגון דליכא למימר משטה אני בך שהוא מפסיד במקום אחר כיוצא בזה:"],[4,"ורשאים החמרים להתנות ביניהם","פירוש רשאים להסיע ממון אם כבר עשו תנאי קודם כמו ורשאין בני העיר להסיע על קצתן דב\"ב (דף ח:):"],[17,"יחסנינה סקאה","פי' בקונ' ארבה כמו [ומעלה את] הסקאין דבתענית (דף ו.) שהוא מין ארבה ואין נראה לר\"ת דלשון ירושה ואחסנתא משמע דאבני אדם איירי ונטלוה מסיקין נמי איירי בבני אדם ונראה שהאויב קרי סקאה שעולין ומכסין את הארץ כדכתיב (שמות י׳:ה׳) . והנה כסה את עין הארץ ועל שם כך נקרא צלצל שמכסה כל הארץ כצל כמו הוי ארץ צלצל כנפים (ישעיהו י״ח:א׳) ר\"ת ונראה דירושה שייכא שפיר בעופות וחיות כמו וירשוה קאת וקפוד (שם לד):"],[18,"הא מרישא שמעי' מינה","תימה דבכמה מקומות איכא הכי שכופל דבריו וי\"ל דדייק מדה\"ל למיתני ואם לאו חייב מדקתני ואם מחמת הגזלן חייב להעמיד לו שדה אחר משמע דמילתא באפי' נפשה היא:"],[19,"לא צריכא דאחוי אחויי","וחייב משום דינא דגרמי כדמשמע לקמן בשמעתין דקאמר זיל לגביה ר' שמעון בן אליקים ור' אלעזר בן פדת דדאין דינא דגרמי וחייבוהו ממתניתין ואם מחמת הגזלן חייב להעמיד לו שדה אחר ותימה לרשב\"א דלעיל בהגוזל קמא (בבא קמא דף ק. ושם) לא משכחת דר\"מ דאין דינא דגרמי אלא ברייתא דמחיצת הכרם שנפרצה דלא שמעינן דאתא כר\"מ אלא מכח ההיא משנה דהמסכך ואמאי לא מייתי התם ממתני' דהכא דמחייבינן בדינא דגרמי ואומר ר\"י דלא ניחא ליה לאתויי ממתניתין דהכא דלא קתני בה בהדיא דאחוי אלא מיתורא דמתני' מוקי לה הכי:"]]],[["אי דינא אי קנסא א\"ל אי דינא גמרינן מיניה אי קנסא לא גמרינן מיניה","ומנא תימרא דמקנסא לא גמרינן דתניא בראשונה היו אומרים המטמא והמנסך חזרו לומר אף המדמע","חזרו אין לא חזרו לא מאי טעמא לאו משום דקנסא הוא וקנסא לא גמרינן מיניה","לא מעיקרא סברי להפסד מרובה חששו להפסד מועט לא חששו ולבסוף סברי להפסד מועט נמי חששו","איני והא תני אבוה דרבי אבין בראשונה היו אומרים המטמא והמדמע חזרו לומר אף המנסך חזרו אין לא חזרו לא","מאי טעמא לאו משום דלא גמרינן מקנסא","לא מעיקרא סברי כרבי אבין ולבסוף סברי כרבי ירמיה","מעיקרא סברי כרבי אבין דאמר רבי אבין זרק חץ מתחילת ארבע ולבסוף ארבע וקרע שיראין בהליכתו פטור שהרי עקירה צורך הנחה היא ומתחייב בנפשו","ולבסוף סברי כר' ירמיה דא\"ר ירמיה משעת הגבהה קנייה איחייב ליה ממון מתחייב בנפשו לא הוי עד שעת ניסוך","רב הונא בר יהודה איקלע לבי אביוני אתא לקמיה דרבא א\"ל כלום מעשה בא לידך א\"ל ישראל שאנסוהו עובדי כוכבים והראה ממון חבירו בא לידי וחייבתיו","א\"ל אהדר עובדא למריה דתני ישראל שאנסוהו עובדי כוכבים והראה ממון חבירו פטור ואם נטל ונתן ביד חייב","אמר רבה אם הראה מעצמו כנשא ונתן ביד דמי","ההוא גברא דאנסוהו עובדי כוכבים ואחוי אחמרא דרב מרי בריה דרב פנחס בריה דרב חסדא א\"ל דרי ואמטי בהדן דרא ואמטי בהדייהו אתא לקמיה דרב אשי פטריניה","א\"ל רבנן לרב אשי והתניא אם נשא ונתן ביד חייב א\"ל הני מילי היכא דלא אוקמיה עילויה מעיקרא אבל היכא דאוקמיה עילויה מעיקרא מיקלי קלייה","איתיביה רבי אבהו לרב אשי אמר לו אנס הושיט לי פקיע עמיר זה או אשכול ענבים זה והושיט לו חייב הכא במאי עסקינן כגון דקאי בתרי עברי נהרא","דיקא נמי דקתני הושיט ולא תני תן ש\"מ:","ההוא שותא דהוו מנצו עלה בי תרי האי אמר דידי הוא והאי אמר דידי הוא אזל חד מנייהו ומסרה לפרהגנא דמלכא אמר אביי יכול לומר אנא כי מסרי דידי מסרי א\"ל רבא וכל כמיניה אלא אמר רבא משמתינן ליה עד דמייתי ליה וקאי בדינא","ההוא גברא דהוה בעי אחוויי אתיבנא דחבריה אתא לקמיה דרב א\"ל לא תחוי ולא תחוי א\"ל מחוינא ומחוינא יתיב רב כהנא קמיה דרב שמטיה לקועיה מיניה","קרי רב עילויה (ישעיהו נא, כ) בניך עולפו שכבו בראש כל חוצות כתוא מכמר מה תוא זה כיון שנפל במכמר אין מרחמין עליו אף ממון של ישראל כיון שנפל ביד עובדי כוכבים אין מרחמין עליו","א\"ל רב כהנא עד האידנא הוו פרסאי דלא קפדי אשפיכות דמים והשתא איכא יוונאי דקפדו אשפיכות דמים ואמרי מרדין מרדין קום סק לארעא דישראל וקביל עלך דלא תקשי לרבי יוחנן שבע שנין","אזיל אשכחיה לריש לקיש דיתיב וקא מסיים מתיבתא דיומא לרבנן אמר להו ריש לקיש היכא אמרו ליה אמאי אמר להו האי קושיא והאי קושיא והאי פירוקא והאי פירוקא אמרו ליה לריש לקיש אזל ריש לקיש א\"ל לרבי יוחנן ארי עלה מבבל לעיין מר במתיבתא דלמחר","למחר אותבוה בדרא קמא קמיה דר' יוחנן אמר שמעתתא ולא אקשי שמעתתא ולא אקשי אנחתיה אחורי שבע דרי עד דאותביה בדרא בתרא א\"ל רבי יוחנן לר\"ש בן לקיש ארי שאמרת נעשה שועל","אמר יהא רעוא דהני שבע דרי להוו חילוף שבע שנין דאמר לי רב קם אכרעיה א\"ל נהדר מר ברישא אמר שמעתתא ואקשי אוקמיה בדרא קמא אמר שמעתתא ואקשי","ר' יוחנן הוה יתיב אשבע בסתרקי שלפי ליה חדא בסתרקא מתותיה אמר שמעתתא ואקשי ליה עד דשלפי ליה כולהו בסתרקי מתותיה עד דיתיב על ארעא רבי יוחנן גברא סבא הוה ומסרחי גביניה אמר להו דלו לי עיני ואחזייה דלו ליה במכחלתא דכספא","חזא דפרטיה שפוותיה סבר אחוך קמחייך ביה חלש דעתיה ונח נפשיה למחר אמר להו רבי יוחנן לרבנן חזיתו לבבלאה היכי עביד אמרו ליה דרכיה הכי על לגבי מערתא חזא דהוה"],[[0,"אי דינא","הוא שמסור ישלם:"],[0,"גמרינן","מהאי מעשה דרב נחמן לשאר גרמי דנזקין דעלמא:"],[0,"ואי קנסא","הוא דקנסיה רב נחמן משום דרגיל היה בכך לא גמרינן מיניה:"],[1,"המטמא","טהרותיו של חבירו או מנסך יינו של חבירו לע\"ז דאע\"ג דקמיה מנח ואין הזיקו ניכר משלם:"],[2,"לא חזרו","לא היינו גמרי' מדמע ממנסך:"],[3,"להפסד מרובה","מטמא תרומה הפסד מרובה הוא דתו לא חזיא לאכילה מדמע הפסד מועט הוא דהא מזדבן לכהנים בדמי תרומה:"],[4,"המדמע","ערב חולין בתרומה דהפחית דמי החולין דלא חזו מהשתא אלא להמכר לכהנים:"],[4,"אף המנסך [כו']","לא חזרו לא גמרינן מנסך אע\"ג דהפסידו מרובה ממדמע ומטמא דהפסידן מועט לגבי מנסך:"],[7,"זרק חץ","בשבת:"],[7,"עקירה צורך הנחה","דכיון דבין עקירה להנחה קרע נמצא מעשה שבת ומעשה עקירה באין כאחד ולא אמרינן משעת עקירה חייב ממון ומתחייב בנפשו לא הוי עד שעת הנחת חץ והכא נמי הגבהת יין צורך ניסוך הוא ותשלומין וחיוב מיתה דע\"ז באין כאחד:"],[9,"לבי אביוני","מקום:"],[10,"נשא ונתן ביד חייב","דהציל עצמו בממון חברו:"],[11,"מעצמו","בלא אונס:"],[12,"דרי ואמטי","שאי והולך עמנו לבית המלך:"],[13,"ה\"מ","דאם נשא ונתן ביד חייב:"],[13,"היכא דלא אוקמינהו","העובדי כוכבים על הממון מעיקרא ע\"י האונס אלא הלך ונטל ונתנו להם אבל הכא דאוקמינהו על היין קלייה ואההיא שעתא פטור כי אמטי תו דידהו אמטי:"],[14,"פקיע","קשר:"],[14,"חייב","ואע\"ג דקאי עכו\"ם ע\"ג הממון הואיל ונשא ונתן ביד חייב:"],[14,"בתרי עיברי נהרא","עכו\"ם מצד זה והעמיר מצד זה דאי לא יהביה נהליה לא מצי אנס למשקליה:"],[16,"שותא","מכמורת לדגים או לחיות:"],[17,"לקועיה","לצואריה שבר מפרקתו:"],[18,"תוא","חיה והוא שור הבר כדמתרגם (דברים יד) תוא וזמר תורבלא תור שור בלא יער:"],[18,"אין מרחמין עליו","ושפיר עבדת דקטלתיה:"],[20,"מסיים מתיבתא דיומא לרבנן","היה מחזר ושונה להם מה שדרש רבי יוחנן אותו היום לפי שר\"ל חכם גדול היה ולאחר ששמעו כולן מפי הרב חוזר ומכוונה בידם:"],[21,"בדרא קמא","שבע שורות תלמידים יושבים לפניו זו לפנים מזו:"],[23,"ביסתרקי","תפי\"ד בלעז:"],[23,"מסרחי גביניה","גבות עיניו גדולים ומכסין עיניו:"],[24,"פריטא שפתיה","נקרעה שפתו על ידי מכה:"]],[[2,"לאו משום דקנס הוא","והא דמעיקרא לא גזרו על זה כמו על זה למאי דלא מסיק אדעתיה השתא טעמא דהפסד מועט איכא למימר דמעשה אירע במטמא ובמנסך לכך גזרו עליהם בשעת מעשה:"],[18,"כיון שנפל בידי עובדי כוכבים אין מרחמים עליו","כלומר שפיר מיקרי מסור שדבר ברור הוא שיקחו מאחר שהראהו:"],[19,"","השתא יווני נינהו כו'. קשה לר\"י דבפ\"ב דגיטין (דף טז: ושם יז. ד\"ה הא) אמר רבה בר בר חנה חלש על לגביה כו' אמר רחמנא או בטולך. וכו' ופריך למימרא דרומאי מעלי מפרסאי אלמא משמע שאז עדיין היו פרסיים בבבל ולכאורה משמע שאותו מעשה היה אחר מעשה שבכאן ואור\"י שהשרים והפקידים היו משתנים והיו פעמים מפרסיים ופעמים מיוונים:"]]],[["הדרא ליה עכנא א\"ל עכנא עכנא פתח פומיך ויכנס הרב אצל תלמיד ולא פתח יכנס חבר אצל חבר ולא פתח יכנס תלמיד אצל הרב פתח ליה בעא רחמי ואוקמיה","א\"ל אי הוה ידענא דדרכיה דמר הכי לא חלשא דעתי השתא ליתי מר בהדן א\"ל אי מצית למיבעי רחמי דתו לא שכיבנא אזילנא ואי לא לא אזילנא הואיל וחליף שעתא חליף","תייריה אוקמיה שייליה כל ספיקא דהוה ליה ופשטינהו ניהליה היינו דאמר ר' יוחנן דילכון אמרי דילהון היא:","ההוא דאחוי אמטכסא דר' אבא יתיב ר' אבהו ור' חנינא בר פפי ור' יצחק נפחא ויתיב ר' אילעא גבייהו","סבור לחיוביה מהא דתנן דן את הדין זיכה את החייב וחייב את הזכאי טימא את הטהור וטיהר את הטמא מה שעשה עשוי וישלם מביתו","א\"ל ר' אילעא הכי אמר רב והוא שנשא ונתן ביד אמרי ליה זיל לגבי דר\"ש בן אליקים ורבי אלעזר בן פדת דדייני דינא דגרמי","אזל לגבייהו חייבי' ממתני' אם מחמת הגזלן חייב להעמיד לו שדה אחר ואוקימנא דאחוי אחוויי:","ההוא גברא דהוה מפקיד ליה כסא דכספא סליקו גנבי עילויה שקלה יהבה להו אתא לקמיה דרבה פטריה א\"ל אביי האי מציל עצמו בממון חבירו הוא אלא אמר רב אשי חזינן אי איניש אמיד הוא אדעתא דידיה אתו ואי לא אדעתא דכספא אתו:","ההוא גברא דהוה מפקיד גביה ארנקא דפדיון שבויים סליקו גנבי עילויה שקלה יהבה ניהלייהו אתא לקמיה דרבא פטריה א\"ל אביי והא מציל עצמו בממון חבירו הוא א\"ל אין לך פדיון שבויים גדול מזה:","ההוא גברא דאקדים ואסיק חמרא למברא קמי דסליקו אינשי במברא בעי לאטבועי אתא ההוא גברא מלח ליה לחמרא דההוא גברא ושדייה לנהרא וטבע אתא לקמיה דרבה פטריה אמר ליה אביי והא מציל עצמו בממון חבירו הוא א\"ל האי מעיקרא רודף הוה","רבה לטעמיה דאמר רבה רודף שהיה רודף אחר חבירו להורגו ושיבר את הכלים בין של נרדף בין של כל אדם פטור שהרי מתחייב בנפשו","ונרדף ששיבר את הכלים של רודף פטור שלא יהא ממונו חביב עליו מגופו אבל של כל אדם חייב דאסור להציל עצמו בממון חבירו","ורודף שהיה רודף אחר רודף להציל ושבר כלים בין של נרדף בין של כל אדם פטור ולא מן הדין אלא שאם אי אתה אומר כן אין לך אדם שמציל את חבירו מן הרודף:","\u0001מתני׳\u0002 שטפה נהר אומר לו הרי שלך לפניך:","\u0001גמ׳\u0002 ת\"ר הגוזל שדה מחבירו ושטפה נהר חייב להעמיד לו שדה אחר דברי ר' אלעזר וחכ\"א אומר לו הרי שלך לפניך","במאי קא מיפלגי ר\"א דרש ריבויי ומיעוטי (ויקרא ה, כא) וכחש בעמיתו ריבוי בפקדון מיעט (ויקרא ה, כד) כל אשר ישבע עליו לשקר חזר וריבה","ריבה ומיעט וריבה ריבה הכל ומאי רבי רבי כל מילי","ומאי מיעט מיעט שטרות","ורבנן דרשי כללי ופרטי וכחש כלל בפקדון פרט או מכל חזר וכלל כלל ופרט וכלל אי אתה דן אלא כעין הפרט","מה הפרט דבר המיטלטל וגופו ממון אף כל דבר המיטלטל וגופו ממון יצאו קרקעות שאין מטלטלין יצאו עבדים שהוקשו לקרקעות יצאו שטרות שאע\"פ שמטלטלין אין גופן ממון","והדתניא הגוזל את הפרה ושטפה נהר חייב להעמיד לו פרה דברי ר' אלעזר וחכמים אומרים אומר לו הרי שלך לפניך התם במאי קמיפלגי","אמר רב פפא התם במאי עסקינן כגון שגזל שדה מחבירו והיתה"],[[0,"הדרא ליה עכנא","נחש גדול עשה עצמו כגלגל ומקיף את פי המערה ונותן זנבו לתוך פיו ואין אדם יכול ליכנס:"],[0,"פתח פיך","הרחיבי פתחיך להסיר זנביך מפיך ועשה פתח ליכנס:"],[1,"אי מצית למבעי רחמי דתו לא שכיבנא","אי אקשינא לך אזלינא בהדך ואעמוד אצלך בבית המדרש:"],[1,"ואי לא הואיל וחליף שעתא","ואתרחיש ניסא חליף ולא אלך עוד עמך שמא תכעוס עלי ואמות עוד פעם אחרת אלא אלך לביתי חי ולא אעמוד עוד אצלך פן אמות פעם אחרת ואית דמפרש הואיל וחליף שעתא וקבלתי צער מיתה לא אקבל עוד פעם אחרת לילך מכאן ובפסחים (דף מט.) מוכח שהלך לביתו דאמר רב כהנא אי לאו דנסיבנא כהנתא לאו אנא גלאי אמרי ליה והא למקום תורה גלית א\"ל לאו אנא גלאי כדגלו שאר אינשי שהרי לא בעבור מקום תורה גליתי אלא מאימת מלכות ברחתי אלמא בתר הכי חי הוה ועוד אמרי' בברכות ירושלמי דפגע ביה ההוא גברא אמר ליה מאי עביד בשמיא כלומר שליעג עליו שהיה מת וחיה א\"ל גזר דיניה דההוא גברא מחתם ומת ההוא גברא פגע ביה אחרינא אמר ליה הכי נמי ומית אתי לקמיה דר' יוחנן אמר ליה בר איניש דאמיה מבסרא ליה ואנתתיה דאבוה מיקרא כו':"],[2,"תייריה","הקיצו משנתו:"],[2,"א\"ל דילכון אמרי","שלכם הייתי אומר תורה של בני א\"י היא:"],[2,"דילהון היא","של בני בבל:"],[3,"מטכסא","תכשיט משי:"],[4,"וישלם מביתו","דאדבורא בעלמא חייב:"],[5,"שנשא ונתן ביד","ובכולם מפרש שנשא ונתן ביד באחד דיני ממונות בסנהדרין:"],[7,"אמיד","עשיר:"],[9,"אסיק חמריה למברא","מכניס חמורו לספינה מעבר הנהר והיו בה אנשים:"],[9,"בעא","חמרא לטבועי מעברא:"],[9,"מלח ליה","דחפו לחמור והשליכו למים לשון אחר מלח ליה כמו המלחים (יונה א) התחיל המלח להציל הספינה ודחפו והשליכו:"],[9,"[האי]","בעל החמור רודף הוא להרוג נפשות:"],[10,"ושיבר את הכלים","בין של נרדף בין של כל אדם פטור מלשלם שהרי מתחייב בנפשו הוא ברדיפה זו ואפילו אין הורגו דתנן בפרק בן סורר ומורה ואלו ניתנו להציל בנפשו הרודף אחר חבירו להרגו ונמצא תשלומין וחיוב מיתה באין כאחד:"],[11,"מגופו","שהרי נרדף זה רשאי להרוג את רודפו שנאמר (שמות כ״ב:א׳) אם במחתרת ימצא הגנב התורה אמרה אם בא להרגך השכם להרגו:"],[12,"ולא מן הדין","שהרי המציל עצמו בממון חבירו חייב כ\"ש מציל אחרים בממון חבירו:"],[13,"שטפה נהר","שהיתה על שפת הנהר והגביה שפתו והמים שוחקים וכורין תחת השפה ומתפשט בתוך השדה:"],[16,"רבי כל מילי","ואפילו קרקעות לשבועה ולהשבון:"],[17,"מיעט שטרות","שאין גופן ממון דיהיב ליה ניירא בעלמא:"]],[[2,"דילכון אמרי דילהון היא","פי' הקונטרס התורה היא של בני בבל וקשה בפרק לולב וערבה (סוכה דף מד. ושם ד\"ה והא) גבי הא דקאמר ערבה יסוד נביאים היא ושכחום וחזרו ויסדום ופריך מי א\"ר יוחנן הכי והא\"ר יוחנן דילכון אמרי דילהון הוא ופירש בקונטרס אלמא לא שכחוה בגולה ומאי פירכא היא וכי מפני שהיו בעלי תורה אין יכול להיות ששכחו תורת ערבה ועוד בכמה דוכתין אמר שכחום וחזרו ויסדום ולא פריך עלה הכי ואור\"ת כפר\"ח שלתלמידיו מבבל שהיו בפניו היה מדבר וה\"ק דילכון אמרי רב כהנא שהיה שלכם אמר שערבה דילהון הוא כלומר מנהג של נביאים ופריך אמאי דקאמר התם לעיל תסתיים דרבי יוחנן דאמר יסוד נביאים היא והאמר ר' יוחנן דילכון אמרי דילהון הוא ולשון דילהון משמע ליה מנהג נביאים ולא יסוד נביאים וכן צ\"ל בהמגרש (גיטין פד: ושם ד\"ה ר\"י) גבי ההיא דא\"ר יוחנן דילכון אמר הואיל וקנאתו להתגרש בו שלתלמידיו מבבל היה אומר כן על רב כהנא ובקונט' פי' שם דלחזקיה רבו שהיה חולק שם עליו היה אומר כן ואין נראה [לומר] שבשעה שלמד רב כהנא לפני ר' יוחנן היה רבי יוחנן ראש ישיבה בעוד שרבו חזקיה היה בחיים: [ועיין תוספות מנחות כג: ד\"ה כי]:"],[7,"ואי לאו אדעתא דכספא אתו","ואע\"ג דאמר לעיל נשא ונתן ביד חייב אור\"י דשאני שומר שלדעת כן הפקידוהו שיציל עצמו בו אם יבואו עליו אדעתא דכסא דכספא:"],[8,"אין לך פדיון שבויים גדול מזה","אע\"ג דמשמע דהוי אמיד מדלא מפליג כדמפליג לעיל מ\"מ הואיל ולא היה לו באותה שעה מה ליתן להם חשיב פדיון שבויים:"]]],[["פרה רבוצה בו ושטפה נהר דר' אלעזר לטעמיה ורבנן לטעמייהו:","\u0001מתני׳\u0002 הגוזל את חבירו או שהלוה הימנו או שהפקיד לו בישוב לא יחזיר לו במדבר על מנת לצאת במדבר יחזיר לו במדבר:","\u0001גמ׳\u0002 ורמינהו מלוה משתלמת בכל מקום אבידה ופקדון אין משתלמין אלא במקומן אמר אביי ה\"ק מלוה ניתנה ליתבע בכל מקום אבידה ופקדון לא ניתנו ליתבע אלא במקומן:","על מנת לצאת במדבר: פשיטא לא צריכא דא\"ל ליהוי האי פקדון גבך דאנא למדבר נפיקנא וא\"ל איהו אנא למדבר נמי בעינא למיפק אי בעינא לאהדרינהו לך התם מהדרנא לך:","\u0001מתני׳\u0002 האומר לחבירו גזלתיך הלויתני הפקדת אצלי ואיני יודע אם החזרתי לך אם לא החזרתי לך חייב לשלם אבל אם אמר לו איני יודע אם גזלתיך אם הלויתני אם הפקדת אצלי פטור מלשלם:","\u0001גמ׳\u0002 איתמר מנה לי בידך והלה אומר איני יודע רב הונא ורב יהודה אמרי חייב ור\"נ ור' יוחנן אמרי פטור","רב הונא ורב יהודה אמרי חייב ברי ושמא ברי עדיף ר\"נ ור' יוחנן אמרי פטור אוקי ממונא בחזקת מריה","תנן אבל אם אמר לו איני יודע אם הלויתני פטור ה\"ד אילימא דלא קא תבע ליה רישא נמי דלא קא תבע ליה אמאי חייב אלא דקתבע ליה וקתני סיפא פטור מלשלם","לא לעולם דלא קא תבע ליה ורישא בבא לצאת ידי שמים","איתמר נמי א\"ר חייא בר אבא א\"ר יוחנן האומר לחבירו מנה לי בידך והלה אומר איני יודע חייב בבא לצאת ידי שמים:","\u0001מתני׳\u0002 הגונב טלה מן העדר והחזירו ומת או נגנב חייב באחריותו לא ידעו בעלים לא בגניבתו ולא בחזירתו ומנו את הצאן ושלימה היא פטור:","\u0001גמ׳\u0002 אמר רב לדעת צריך דעת שלא לדעת מנין פוטר וכי קתני ומנו את הצאן והיא שלימה אסיפא","ושמואל אמר בין לדעת בין שלא לדעת מנין פוטר וכי קתני ומנו והיא שלימה פטור אכולה","ורבי יוחנן אומר לדעת מנין פוטר שלא לדעת אפי' מנין נמי לא צריך וכי קתני ומנו את הצאן והיא שלימה ארישא","רב חסדא אמר לדעת מנין פוטר שלא לדעת צריך דעת וכי קתני ומנו את הצאן והיא שלימה ארישא","אמר רבא"],[[0,"פרה רבוצה כו'","וגזלן לא משכה והוי כקרקעות ולר\"א דאמר שדה נגזלת קונה פרה עמה וחייב לשלם דמטלטלין נקנין אגב קרקע ולרבנן לא קנה שדה ולא פרה שבה:"],[1,"מתני' לא יחזיר לו במדבר","אם אין זה תובעו אין זה יכול לכופו לקבל חובו או פקדונו במדבר דלאו מקום שימור הוא:"],[1,"על מנת לצאת למדבר","קס\"ד שאמר לו לוה זה על מנת שנצא למדבר ושם אפרע לך להכי פריך פשיטא והא מתנה בהדיא לקבלו במדבר:"],[2,"גמ' ניתנה ליתבע","אם ירצה מלוה דידו על העליונה:"],[3,"אי בעית לאהדוריה ניהלך התם מהדרנא לך","ואשמועינן תנא דאע\"ג דלא תנאי גמור הוא דהא אי בעית קאמר אפ\"ה כיון דידע דאיהו נמי למדבר נפיק על כרחו יקבלם:"],[6,"רב הונא ורב יהודה אמרי חייב","לשלם:"],[6,"פטור","ומיהו ישבע כדאמר שאין יודע שחייב לו כלום דלא עדיף שמא מברי דהא א\"נ הוה טעין ליה אין לך בידי כלום הוי משביעין ליה שבועת היסת:"],[7,"דקא תבע ליה","וא\"ל גזלתני דהוי טענת ברי:"],[8,"לצאת ידי שמים","וכיון דקא מודי דודאי גזליה לא נפיק ידי שמים עד דעביד השבה אבל סיפא הואיל ולא גזלן ידע ולא נגזל ידע ליכא שום טענת ברי לא צריך למיפק ידי שמים:"],[9,"אתמר נמי","דהיכא דבא לצאת ידי שמים אפילו מאן דפטר ליה מדיני אדם מודה דחייב היכא דאיכא קצת טענת ברי הלכך רב הונא דאוקמה רישא בדלא תבע הואיל ואיכא קצת ברי דהא גזלן ידע דגזליה מעיקרא חייב בבא לצאת ידי שמים:"],[10,"מתני' חייב באחריותו","דמכי גנבה קם ליה ברשותיה והשבה דעבד לאו השבה היא עד שמודע להו לבעלים:"],[10,"ומנו את הצאן","אחר שהחזירו והיא שלימה הרי יש כאן דעת בעלים:"],[11,"אסיפא","לא ידעו הבעלים בגניבתו ובחזרתו ומנו את הצאן והיא שלימה פטור אבל ידעו לא מהני מנין:"],[12,"ושמואל אמר בין לדעת בין שלא לדעת מנין פוטר וכי קתני מנו את הצאן אכולה","בין ידעו בין שלא ידעו והכי משמע מתני' הגונב טלה ורישא בשהכירו בה הבעלים וידעו שנגנבה מהן קאי מדקתני סיפא לא ידעו מכלל דרישא בידעו והחזירה ומת חייב באחריותו וכן לא ידעו בגניבתו ובחזירתו נמי חייב אבל מנו את הצאן והיא שלימה פטור בין רישא דידעו בין סיפא דלא ידעו:"],[13,"ור' יוחנן אומר לדעת מנין פוטר שלא לדעת אפילו מנין לא צריך ומנו את הצאן ארישא","והכי קתני הגונב טלה דהיינו ידעו אחרי כן והחזירו חייב באחריותן היכא דלא מנו אבל לא ידעו הבעלים בגניבתו ובחזרתו אפי' אין מנין או שמנו אפילו הואי ידיעה פטור:"],[14,"ורב חסדא אמר לדעת מנין פוטר שלא לדעת צריך להודיעו","אם לא הודיעו אע\"ג דמנו חייב ומנו את הצאן ארישא והכי משמע מתני' חייב באחריות בין מנו בין לא מנו אימתי בזמן שלא ידעו בעלים בחזרתו ובגניבתו ואם מנו הנך דרישא את הצאן לאחר חזרה פטור:"],[14,"גמ' לדעת צריך דעת","אם הכירו הבעלים שנגנב מהן טלה צריך שיודיעם כשיחזירנה ואי לא הודע להו אע\"ג דמנו את הצאן והיא שלימה עדיין חייב באחריותה דכיון דידע הויא ליה גזילה גמורה ובעינן השבה מעליותא:"]],[[5,"","והלה אומר איני יודע. פי' אם הפקיד אצלי אבל איני יודע אם החזרתי לך חייב לכ\"ע כמו רישא דמתני' ולסיפא דמתני' הוא דמדמה לה בסמוך:"],[5,"רב נחמן ורבי יוחנן אמרי פטור","וקי\"ל כרב נחמן בדיני ופירש בקונטרס דמשביעין אותו שבועת היסת שאין יודע דלא עדיף מאילו היה כופר לגמרי ונראה דסובר בקונטרס כלישנא קמא דרב נחמן דפרק שבועת הדיינין (שבועות מ: ושם מא. ד\"ה מאן) דארישא דקתני התם מנה לי בידך אין. לך בידי כלום פטור קאמר רב נחמן ומשביעין אותו . שבועת היסת אבל איכא דמתני לה אסיפא אמנה לי בידך וא\"ל הן למחר א\"ל תנהו לי נתתיו לך פטור דדוקא בסיפא דאיכא דררא דממונא קאמר ר\"נ דמשביעין אותו שבועת היסת אבל ארישא לא וכן נראה הלכה כלשון הראשון דלישנא קמא סתמא דגמרא קאמר אבל לישנא בתרא רב חביבא הוא דמתני לה ובפ\"ק דב\"מ (דף ה. ושם ד\"ה אין) גבי ההוא רעיא מייתי נמי לישנא קמא דר\"נ אבל ר\"ת אומר דמספק אין לחייבו שבועה היכא דליכא דררא דממונא כיון שיש ב' לשונות ובפ\"ק דב\"מ (שם) לאו דוקא נקט לישנא קמא דהא התם איכא דררא דממונא דאתו סהדי דאכיל תרי מינייהו ושמע ר\"י שר\"ת היה מניח לדיינין לחייב היכא דליכא דררא דממונא רק שהוא לא היה רוצה לדון כן היכא דמודה שחייב לו אלא שטוען לו פרעתי ראה ר\"י ר\"ת לחייב שבועה אע\"ג דליכא עדים בההיא הודאה והיה יכול לכפור בשעה שטען שפרעתי ואמר דחשיב שפיר דררא דממונא כמו ההיא דנתתיו לך אע\"ג דבהך הודאה יש עדים ולפי פשט הלכה משמע דלמאן דמתני אסיפא חשיב לה דררא דממונא משום דאיכא עדים בהודאה שא\"ל אתמול הן ואין יכול עתה לכפור ורב האי גאון פי' כמו כן דלא משביעין ליה היכא דליכא דררא דממונא ומיהו משמתינן ליה על תנאי שיהא בשמתא אם הוא חייב ואינו מודה לו:"],[13,"שלא לדעת מנין נמי לא צריך","והא דאמר ר' אלעזר לעיל בהכונס (בבא קמא ד' נז.) הכל צריכין דעת בעלים חוץ מהשבת אבידה אין צ\"ל דפליג . אהא אלא יש לפרש הכל צריכין דעת בעלים היכא דהוי לדעת חוץ מהשבת אבידה שאין צריך אפי' הוי לדעת שידוע שאבדה לו אותה אבידה:"]]],[["מ\"ט דרב חסדא הואיל ואנקטה נגרי ברייתא","ומי אמר רבא הכי והאמר רבא האי מאן דחזייה לחבריה דאגבה אימרא מעדרא דידיה ורמא ביה קלא ושדייה ולא ידע אי הדריה אי לא הדריה ומת או נגנב חייב באחריותו","מאי לאו אע\"ג דמני לא דלא מני","ומי אמר רב הכי והאמר רב החזירו לעדר שבמדבר יצא אמר רב חנן בר אבא מודה רב ברקועתא","לימא כתנאי הגונב טלה מן העדר וסלע מן הכיס למקום שגנב יחזיר דברי רבי ישמעאל ר\"ע אומר צריך דעת בעלים","סברוה דכולי עלמא אית להו דרבי יצחק דאמר רבי יצחק אדם עשוי למשמש בכיסו בכל שעה מאי לאו בסלע לדעת ובפלוגתא דרב ושמואל","(לא) בטלה שלא לדעת ובפלוגתא דרב חסדא ור' יוחנן","אמר רב זביד משמיה דרבא בשומר שגנב מרשות בעלים כ\"ע לא פליגי כדרב חסדא והכא בשומר שגנב מרשותו שיחזיר למקום שגנב קמיפלגי ר\"ע סבר כלתה לו שמירתו ור' ישמעאל סבר לא כלתה לו שמירתו","לימא מנין פוטר תנאי היא דתניא הגוזל את חבירו והבליע לו בחשבון תני חדא יצא ותניא אידך לא יצא","סברוה דכ\"ע אית להו דר' יצחק דאמר אדם עשוי למשמש בכיסו בכל שעה ושעה מאי לאו בהא קמיפלגי דמ\"ד יצא סבר מנין פוטר ומאן דאמר לא יצא סבר מנין אינו פוטר","אמרי אי סבירא לן כר' יצחק כ\"ע לא פליגי דמנין פוטר אלא בדרבי יצחק קמיפלגי מר אית ליה דר' יצחק ומר לית ליה דר' יצחק","ואי בעית אימא דכ\"ע אית להו דר' יצחק ולא קשיא הא דמני ורמא ליה בכיסיה והא דמני ורמא לידיה","ואיבעית אימא אידי ואידי דמני ורמא בכיסיה הא דאית ליה זוזי אחריני בכיסיה הא דלית ליה זוזי אחריני בכיסיה:","\u0001מתני׳\u0002 אין לוקחין מן הרועים צמר וחלב וגדיים ולא משומרי פירות עצים ופירות","אבל לוקחין מן הנשים כלי צמר ביהודה וכלי פשתן בגליל ועגלים בשרון וכולן שאמרו להטמין אסור ולוקחין ביצים ותרנגולין מכל מקום:","\u0001גמ׳\u0002 ת\"ר אין לוקחין מן הרועים לא עזים ולא גדיים ולא גיזין ולא תלושין של צמר אבל לוקחין מהן תפורין מפני שהן שלהן ולוקחין מהן חלב וגבינה במדבר ולא בישוב","ולוקחין מהן ד' וה' צאן ד' וה' גיזין אבל לא שתי צאן ולא שתי גיזין","ר\"י אומר בייתות לוקחין מהן מדבריות אין לוקחין מהן כללו של דבר כל שהרועה מוכר ובעל הבית מרגיש בו לוקחין מהן אין מרגיש בו אין לוקחין מהן","אמר מר לוקחין מהן ד' וה' צאן ד' וה' גיזין השתא יש לומר ארבעה זבנינן חמשה מיבעיא א\"ר חסדא ארבעה מתוך חמשה ואיכא דאמרי א\"ר חסדא ארבעה מעדר קטן וחמש מעדר גדול","הא גופא קשיא אמרת ד' וה' צאן ד' וה' גיזין ד' וה' אין אבל שלש לא אימא סיפא אבל לא שתי צאן הא שלש זבנינן","לא קשיא הא בברייתא הא בכחישתא:","ר\"י אומר בייתות לוקחין מהן מדבריות אין לוקחין מהן כו': איבעיא להו ר\"י ארישא קאי ולחומרא או דלמא אסיפא קאי ולקולא","ארישא קאי ולחומרא דאמר לוקחין מהן ארבעה וחמשה צאן הני מילי בייתות אבל מדבריות אפילו ארבעה וחמשה לא או דלמא אסיפא קאי ולקולא דאמר אבל לא שתי צאן ולא שתי גיזין הני מילי מדבריות אבל בייתות שתים נמי לוקחין","ת\"ש דתניא ר\"י אומר לוקחין בייתות מהן ואין לוקחין מהן מדבריות ובכל מקום לוקחין מהן ארבעה וחמשה צאן"],[[0,"מ\"ט דרב חסדא","בשלמא טעמא דכולהו ניחא דעדיף להו לדעת משלא לדעת ועוד מתני' ניחא לתרוצי כוותייהו טפי:"],[0,"הואיל ואנקטה נגרי ברייתא","למדה לצאת חוץ ומעתה צריכה שימור יפה וכיון דלא ידעו בעלים לא מזדהרי בה אבל לדעת מנין פוטר שהרי הכירו שנגנבה והחזירה ומעכשיו יזהרו בה:"],[1,"האי מאן דחזייה לחבריה דאגבה אימרא מעדרא דידיה","כדי לגונבה:"],[2,"אע\"ג דמני","אלמא לדעת צריך דעת:"],[3,"החזירו לעדר","שיש לו לבעל הבית במדבר יצא ואע\"ג דליכא לא לדעת ולא מנין ורב לא סגי ליה בלאו חד מהני:"],[3,"ברקועתא","שהטלה ניכר הוא כשנגנב וניכר הוא לרועה במדבר כשניתוסף על צאנו ואפי' לא מנה:"],[5,"אית להו דרבי יצחק","והבעלים יודעין בגניבתו שמנו והיא חסירה ולאחר חזרה מנו והיא שלימה:"],[5,"מאי לאו בסלע","פליגי לדעת כדפרישית וידעו הבעלים בגניבתו וקאמר רבי ישמעאל מנין פוטר שאדם עשוי למשמש בכיסו ומנה והיא שלימה פטור וכשמואל דאמר לדעת מנין פוטר ור\"ע כרב דאמר לדעת צריך דעת:"],[6,"בטלה פליגי שלא לדעת ובפלוגתא דרב חסדא ור' יוחנן","דרבי ישמעאל דאמר למקום שגנב יחזיר כרבי יוחנן דאמר שלא לדעת אפילו מנין לא צריך ור\"ע כרב חסדא דאמר שלא לדעת צריך דעת:"],[7,"ה\"ג א\"ר זביד משמיה דרבא בגונב מרשות בעלים דכ\"ע לא פליגי","דסבירא להו כרב חסדא כדמפרש טעמא משום דאנקטה ניגרי ברייתא והכא בשומר שגנב מרשות עצמו עסקינן ובעי למפטר נפשיה מן הבעלים בטענת גניבה או אבידה וכ\"ע כרב חסדא דאמר שלא מדעת צריך דעת:"],[7,"ר\"ע סבר","כיון שנעשה גנב כלתה שמירתו דתו לא מהימן להו לבעלים דהא ה\"ל גונב שלא לדעת צריך דעת ולא אמרינן סגיא בדעת שומר והא איהו ידע בחזירתו:"],[7,"ורבי ישמעאל סבר","עדיין הוא שומר עליו וסגי בדעת דידיה:"],[8,"והבליע לו בחשבון","לאחר זמן לקח הימנו מקח וכשנתן לו דמים הוסיף עליהם מעות הגזילה והבליע בחשבון שהיה בוש לומר הרי גזילתך יצא:"],[9,"אדם עשוי למשמש","ולמנות כמה בכיסו וזה מיד מנה אחריו ומצא יותר מדמי המקח והכיר שהחזיר לו גזילתו:"],[10,"לית ליה דר' יצחק","וליכא מנין:"],[11,"והא","דקתני יצא דמני גזלן ורמא לכיסיה דנגזל וכיון דאית לן דר' יצחק מנין פוטר:"],[11,"הא","דקתני לא יצא דמני גזלן ורמא לידיה דנגזל הלכך איכא למימר דהשליכו זה לתיבתו ולא מנאן:"],[12,"אית ליה זוזי אחריני בכיסיה","ולא ידע כמה:"],[13,"מתני' אין לוקחין מן הרועים","דאיכא למימר שמא גנבו מצאנו של בעל הבית המסור להם:"],[14,"צמר ביהודה ופשתן בגליל","זו היא מלאכת הנשים והן עצמן עושות ומוכרות ולדעת בעליהן הוא:"],[14,"ועגלים","הרועים בשרון ברחבה לעין כל מאחר שמוכרין בפרהסיא לא גנבום. ל\"א שרון שם מקום ומקום גידול עגלים הוא ולוקחין עגלים בזול ומגדלין אותן ושלהן הן לשון זה עיקר דתניא במנחות בפרק כל קרבנות (מנחות דף פז.) אילים ממואב וכבשים מחברון עגלים משרון:"],[15,"גמ' ולא תלושין","שנתלש הצמר שעל הרחל מעט מעט:"],[15,"תפורים","בגדים תפורים דאי נמי גנבו קננהו בשינוי:"],[15,"חלב וגבינה במדבר","דאין דרך בעלים לילך שם וליטלם והרועה נטלן:"],[15,"אבל לא בישוב","שדרך להביאו לבית בעל הבית:"],[16,"ארבע וחמש צאן","שחסרונן ניכר בעדר ואין יכול לישמט ולומר זאב טרפה:"],[17,"בייתות לוקחין מהן","שהרי בעל הבית יודע מניינם:"],[17,"מרגיש","מבין:"],[18,"ארבע מתוך חמש","אם לא היה לו בעדר אלא חמש צאן ומוכר מהן ארבע מותר ליקח דכולי האי לא גניב מדבר מועט:"],[20,"בברייתא","בריאות עין בעל הבית תמיד עליהן ומרגיש בשלש:"],[20,"כחושות","אין חשובות לו ואין עינו עליהם לפיכך אין מרגיש כלומר אין יודע כשמוכרם זה:"],[21,"ארישא קאי","ארבע וחמש דשרי ת\"ק:"],[21,"אסיפא","שתי צאן דקאסר ת\"ק:"],[22,"ארבע וחמש צאן","שחסרונן ניכר בעדר ואין יכול לישמט ולומר זאב טרפה:"]],[[5,"מאי לאו בסלע כו' ובטלה שלא לדעת","סתם כיס רגיל להיות לדעת כיון שעשוי למשמש בכיסו וסתם טלה רגיל להיות שלא לדעת להכי נקט בהא לדעת ובהא שלא לדעת:"],[18,"חמש מבעיא","מפורש במס' שבת בפרק במה אשה (שבת דף ס: ושם ד\"ה השתא) גבי שמעתא דסנדל המסומר:"]]],[["מדאמר בכל מקום ש\"מ אסיפא קאי ולקולא ש\"מ:","ולא משומרי פירות כו': רב זבין שבישתא מאריסא א\"ל אביי והא תנן ולא משומרי פירות עצים ופירות א\"ל ה\"מ בשומר דלית ליה בגופא דארעא מידי אבל אריס דאית ליה בגוויה אימא מדנפשיה קא מזבין","ת\"ר שומרי פירות לוקחין מהן כשהן יושבין ומוכרין והסלין לפניהם וטורטני לפניהם וכולן שאמרו הטמן אסור לוקחין מהן מפתח הגינה אבל לא מאחורי הגינה","איתמר גזלן מאימת מותר לקנות הימנו רב אמר עד שתהא רוב משלו ושמואל אמר אפילו מיעוט שלו","אורי ליה רב יהודה לאדא דיילא כדברי האומר אפילו מיעוט שלו","ממון מסור רב הונא ורב יהודה חד אמר מותר לאבדו ביד וח\"א אסור לאבדו ביד","מ\"ד מותר לאבדו ביד לא יהא ממונו חמור מגופו ומ\"ד אסור לאבדו דלמא הוה ליה זרעא מעליא וכתיב (איוב כז, יז) יכין רשע וצדיק ילבש:","רב חסדא הוה ליה ההוא אריסא דהוה תקיל ויהיב תקיל ושקיל סלקיה קרא אנפשיה (משלי יג, כב) וצפון לצדיק חיל חוטא","(איוב כז, ח) כי מה תקות חנף כי יבצע כי ישל אלוה נפשו רב הונא ורב חסדא חד אמר נפשו דנגזל וח\"א נפשו של גזלן","מ\"ד נפשו של נגזל דכתיב (משלי א, יט) כן ארחות כל בוצע בצע את נפש בעליו יקח מ\"ד נפשו של גזלן דכתיב (משלי כב, כב) אל תגזול דל כי דל הוא ואל תדכא עני בשער כי ה' יריב ריבם וקבע את קובעיהם נפש","ואידך נמי הכתיב נפש בעליו יקח מאי בעליו בעליו דהשתא","ואידך נמי הכתיב וקבע את קובעיהם נפש מה טעם קאמר מה טעם וקבע את קובעיהם משום דקבעי נפש","א\"ר יוחנן כל הגוזל את חבירו שוה פרוטה כאילו נוטל נשמתו ממנו שנאמר כן ארחות כל בוצע בצע את נפש בעליו יקח ואומר (ירמיהו ה, יז) ואכל קצירך ולחמך בניך ובנותיך","ואומר (יואל ד, יט) מחמס בני יהודה אשר שפכו דם נקי בארצם ואומר (שמואל ב כא, א) אל שאול ואל בית הדמים על אשר המית את הגבעונים","מאי ואומר וכ\"ת נפש דידיה אבל נפש בניו ובנותיו לא ת\"ש בשר בניו ובנותיו","וכ\"ת הני מילי היכא דלא יהיב דמי אבל היכא דיהיב דמי לא ת\"ש מחמס בני יהודה אשר שפכו דם נקי (בארצכם) [בארצם]","וכ\"ת ה\"מ היכא דקעביד בידים אבל גרמא לא ת\"ש אל שאול ואל בית הדמים [על] אשר המית את הגבעונים וכי היכן מצינו שהרג שאול את הגבעונים אלא מתוך שהרג נוב עיר הכהנים שהיו מספיקין להן מים ומזון מעלה עליו הכתוב כאילו הרגן:","אבל לוקחין מן הנשים: ת\"ר לוקחין מן הנשים כלי צמר ביהודה וכלי פשתן בגליל אבל לא יינות ושמנים וסלתות ולא מן העבדים ולא מן התינוקות אבא שאול אומר מוכרת אשה בארבעה וחמשה דינר כדי לעשות כפה לראשה וכולן שאמרו להטמין אסור","גבאי צדקה לוקחין מהן דבר מועט אבל לא דבר מרובה","והבדדין לוקחין מהן זיתים במידה ושמן במידה אבל לא זיתים במועט ושמן במועט רשב\"ג אומר לוקחין מנשים זיתים במועד בגליל העליון שפעמים אדם בוש למכור על פתח ביתו ונותן לאשתו ומוכרת","רבינא איקלע לבי מחוזא אתו נשי דבי מחוזא רמו קמיה כבלי ושירי קביל מינייהו א\"ל רבה תוספאה לרבינא והתניא גבאי צדקה מקבלין מהן דבר מועט אבל לא דבר מרובה א\"ל הני לבני מחוזא דבר מועט נינהו:","\u0001מתני׳\u0002 מוכין שהכובס מוציא הרי אלו שלו והסורק מוציא הרי אלו של בעה\"ב כובס נוטל ג' חוטין והן שלו יתר מכן הרי אלו של בעה\"ב אם היה שחור ע\"ג הלבן נוטל את הכל והן שלו","החייט ששייר את החוט כדי לתפור בו ומטלית שהיא ג' על ג' הרי אלו של בעה\"ב מה שהחרש מוציא במעצד הרי אלו שלו ובכשיל של בעל הבית ואם היה עושה אצל בעה\"ב אף הנסרים של בעה\"ב:","\u0001גמ׳\u0002 ת\"ר לוקחין מוכין מן הכובס מפני שהן שלו הכובס נוטל שני חוטין העליונים והן שלו"],[[0,"מדקאמר בכל מקום","לוקחין ארבעה וחמשה אלמא האי דקמפליג בין בייתות למדבריות אשתי צאן פליג ולקולא קאי:"],[1,"שבישתא","חבילי זמורות: שומר שכרו הוא נוטל במעות ואין לו חלק בעצים אבל אריס חולק בזמורות ובעצים וביין:"],[2,"והטורטני","מאזנים גדולים ומוכרין פירות במשקל כדרך התגרים דכיון דמוכרין בפרהסיא לא גנבום:"],[3,"רוב","ממונו משלו בלא גזילה הולכין אחר הרוב ונהנין ממנו:"],[3,"אפילו מיעוט משלו","תלינן ואמרינן האי מידי דיהיב ליה מדידיה הוא:"],[4,"אדא","שם האיש:"],[4,"דיילא","שמש דרבנן:"],[5,"מסור","מלשין המוסר ממון חבירו לאנסים:"],[6,"חמיר מגופו","דקיימא לן בפרק שני דע\"ז (דף כו:) דמותר לאבד גופו בידים דקתני המינין והמסורות מורידין אותן לבור ולא מעלין:"],[7,"תקיל ושקיל","לנפשיה מדקדק בחלוקה ואינו מוותר מחלקו כלום לשון אחר מחצה היה נוטל ודרך שאר האריסין ליטול שליש:"],[7,"תקיל ויהיב","לרב חסדא:"],[7,"[קרא אנפשיה]","רב חסדא צדיק והאריס חוטא ונצפן חילו לרב חסדא דסלקו ונטל חלקו:"],[8,"כי ישל אלוה נפשו","משליך הקב\"ה נשמתו ומאבד ממנו נשמה אחת:"],[9,"אל תגזל דל כי דל הוא","אע\"פ שדל הוא ואין לו מה לגוזלו:"],[9,"אל תדכא עני בשער","מעשר עני ולקט שכחה ופאה המתחלקין בשעריך אל תדכאהו בם:"],[9,"וקבע את קובעיהם נפש","גוזל נפש גוזליהם:"],[10,"בעלים דהשתא","גזלן שנעשה עכשיו בעלים לממון:"],[12,"ואכל קצירך ולחמך","ודומה לך כאוכל בניך ובנותיך לפי שאין לך שוב במה לפרנסם:"],[13,"מחמס בני יהודה","מגזל שעשו מעלה אני עליהם כאילו שפכו דם נקי:"],[13,"המית הגבעונים","כדמפרש לקמיה שהמית כהני נוב שהיו מספקים מים ומזון לגבעונים שהגבעונים היו משמשין למזבח חוטבי עצים ושואבי מים ומעלה עליו כאילו המית הגבעוני':"],[14,"[אבל נפש בניו ובנותיו לא]","הא מאת נפש בעליו יקח לא נפקא לן אלא נפש הגוזל אבל בניו ובנותיו לא נענש גזלן אנפש בני הנגזל:"],[15,"[דלא יהיב דמי]","חמסן יהיב דמי וזה לא היה רוצה למכור:"],[17,"אבל לא יינות ושמנים וסלתות","שדרך האיש למוכרן ואין עושה את אשתו שליח לכך ושמא גנבתו מבעלה:"],[17,"כפה","צעיף ואין הבעל מקפיד:"],[19,"והבדדין","בעלי בית הבד שתגרין הן בשמן לוקחין מן נשיהם זיתים ושמן במדה כלומר דרך מכירה בפרהסיא ודבר מרובה דאין יכולה לגנוב כל זאת ולעשות בצינעא אבל לא במועט דגנבתו ויכולה לעשות בצינעא ולא ירגיש בעלה ל\"א במועט במעטן שנטלתן מן המעטן ואין דרך למוכרן כך:"],[19,"בגליל העליון","שהשמן שם ביוקר ומקפיד על דבר מועט:"],[20,"רבינא","גבאי צדקה היה:"],[20,"כבלי","שרשרות זהב:"],[20,"ושירי","צמידין:"],[20,"לבני מחוזא","עשירים הם:"],[21,"מתני' הכובס מוציא","מבגד צמר דבר מועט על ידי שטיפה ואין הבע\"ה מקפיד ומן הדין הן שלו והמקפיד לא הוי קפידא:"],[21,"שהסורק מוציא","ע\"י הקוצים שקורין קרדונ\"ש:"],[21,"סורק","פילונ\"ש כך שם האומנות על שם שהוא סורקו בקוצים כעין מסרק:"],[21,"של בעל הבית","שדבר חשוב הוא ולא מחיל:"],[21,"הכובס נוטל ג' חוטין","דרך אורגי בגדי צמר לארוג שלשה חוטין ממין אחר בסוף הבגד והכובס נוטלן ומשוה הבגד ומייפהו:"],[21,"ואם היה החוט שחור","שארגו בבגד לבן רשאי ליטול הכל לפי שהשחור מגנה את הלבן:"],[22,"החייט ששייר מן החוט כדי לתפור בו","ובגמרא מפרש שיעור תפירה:"],[22,"ה\"ג ומטלית שהוא ג' על ג'","חייט שהשוה את תפירתו וקיצע הימנה מטלית קטנה שלש אצבעות על שלש אצבעות הרי אלו של בעה\"ב:"],[22,"מעצד","דילדיי\"ר בלע\"ז קטנה ומחליק בה את הנסרים ושפאין שהוא משוה דקין הן טנב\"ש בלע\"ז:"],[22,"בכשיל","קרדום ומפיל שפאין גסין:"],[22,"אצל בעל הבית","שכיר יום:"],[22,"נסורת","אפי' דק דק היוצא מתחת המקדח שהיא דק מאד של בעל הבית ורישא בקבלן שקיבל לבנות הבית בדמים קצובים: גמ'"]],[]],[["ולא יטיל בו יותר משלשה חובין ולא יסרוק הבגד לשתיו אלא לערבו ומשויהו לארכו אבל לא לרחבו ואם בא להשוותו עד טפח רשאי","אמר מר שני חוטין והאנן תנן שלש לא קשיא הא באלימי והא בקטיני:","ולא יסרוק הבגד לשתיו אלא לערבו והתניא איפכא לא קשיא הא בגלימא הא בסרבלא:","ולא יטיל בו יותר משלשה חובין בעי רבי ירמיה אמטויי ואתויי חד או דלמא אמטויי ואתויי תרי תיקו:","ומשויהו לארכו אבל לא לרחבו והתניא איפכא לא קשיא הא בגלימא הא בהמיוני","ת\"ר אין לוקחין מן הסורק מוכין מפני שאינו שלו ובמקום שנהגו להיות שלו לוקחין ובכל מקום לוקחין מהן כר מלא מוכין וכסת מלאה מוכין מאי טעמא קננהו בשינוי","ת\"ר אין לוקחין מגרדי לא אירין ולא נירין ולא פונקלין ולא שיורי פקיעות","אבל לוקחין מהן בגד מנומר ערב ושתי טווי ואריג","אמרי השתא טווי שקלי ארוג מבעיא מאי אריג תיכי","ת\"ר אין לוקחין מן הצבע לא אותות ולא דוגמות ולא תלושים של צמר אבל לוקחין מהן בגד צבוע טווי בגדים השתא טווי שקיל בגדים מיבעיא מאי בגדים נמטי","ת\"ר הנותן עורות לעבדן הקיצועין והתלושין הרי אלו של בעל הבית והעולה ומשטף במים הרי אלו שלו:","אם היה שחור [וכו']: א\"ר יהודה קצרא שמיה וקצרא שקיל ליה אמר רב יהודה הכל עולין למנין תכלת ויצחק ברי קפיד עלייהו:","החייט ששייר (מן) [את] החוט כו': וכמה לתפור אמר רב אסי מלא מחט חוץ למחט איבעיא להו מלא מחט וחוץ למחט כמלא מחט או דלמא מלא מחט וחוץ למחט משהו","ת\"ש דתניא החייט ששייר את החוט פחות מכדי לתפור בו ומטלית שהיא פחותה משלש על שלש בזמן שבעל הבית מקפיד עליהן הרי אלו של בעל הבית אין בעל הבית מקפיד עליהן הרי אלו שלו","אי אמרת בשלמא מלא מחט וחוץ למחט כמלא מחט פחות מכאן חזי לסיכתא אלא אי אמרת מלא מחט וחוץ למחט משהו פחות מכאן למאי חזי","אלא ש\"מ מלא מחט וחוץ למחט כמלא מחט שמע מינה:","מה שהחרש כו': ורמינהי מה שהחרש מוציא במעצד והנפסק במגירה הרי אלו של בעל הבית והיוצא מתחת מקדח ומתחת רהיטני והנגרר במגירה הרי אלו שלו","אמר רבא באתרא דתנא דידן איכא תרתי חציני לרבתי קרי לה כשיל ולזוטרתי קרי לה מעצד באתרא דתנא ברא חד הוא דאיכא וקרו לה מעצד:","ואם היה עושה אצל כו': ת\"ר מסתתי אבנים אין בהם משום גזל מפסגי אילנות מפסגי גפנים מנקפי היגי מנכשי זרעים ועודרי ירקות בזמן שבעה\"ב מקפיד עליהם יש בהן משום גזל אין בעל הבית מקפיד עליהן הרי אלו שלו","א\"ר יהודה כשות וחזיז אין בהם משום גזל באתרא דקפדי יש בהן משום גזל אמר רבינא ומתא מחסיא אתרא דקפדי הוא","\u0001הדרן עלך הגוזל בתרא וסליקא לה מסכת בבא קמא\u0002"],[[0,"ולא יטיל בו יותר מג' חובין","דרך הסורקים לתת לולאות של טוי במחט לאורכו של בגד שמותחו בהן כשהוא נסרק וחובטו במקלות וכשנגמר ובולטין אותו מקום הלולאות שנמתח שם משוה אותן ונוטל אותן הקצועים לעצמו כדאמר לקמן ואשמועינן תנא שלא יתפרם לאותן לולאות בחזקה כדי שלא יכול למתחו יותר מדאי אלא ג' חבין יפיינ\"ץ בלעז ג' תפירות במחט:"],[0,"ומשויהו","מקום הבליטות שנמתח שם נוטל במספרים:"],[0,"אפילו עד טפח","ליטול ממנו רצועות רחבות טפח:"],[1,"אלימי","גסין שנים:"],[2,"גלימא","טלית העשויה לכל יום וכשהוא סורק לשתיו נוחה ליקרע מהר:"],[2,"סרבלא","עשוי. לכבוד ולנוי וכשהוא סורק לשתיו נאה יותר:"],[3,"ה\"ג אמטויי ואתויי חד או דלמא אמטויי ואתויי תרי","מנהג תופר אומן להוליך ולהביא המחט בבגד קודם שימשוך כל החוט וקא מבעיא ליה הנך ג' חוטין דקתני מי חשיבא הולכה והובאה חד דהוו להו ג' הולכות וג' הובאות א\"ד הולכה והובאה תרי חשיב להו:"],[4,"גלימא משויהו לארכו","כדפרישית לעיל:"],[4,"המיונא","אינו נראה אלא שני ראשיה התלויין לכך משוה לרחבה ב' ראשיה התלויין:"],[6,"אירין","דרך הגרדי להניח צמר בקנה של ערב כדי שלא יצא הערב מן הקנה לכאן ולכאן והוא של בעה\"ב:"],[6,"נירין","ליציי\"ץ:"],[6,"פקעיות","לוישיי\"ל:"],[6,"פונקלין","טריימ\"ש שעושין ליריעות הנארגות מעומד ואין עושין להו קנה כדרך הגרדין:"],[7,"בגד מנומר","כלומר אפילו מנומר בצבעים הרבה אע\"פ שרגלים לדבר שגנב הצמר מן בגדים שארג לוקחין מהן דקנינהו בשינוי:"],[7,"טווי אריג","והיינו אירין דאמרן לא יקח אם טלאן הגרדי לוקחין דקנינהו בשינוי:"],[8,"ארוג מבעי","הא ה\"ל טווי קודם לאריג:"],[8,"תיכי","שרשרות שרימ\"ש דלא טוואן קודם לכן:"],[9,"אותות","כשמביאין לו בגד לצבוע חותך ממנו מעט לפני בעליו לידע אם יקלוט את הצבע ופעמים שמעכבו אצלו ושכחו בעלים:"],[9,"דוגמאות","שמביאין לו הבעלים צמר לצבוע ומביא עמו מעט צמר צבוע ואומר כזה צבע לי:"],[9,"תלושי צמר","שתלש מן הגיזה הצמר מעט מעט:"],[9,"אבל לוקחין ממנו בגד צבוע","דבגד שלם לא גנב ואי נמי גנבו קנייה בשינוי:"],[9,"טווי ובגדים","והנך דוגמאות שטוואן או עשה מהן בגדים לוקחין:"],[9,"השתא טווי שקלינן בגדים מבעיא","הא אין בגדים אא\"כ טוואן:"],[9,"נמטי","לבדין פליטר\"ש בלע\"ז ואין שם טווי:"],[10,"הקיצועין","רונייור\"ש בלע\"ז שמקצע מן העור סביב:"],[10,"והתלושין","צמר התלוש מן העור:"],[10,"צמר העולה מן שטף המים שלו","דדבר מועט הוא ואפקורי מפקר ליה:"],[11,"קצרא שמיה וקצרא שקיל ליה","הכובס נקרא קצרי בלשון ארמי וקצרא שהוא מקצר מן הבגד איהו שקיל ליה ודידיה הוא:"],[11,"הכל עולין למנין תכלת","אותן שלשה חוטין אם לא קצרן הכובס עולין למדת מלא קשר גודל שצריך להרחיק את תכלת של ציצית משפת הבגד במסכת מנחות (דף מב.):"],[11,"קפיד עלייהו","ונוטלן:"],[12,"מלא המחט","מלא אורך המחט:"],[12,"וחוץ למחט","שכל זמן שאין מן החוט אלא מלא המחט מצומצם אין יכול לתוחבו בבגד: בברייתא גרסינן ומטלית שהיא פחותה מג' על ג':"],[14,"לסיכתא","חבין שפירשנו למעלה:"],[14,"פחות מכאן למאי חזי","הא אין יכול להפוך המחט ולתוחבו:"],[16,"מגירה","שייר\"ה בלע\"ז וסכין הוא שיש בו פגימות הרבה וקוצצת מהר:"],[16,"הנפסק במגירה","פסקי עצים שהעץ ארוך ופוסקו:"],[16,"מקדח","טרייד\"א והיוצא משם דק כעפר:"],[16,"רהיטני","פליינ\"א:"],[16,"והנגרר במגירה","דק דק שהיא משרת במקום חתך דק כעפר:"],[17,"חד הוא דאיכא","ורבתי היא ומשרת שפאי גסין:"],[18,"מסתתי אבנים","מרבע אותן ומחליק אותן:"],[18,"מפסגי אילנות","כשיש בהן ענפים יותר מדאי קוצץ אחת מבינתים והיינו פיסוג לשון דילוג והרחבה:"],[18,"ניקוף","שייך בהיגא כמו ונקף סבכי היער בברזל (ישעיהו י׳:ל״ד):"],[18,"היגא","סנה:"],[18,"ומנכשי זרעים","נוטלים ירקות מביניהם:"],[18,"ועודרי ירקות","כשהן תכופות יותר מדאי נוטל אחת מבינתים כדי שיהא מקום להרחיב ולהתפשט:"],[18,"היגא","סנה:"],[19,"חזיז","שחת של תבואה חטין ושעורין בעודן ירק:"],[19,"מתא מחסיא","מקום בהמות הוא וצריכין למרעה טוב:"]],[]]]};
